export const doctorNotes: Record<number, DoctorNote> = {
  1: { text: "A) No. Acetylsalicylic acid (aspirin, ASA) is not a drug used in the treatment of JIA. Its anti-inflammatory effect is used, for example, in the treatment of rheumatic fever.\nB) No, that's not it. Second-generation cephalosporin is an antibacterial drug - there are no indications for its use in JIA, which is an autoimmune inflammatory joint disease.\nC) This statement is false. Like cephalosporin, phenoxymethylpenicillin is an antibiotic and therefore is not effective in the treatment of JIA.\nD) Yes. Methotrexate, as a disease-modifying drug, is used as a first-line drug in the treatment of JIA. In case of contraindications to its use or lack of effectiveness, drugs such as sulfasalazine, cyclosporine A, chloroquine/hydroxychloroquine are used. These drugs reduce inflammation and inhibit the progression of the disease. Additionally, we use NSAIDs and glucocorticoids in the treatment of JIA.\nTherefore, the correct answer to the question is D.\nSource:\nWanda Kawalec, Ryszard Grenda, Helena Ziółkowska, Pediatrics, 2018, volume 2\nQuestion removed from CEM database - 2023-12-15", key: "D", consensusPct: 82, doctorsN: 7681, topic: "", konsyliumStem: "W leczeniu młodzieńczego idiopatycznego zapalenia stawów stosuje się:" },
  2: { text: "Primary pigmented adrenal nodular disease is a histologically benign form of bilateral adrenal hyperplasia that causes Cushing's syndrome with an overt or subclinical, permanent or cyclic course. It most often affects children and young adults, mainly women. It may occur in isolated form or as the main component of the Carney complex (multiglandular neoplasia) along with cardiac and cutaneous myxoma, mucosal and skin pigmentation, fibroadenomas of the mammary glands, testicular or ovarian tumors, thyroid tumors and pituitary adenomas. Both forms may be sporadic or familial, transmitted in an autosomal dominant manner, caused by an inactivating mutation of the PRKAR1A gene. The variety of clinical forms and the usually normal appearance of the adrenal glands in PPNAD on imaging tests may cause diagnostic difficulties. In most patients with PPNAD, in the high-dose dexamethasone test, instead of the lack of inhibition of cortisol secretion typical of ACTH-independent hyperadrenalism, a paradoxical, over 50% increase in cortisol secretion in urine is observed.\nThe issue goes beyond the required literature.\nSource: \"Primary pigmented nodular adrenal disease - case presentation\", Małgorzata Kumorowicz-Kopiec, Jerzy Starzyk, Katarzyna Doleżal-Ołtarzewska, Dorota Roztoczyńska, Małgorzata Chrupek, Andrzej Igor Prokurat, Grażyna Drabik; Department of Pediatric and Adolescent Endocrinology, Department of Pediatrics, Polish-American Institute of Pediatrics, Collegium Medicum of the Jagiellonian University, Kraków, Department and Clinic of Pediatric Surgery, Collegium Medicum. Ludwik Rydygier in Bydgoszcz, Nicolaus Copernicus University, Toruń Department of Pathomorphology, Polish-American Institute of Pediatrics, Collegium Medicum of the Jagiellonian University, Kraków", key: "C", consensusPct: 54, doctorsN: 14213, topic: "", konsyliumStem: "Wskaż fałszywe stwierdzenie dotyczące zespołu Carneya:" },
  5: { text: "Warning symptoms suggestive of primary immunodeficiency:\n- at least 4 ear infections per year\n- at least 2 sinusitis per year\n- antibiotic therapy lasting 2 months or longer with slight improvement in the clinical condition\n- at least 2 pneumonias per year\n- lack of weight gain and inhibition of normal development\n- repeated deep skin or organ abscesses\n- chronic mycosis of the oral cavity or skin in children after 1 year of age\n- the need for long-term treatment of infections with intravenous antibiotics\n- 2 or more severe soft tissue infections, including sepsis\n- family history indicating the occurrence of primary immunodeficiencies\nSource: \"Pediatria\" W. Kawalec, 2018, 2nd ed.; Volume II; Ch. 20.2.2", key: "A", consensusPct: 72, doctorsN: 12155, topic: "", konsyliumStem: "Które z poniższych problemów klinicznych mogą wskazywać na pierwotny niedobór odporności? 1) 6 ostrych zapaleń ucha środkowego w ciągu roku u dziecka 4-letniego; 2) 7 łagodnych epi" },
  9: { text: "MODY 2 diabetes is an autosomal recessive diabetes mellitus, caused by a mutation of the glucokinase gene, manifesting itself only by elevated fasting glucose. It is characterized by a mild course with no tendency to acidosis or ketosis and does not require treatment. Symptoms appear in people aged 15-35, and their clinical course is similar to type 2 diabetes. Unlike type 1, which always requires insulin, MODY patients can often take oral antidiabetic drugs.", key: "C", consensusPct: 76, doctorsN: 11671, topic: "", konsyliumStem: "Wskaż typ cukrzycy monogenowej dziedziczonej autosomalnie dominująco, w której pacjenci mają stabilnie podwyższone wartości glikemii na czczo i nie wymagają na ogół leczenia farmak" },
  10: { text: "Let's consider each answer:\nA) No - although fever occurs in the course of erythema infectiosum, HOWEVER, the skin lesions characteristic of this disease include: intense erythema, a garland-like, pink and fading rash from the inside on the trunk, as well as a PAPPULAR or HEMORRHAGIC rash (often painful and itchy) on the hands and feet.\nB) No. It is true that in primary contagious impetigo there is a vesicle on an erythematous base, which bursts to form a honey-colored scab. HOWEVER, most often this disease occurs WITHOUT GENERAL SYMPTOMS - i.e. without fever.\nC) No. In the course of HSV-herpes infection, painful blisters may form, but fever usually does not occur.\nD) Absolutely. Chickenpox is a disease caused by VZV, in which 95% of infections are symptomatic. In children, it most often begins with FEVER and the appearance of characteristic vesicular, itchy rash, which evolves into scabs (scarring may occur when the lesions are scratched). In vaccinated people, the course is often milder - sometimes there is no fever and fewer skin lesions.\nE) That's not it. In the course of measles, there is FEVER and, in the later phase of the disease, an rash - however, the characteristic and pathognomonic symptom of measles are COPLIC SPOTS (small, whitish lumps typically on the mucous membrane of the cheeks). As for skin changes - the rash is MOTIC or PAPULULAR in nature and does not form crusts (the rashes fade, leaving brown discolorations, and there is often a small, bran-like peeling of the skin).\nTherefore, the correct answer to the question is D.\nSource:\nAndrzej Szczeklik, Piotr Gajewski \"Interna Szczeklik\", Practical Medicine, 2022", key: "D", consensusPct: 83, doctorsN: 11448, topic: "pediatria / Choroby zakaźne", konsyliumStem: "Gorączka i swędząca pęcherzykowa wysypka z tworzeniem strupów do 7 dni to u dzieci objawy:" },
  12: { text: "In a child who experiences prolonged bleeding after a heel prick for preventive examinations, we should rule out coagulation disorders. The described case (male sex of the newborn, prolonged bleeding after examination of blood drops, formation of muscle hematomas) suggests hemophilia. For diagnostic purposes, we should conduct a detailed family interview and tests for coagulation factors, possibly DNA analysis.\nFurther diagnostics are necessary, both a subjective and physical examination. Because bleeding disorders may occur as genetically determined diseases, a family history is necessary. Parameters of the coagulation system should also be determined in order to differentiate the origin of the disorders. Prolonged but controlled bleeding or hematoma at the site of intramuscular injection is not an indication for the administration of fresh frozen plasma or repeated administration of Hello K.\nHowever, in the case of justified suspicion of hemophilia, it is an indication to administer vitamin K orally. This does not apply to the situation in the question because vitamin K has already been given.\nSource: Guidelines of the Polish Neonatological Society\nSource: Pediatrics. Lissauer (T. Lissauer, W. Carroll) ed. 5, ed. A. Milanowski, 2019, pp. 478–479.\nSource: Guidelines of the Polish Neonatological Society", key: "B", consensusPct: 88, doctorsN: 10895, topic: "pediatria / Choroby układu krążenia", konsyliumStem: "U noworodka płci męskiej, u którego po nakłuciu pięty do testów przesiewowych występuje przedłużone krwawienie, a po podaniu witaminy K w mięśniu powstał krwiak należy: 1) zlecić b" },
  15: { text: "The Coombs test is a test used in transfusionology aimed at detecting IgG antibodies using antiglobulin serum.\nA positive Coombs test indicates the presence of antibodies against red blood cell antigens and can usually be observed in cases of:\nconflicts in the main blood groups (1) and in the Rh range (2).\nIn the other conditions mentioned in the question, the Cooms test will typically be negative.\nTherefore, the correct answer to the problem is A (1,2).\nSource:\nhttps://www.mp.pl/interna/chapter/B16.II.15.19.3.2\nW.Kawalec, Pediatrics, 2018, Volume I, p. 67", key: "A", consensusPct: 54, doctorsN: 13316, topic: "", konsyliumStem: "U pacjenta, u którego stwierdza się hemolizę, dodatni odczyn Coombsa może wskazywać na: 1) konflikt w zakresie grup głównych; 2) konflikt w zakresie Rh; 3) hemoglobinopatię; 4) aty" },
  16: { text: "Bone softening in the parieto-occipital areas occurs in associated conditions\nwith chronic hyperphosphatemia (A), in osteogenesis imperfecta (C), in premature infants in case of osteopenia (B), in children with Down syndrome (E)\n, as well as in the case of hypervitaminosis A, congenital syphilis, calcium-phosphate metabolism disorders, rickets.\nD) In ​​children with Ehlers-Danlos syndrome, there is no softening of the bones in the parieto-occipital areas. This disease is characterized by excessive elasticity of the skin and joints.\nSo the correct answer to this question is D.\nSource:\nW.Kawalec, Pediatrics, 2018", key: "D", consensusPct: 58, doctorsN: 13523, topic: "pediatria / Choroby układu wydzielania wewnętrznego", konsyliumStem: "Rozmiękanie kości w okolicach ciemieniowo-potylicznych (craniotabes) może być obserwowane w poniższych przypadkach, z wyjątkiem:" },
  17: { text: "Conducting a spirometry test requires the patient's cooperation in performing maximum, forced exhalation, which is usually possible in the case of 5-6-year-old children. In practice, it is recommended to perform the test from the age of 6. In children >3. years of age who are not yet able to cooperate satisfactorily, respiratory resistance can be measured in specialist centers.\nBefore spirometry, drugs affecting bronchial motility should be discontinued (short-acting ß2-agonists: inhaled - 8 hours, orally - 12 hours; long-acting ß2-agonists - 12-24 hours; theophylline: short-acting - 12 hours, extended-release - 24-48 hours; ipratropium bromide - 8 hours)\nIn children, dynamic lung volume testing (FEV1, FVC) is most often performed - measured during forced exhalation and/or inhalation (flow-volume curve).\nThe FEV1 (forced expiratory flow in 1 sec) parameter - forced expiratory volume in one second - allows you to estimate the severity of bronchial obstruction.\nThe analysis of MEF25 and MEF50 (maximal expiratory flow for 25/50% FVC) - the maximum expiratory flow for 25/50% FVC remaining in the lungs - enables the assessment of flow in medium and small airways.\nThe bronchodilatory test is used to assess the reversibility of bronchospasm after administration of a short-acting beta-agonist and is positive in the case of an increase in FEV1 by at least 12% and/or FVC by 0.2 l after administration of the drug.", key: "E", consensusPct: 66, doctorsN: 12736, topic: "pediatria / Choroby układu oddechowego", konsyliumStem: "Wskaż fałszywe stwierdzenie dotyczące badań czynnościowych układu oddechowego u dzieci:" },
  20: { text: "The incubation period for hepatitis A is 15–50 days (average 30). The infectious period begins 1–2 weeks before the onset of clinical symptoms and ends approximately one week after their appearance (during this time the virus is excreted in the feces). In children, the course of the disease is very often asymptomatic or mild. In symptomatic cases, jaundice or cholestatic form may occur.\nIn the acute phase of infection, anti-HAV IgM antibodies are present in the serum, which may persist for up to 4–6 months, and are gradually replaced by anti-HAV IgG antibodies that remain for life.\nSource:\nhttps://www.mp.pl/interna/chapter/B16.II.7.1.1\n.", key: "B", consensusPct: 66, doctorsN: 12774, topic: "pediatria / Choroby zakaźne", konsyliumStem: "Przeciwciała IgM przeciwko wirusowemu zapaleniu wątroby typu A (anty-HAV IgM) u dzieci:" },
  22: { text: "Rheumatic fever is an autoimmune disease. Its symptoms appear\napprox. 2-6 weeks\nafter infection with group A B-hemolytic streptococcus.\nTherefore, the correct answer to this question is C.\nSource:\nhttps://www.mp.pl/interna/chapter/B16.II.2.14\n.\nhttps://www.mp.pl/pacjent/pediatria/choroby/152367,goraczka-reumatyczna", key: "C", consensusPct: 86, doctorsN: 10850, topic: "", konsyliumStem: "W jakim czasie po zakażeniu paciorkowcowym występują objawy gorączki reumatycznej?" },
  24: { text: "Beckwith-Wiedemann syndrome (BWS) is a genetic disorder characterized by excessive growth, a predisposition to cancer and congenital defects.\nPatients have an increased predisposition to developing cancers such as Wilms tumor, hepatoblastoma, neuroblastoma, and rhabdomyosarcoma during the first 8 years of life.\nTherefore, the correct answer to this question is C.\nAdditional information:\nThe disease may include macroglossia (causing feeding difficulties), hemihyperplasia and hypoglycemia, as well as other characteristic symptoms such as umbilical hernia/separation of abdominal muscles, bending of the earlobe and depression behind the ear, squamous hemangioma or other vascular malformations, enlargement of internal abdominal organs, fetal hypertrophy of adrenal cortex cells (pathognomonic symptom), abnormalities, heart defects, cardiomegaly.\nSource:\nhttps://www.orpha.net/data/patho/PL/ZespBeckwithaWiedemann-PLplAbs260.pdfzagiczenia\near lobe and depression behind the ear, squamous hemangioma or other vascular malformations, enlargement of internal abdominal organs, fetal hypertrophy of adrenal cortex cells (pathognomonic symptom), abnormalities, heart defects, cardiomegaly. Patients have an increased predisposition to developing cancers such as Wilms tumor, hepatoblastoma, neuroblastoma, and rhabdomyosarcoma during the first 8 years of life.\nhttps://www.orpha.net/data/patho/PL/ZespBeckwithaWiedemann-PLplAbs260.pdf", key: "C", consensusPct: 73, doctorsN: 11973, topic: "", konsyliumStem: "W zespole Beckwitha-Wiedemanna występuje podwyższone ryzyko rozwoju:" },
  27: { text: "Let's analyze the individual answers contained in the task:\n1) On the contrary - in the course of iron deficiency anemia there is an INCREASE in the total iron-binding capacity. This is due to the fact that in the face of a small pool of iron, the liver produces more transferrin to use it more effectively.\n2) Yes – iron deficiency inhibits the production of hemoglobin.\n3) No - in iron deficiency anemia, we most often observe an INCREASED percentage of erythroblastic cells in the marrow. This is due to the fact that due to the lack of a sufficient amount of iron, the maturation at the level of erythroblasts is inhibited and their accumulation is achieved (hence their number increases).\n4) Yes - in anemia, blood cells of various shapes may appear.\n5) No. Iron deficiency anemia is a microcytic anemia. Megaloblasts in the bone marrow may appear in the case of anemia due to vitamin B12 and B9 (folic acid) deficiency.\nTherefore, the correct answer in this problem is C – 2 and 4.\nSources:\nhttps://www.mp.pl/interna/chapter/B16.II.15.1.2\n.\nhttp://www.Czyteliamedyczna.pl/2088,niedokrzywstosci-niedoborowe-w-pierzym-kwartale-zycia.html", key: "C", consensusPct: 52, doctorsN: 13677, topic: "", konsyliumStem: "W przebiegu niedokrwistości z niedoboru żelaza stwierdza się: 1) zmniejszenie całkowitej zdolności wiązania żelaza; 2) obniżenie średniego stężenia hemoglobiny w krwince; 3) zmniej" },
  29: { text: "Hyperbilirubinemia and increased concentrations of transaminases and GGTP along with increased concentrations of pancreatic enzymes as well as pain in the right hypochondrium in a 12-year-old girl most likely indicate that cholelithiasis and/or choledocholithiasis is the cause of the symptoms. Cholelithiasis in children is rare. In the age group >3 years of age, it is more common in girls.\nShwachman-Diamond syndrome, i.e. congenital pancreatic lipomatosis, is a genetic cause of exocrine pancreatic insufficiency - the secretion of pancreatic enzymes is impaired. This is accompanied by changes in the musculoskeletal system (narrow chest, abnormalities of the knee and hip joints, decreased bone density, slower growth, short stature).\nWilson's disease - a genetic disease with impaired copper metabolism in the body. Copper accumulates in the liver, cornea, brain and kidneys because it is not secreted properly into the bile. The symptoms include hepatitis (and/or cirrhosis) and neuropsychiatric disorders.\nHepatitis A infection can often be non-jaundic. The main symptoms include: fatigue, nausea, vomiting, and abdominal pain. The concentrations of transaminases and, in the cholestatic form, also GGTP increase. Amylase and lipase levels are not elevated.\nHemolytic uremic syndrome is most often secondary to Shigella spp. infection. Thrombotic microangiopathy with severe hemolytic anemia, thrombocytopenia and impaired renal function. It is usually preceded by symptoms of a bacterial infection (e.g. diarrhea, symptoms of a UTI).", key: "B", consensusPct: 80, doctorsN: 12105, topic: "pediatria / Gastroenterologia", konsyliumStem: "Dziewczynka w wieku 12 lat została przyjęta do oddziału z powodu ostrego napadowego bólu brzucha zlokalizowanego w nadbrzuszu i podżebrzu prawym, promieniującego do prawego boku, k" },
  30: { text: "In case of fever in a 2-month-old child, it is recommended to use paracetamol in a single dose of 10 to 15 mg/kg body weight.\nTherefore, the correct drug substance and dose are included in answer D.\nParacetamol requires regular administration every 4 hours, not exceeding a dose of 60 mg/kg/day.\nAccording to the SmPC, the use of ibuprofen (proposed in the other answers) is possible in children after the age of 3 months (dose of 20-30 mg/kg body weight per day, in 3-4 divided doses).\nSource:\nPediatrics in the practice of a primary care physician edited by Anna Dobrzańska, Łukasz Obrycki, Piotr Socha, 2022\nhttp://chpl.com.pl/data_files/2012-06-11_Panadol_dla_dzieci-ChPL.pdf\nhttps://www.ibufen.pl/files/Ulotki/Ibufen%20FORTE%20trusk_SPC_24_05_2017.pdf", key: "D", consensusPct: 79, doctorsN: 11697, topic: "pediatria / Farmakoterapia", konsyliumStem: "Jaki lek przeciwgorączkowy można podać dwumiesięcznemu dziecku?" },
  31: { text: "Common causes of gastrointestinal bleeding in infants include:\n- from the lower section - bacterial infections of the gastrointestinal tract, injuries, Meckel's diverticulum, food allergies, intussusception, anal fissure, intestinal duplication.\n- from the upper section - peptic ulcer, esophagitis and gastritis, congenital defects and vascular dysplasia.\nSource: Wanda Kawalec, Ryszard Grenda, Helena Ziółkowska (ed.): Pediatria, volume 1-2, Warsaw 2013, Wydawnictwo Lekarskie PZWL", key: "B", consensusPct: 62, doctorsN: 13127, topic: "", konsyliumStem: "Do najczęstszych przyczyn krwawień z dolnego odcinka przewodu pokarmowego u niemowląt należą: 1) choroba Schoenleina-Henocha; 2) szczelina odbytu; 3) alergie pokarmowe; 4) nieswois" },
  33: { text: "For newborns and young infants, whooping cough can be life-threatening.\nThe only effective post-exposure prophylaxis for pertussis is to administer a macrolide antibiotic to people in close contact with the patient, and\nin newborns and infants up to 5 months of age the drug of choice is azithromycin\n, used for 5 days.\nTherefore, the correct answer to the question is B.\nWhy not the other answers?\nA) Some sources mention weaning the baby from the breast of a mother suffering from pertussis (no mention of 2 weeks of weaning), but this is not a key element of post-exposure management.\nC) Ceftriaxone is not the drug of choice in this clinical situation.\nD) For primary prevention, we use mandatory DTP vaccination for infants (registered after the age of 6) - in the described case, however, we are dealing with the choice of POST-EXPOSURE treatment.\nE) According to the procedure in the described case, the newborn is not given an infusion of immunoglobulins.\nSource:\nhttps://www.mp.pl/szkolenia/ekspert/blonica_tezec_krztusiec_ekspert/198218,powiedz-komu-i-w-jakim-celu-zaleca-sie-profilaktyczne-antybiotyk-po-ekspozycji-na-krztusiec\nhttps://podyplomie.pl/pediatria/25185,krztusiec-rozne-objawy-i-aktualnie-zalecane-postepowanie?page=4", key: "B", consensusPct: 66, doctorsN: 12961, topic: "pediatria / Choroby zakaźne", konsyliumStem: "U matki 3-tygodniowego noworodka lekarz rodzinny stwierdza krztusiec. Wskaż prawidłowe postępowanie w opisanej sytuacji:" },
  35: { text: "According to the 2020 Protective Vaccination Program published by the National Institute of Hygiene, the H. influenza type B vaccination scheme assumes:\nin children vaccinated at the age of 1 - three doses of basic vaccination administered at 6-8 week intervals and a fourth dose of basic vaccination (supplementary) administered at the 2nd year of life.\nto vaccinated children aged 6 to 12 months, the first two doses of basic vaccination should be administered 6-8 weeks apart, then the third dose of basic vaccination (supplementary) one year after the second dose.\nchildren over 1 year of age should be given one dose of the vaccine.\nalternatively, the DTaP-IPVHib combination vaccine may be used.\nThe vaccine against Hib infections is intended for children from 6 weeks to 5 years of age and older children from risk groups, e.g. after removal of the spleen.\nIn the case of a 7-year-old child who does not belong to a risk group, there are no indications for this vaccination.\nTherefore, the correct answer to the question is E.\nSource:\nNational Institute of Hygiene Vaccination Program:\nhttps://szkolenia.pzh.gov.pl/kalendarz-szczeien-2020/", key: "E", consensusPct: 77, doctorsN: 11892, topic: "", konsyliumStem: "Rodzice zgłaszają się do pediatry z 7-letnim dzieckiem urodzonym za granicą, które nigdy nie było szczepione przeciwko Haemophilus influenzae typu b, w celu uzupełnienia tego szcze" },
  36: { text: "The family doctor's visit should take place within 4 weeks after the child is discharged from the neonatal unit (high-risk groups already in the 1st week). Subsequent visits include a medical examination of the infants. They are carried out on the following vaccination dates: 3–6. week of life, 3–4, 6, 9 and 12 months of life.\nSource: Latkowski B., Lukas W., Godycki-Ćwirko M. and others. \"Family Medicine\", Wydawnictwo Lekarskie PZWL, Warszawa 2017, pp. 355, 414–415.", key: "A", consensusPct: 80, doctorsN: 11368, topic: "", konsyliumStem: "Badania bilansowe dziecka do ukończenia pierwszego roku życia należy przeprowadzić:" },
  40: { text: "Symptoms of strep throat include:\n- severe sore throat\n- fever >38°C\n- nausea, vomiting, abdominal pain\n- headache\n- enlarged cervical lymph nodes\n- exudate on the tonsils\nThese symptoms are included in D - this is the correct answer to the question.\nWhat leads us away from the other answers?\nA) Low-grade fever, severe sore throat, cough, runny nose - this set of symptoms is characteristic of a VIRAL INFECTION, while streptococcal angina is a bacterial infection.  Angina usually occurs with a fever >38°C. Runny nose and cough are symptoms that may accompany both viral infections (dry cough, viral rhinitis) and bacterial infections (wet cough, bacterial rhinitis), but the overall clinical picture presented in the answer does not describe the typical course of streptococcal angina.\nB) Severe sore throat, headache passion for the clinical picture of streptococcal angina, however, usually in the course of this disease the patient has a fever >38°C, therefore the MORE CORRECT answer will be D.\nC) Among those mentioned, dysuria symptoms are not characteristic of the clinical picture of streptococcal angina.\nE) Among those listed, the symptoms included in answer D are the characteristic symptoms of streptococcal angina.\nSource:\nhttps://www.mp.pl/interna/chapter/B16.II.3.3", key: "D", consensusPct: 76, doctorsN: 11644, topic: "", konsyliumStem: "Objawy charakterystyczne dla anginy paciorkowcowej to:" },
  41: { text: "Criteria for growing pains:\n- usually occur between the ages of 4-12,\n- the pain is periodic, does not occur every day,\n- occurs in the afternoon or evening, never in the morning,\n- it is symmetrical, usually covers the front part of the tibia, never covers the joints,\n- the child's gait is normal,\n- no abnormalities were found in physical and laboratory tests.\nFamily history is irrelevant.\nSource: Pediatrics. Vol. 1-2. Wanda Kawalec, Ryszard Grenda, Helena Ziółkowska, Warsaw, Wydawnictwo Lekarskie PZWL, 2013", key: "D", consensusPct: 70, doctorsN: 12281, topic: "pediatria / Rozwój fizyczny i motoryczny dzieci i młodzieży", konsyliumStem: "Które z poniższych nie jest kryterium diagnostycznym bólów wzrostowych u dzieci (wg Petersson i Mellson)?" },
  43: { text: "In children, the most common cause is\nretinopathy of prematurity.\nTherefore, the correct answer to the question is C.\nIt is also worth remembering that cataracts are one of the most common causes of vision loss in the general population.\nSource:\nA.Dobrzańska, Pediatrics, Manual for the Medical Final Examination and State Specialization Examination LEK, 2014, p.928", key: "C", consensusPct: 80, doctorsN: 11236, topic: "", konsyliumStem: "Najczęstszą przyczyną utraty widzenia u dzieci w Polsce jest/są:" },
  44: { text: "Primary hypoparathyroidism is a disease with hypocalcemia and hyperphosphatemia, caused by a primary deficiency or absence of parathyroid hormone (PTH) or the secretion of biologically inactive PTH. Reasons:\n1) Removal of the parathyroid glands during thyroidectomy or other neck surgery;\n2) Destruction of the parathyroid glands due to thyroiditis, thyroid irradiation, deposition of iron (hereditary hemochromatosis), copper (Wilson's disease), or amyloid (amyloidosis), neck trauma, autoimmune process (APS-1/ APS-2)\n3) Congenital defects - lack of parathyroid glands (DiGeorge syndrome), congenital hypoparathyroidism inherited in a sex-linked or autosomal manner.\nMutations that inactivate Ca-SR, occurring in familial benign hypocalciuric hypercalcemia (FBHH) and causing neonatal malignant hyperparathyroidism syndrome (FNHP), block signal transfer to parathyroid cells, resulting in excessive PTH synthesis, which is the cause of symptoms of hyperparathyroidism. The monoallelic mutation has symptoms of familial hypocalciuric hypercalcemia, while the biallelic mutation has symptoms of severe neonatal hyperparathyroidism syndrome.\nSource: Small manual \"Interna Szczeklika 2019/20\", 11th edition, Chapter 14.4.2\n\"Advances in research on calcium-phosphate metabolism - part II\"; Edward Franek, Franciszek Kokot\nA question that partially goes beyond the source material", key: "E", consensusPct: 60, doctorsN: 13520, topic: "pediatria / Choroby układu wydzielania wewnętrznego", konsyliumStem: "Niedoczynność przytarczyc występuje w poniższych stanach chorobowych, z wyjątkiem:" },
  45: { text: "Kidney stones are the presence of insoluble deposits in the urinary tract, resulting from the precipitation of chemical substances contained in urine when their concentration exceeds the solubility threshold. The main risk factors are: high concentration of lithogenic substances in urine (oxalates - hyperoxaluria, calcium - hypercalciuria, phosphates - hyperphosphaturia, uric acid - hyperuricosuria, cystines - hypercystinuria), reduced excretion of citrate - hypocitraturia and magnesium - hypomagnesuria, urinary stasis, UTI.\nSource: Interna Szczeklika 2017/2018, p. 905;\nhttp://www.oil.org.pl/xml/oil/oil50/gazeta/numery/n2005/n200502/n20050210", key: "D", consensusPct: 70, doctorsN: 12214, topic: "", konsyliumStem: "Do czynników ryzyka kamicy układu moczowego nie należy:" },
  46: { text: "The teenager experienced symptoms of hypoglycemia caused by increased glucose consumption during physical exercise.\nAccording to the current (2018) recommendations of the Polish Diabetes Association, the treatment of choice in such a situation is a quick supply of simple carbohydrates. Next, intramuscular administration of glucagon should be considered.\n\"In the treatment of hypoglycemia in a conscious patient (with a glucose concentration ≤ 70 mg/dl), it is crucial to administer 15-20 g of glucose or other carbohydrates orally. If the glucose measurement after 15 minutes still indicates hypoglycemia, the treatment should be repeated. After the hypoglycemia subsides, the patient should eat a snack/meal to prevent recurrence of hypoglycemia\"\n\"consider administering glucagon subcutaneously or intramuscularly, train the patient's relatives in the administration of glucagon\"", key: "B", consensusPct: 93, doctorsN: 10364, topic: "", konsyliumStem: "Nastoletni chłopiec chorujący na cukrzycę typu 1, leczony insuliną, w czasie wycieczki rowerowej nagle poczuł osłabienie, kołatanie serca, drżenie rąk. Co powinien zrobić w pierwsz" },
  47: { text: "In children, foods that are more likely to cause an allergic reaction are chicken eggs, cow's milk, peanuts, gluten (wheat), soy and seafood. It is with these foods that a food challenge is most often performed, which (preferably performed in a double-blind, placebo-controlled trial) is the gold standard for diagnosing food allergies.\nIt is used for:\n- demonstrating correlation between observed clinical symptoms and consumed food,\n- confirmation of the initial diagnosis,\n- demonstrating the tolerance threshold after a previous period of using the elimination diet.\nIn children after anaphylaxis, a food challenge test is usually performed after 6-12 months.\nThe test should be performed on an empty stomach, we always challenge with one food at a time.\nSource: J.J. Pietrzyk, H. Szajewska, J. Mrukowicz (ed.): ABC of procedures in pediatrics, Medycyna Practical 2010", key: "E", consensusPct: 70, doctorsN: 12242, topic: "pediatria / Choroby alergiczne", konsyliumStem: "Wskaż fałszywe stwierdzenie dotyczące prowokacji pokarmowej (PP), będącej uznanym narzędziem diagnostycznym w alergii pokarmowej:" },
  49: { text: "Infectious mononucleosis is a disease caused by infection with the Epstein-Barr virus. Older children, and less often younger ones, may develop a disease syndrome consisting of:\n- fever\n- feeling unwell\n- inflammation of the throat and palatine tonsils - often severe, limiting fluid and food intake; in rare cases, breathing disorders may occur\n- enlarged lymph nodes - most often in the neck, often with generalized lymphadenopathy.\nOther symptoms include:\n- petechiae in the soft palate\n- enlargement of the spleen and liver\n- maculopapular rash\n- jaundice.\nSymptoms last for 1-3 months but eventually disappear. The main symptom in adolescents and adults is often chronic general fatigue. Treatment is symptomatic.\nSource: \"Pediatria\" 5th edition, Tom Lissauer, 2019, Ch. 15", key: "A", consensusPct: 79, doctorsN: 11349, topic: "", konsyliumStem: "Zespół przewlekłego zmęczenia (chronic fatigue syndrome) jest powikłaniem:" },
  50: { text: "The symptoms described in the question are characteristic features\nWiskott-Aldrich syndrome.\nIt is an X-linked inherited syndrome that occurs in boys. The first symptoms appear in early childhood.\nTherefore, the correct answer to the question is E.\nWhat about the other answers?\nA) Characteristic symptoms of Nijmegen Syndrome include microcephaly, bird face, cafe au lait spots, and stunted growth and weight gain.\nB) Hyper IgE syndrome is characterized by the occurrence of a typical triad of symptoms: increased concentration of IgE immunoglobulins, recurrent infections of the respiratory system and sinuses (most often of staphylococcal etiology) and the occurrence of cold skin abscesses since childhood.\nC) Typical symptoms of Bloom's syndrome include stunted growth, low body weight, a bird-like appearance of the face, and erythema telangiectatic, which increases with exposure to sunlight.\nD) Netherton syndrome is a rare genetically determined dermatosis manifesting itself with primary immunodeficiency.\nSource:\nW.Kawalec, Pediatrics, 2018, Volume II, pp. 1196–1199\nhttps://journals.viamedica.pl/advances_in_respiratory_medicine/article/viewFile/27992/22806", key: "E", consensusPct: 71, doctorsN: 12334, topic: "pediatria / Genetyczne uwarunkowania chorób", konsyliumStem: "U pacjenta z nawracającymi infekcjami, skazą krwotoczną małopłytkową (która wystąpiła w pierwszym półroczu życia) i wypryskiem skórnym (o charakterze atopowego zapalenia skóry) nal" },
  53: { text: "​​​​​\nSource: \"Pediatria\" 5th edition, Tom Lissauer, 2019, Ch. 2", key: "C", consensusPct: 64, doctorsN: 13067, topic: "pediatria / Rozwój fizyczny i motoryczny dzieci i młodzieży", konsyliumStem: "Częstość oddechów u zdrowego, czuwającego dziecka w drugim roku życia nie powinna przekraczać:" },
  54: { text: "Vesicoureteral reflux is found in 70% of children with UTI.\nIt is a congenital condition that may run in families (50% of children whose mothers had reflux). It is often a defect secondary to subvesical obstruction, it occurs in 50% of neurogenic bladders, more often in the case of duplication of ureters. It may occur unilaterally.\nSource: Pediatrics – Manual for the State Medical Examination and Specialization Examination, Ed. Anna Dobrzańska and Józef Ryżko, Urban i Partner 2014", key: "C", consensusPct: 89, doctorsN: 10701, topic: "", konsyliumStem: "Wskaż prawdziwe stwierdzenie dotyczące odpływów pęcherzowo-moczowodowych:" },
  55: { text: "The criterion for prematurity is the duration of pregnancy, not the baby's weight.\nA normal pregnancy lasts 38-42 weeks of pregnancy, i.e. 280 days +/- 20 days.\nA premature baby is a baby born from a pregnancy that did not last the full 38 weeks.", key: "E", consensusPct: 80, doctorsN: 11238, topic: "", konsyliumStem: "Noworodek urodzony przedwcześnie to noworodek z ciąży trwającej krócej niż:" },
  58: { text: "Somatotropin hypopituitarism may be congenital or acquired. The congenital causes of the disease are usually caused by genetic defects that disturb the production or secretion of growth hormone or by organic changes within the central nervous system. Another possible cause is tumors of the hypothalamic-pituitary region, most often craniopharyngioma. Symptoms of increased intracranial pressure caused by the mass of the tumor may be part of the clinical picture of hypopituitarism.\nOther symptoms of this condition include:\n- hypoglycemia,\n- prolonged neonatal jaundice,\n- short stature,\n- growth rate deteriorating with age.\nSource: Growth hormone deficiency in children and young adults,\nAdvances in Hygiene and Experimental Medicine, Oświęcimska J, 2016", key: "E", consensusPct: 53, doctorsN: 14086, topic: "pediatria / Diagnostyka prenatalna", konsyliumStem: "Objawy kliniczne, które mogą być stwierdzane u dziecka z niedoczynnością przedniego płata przysadki w zakresie wytwarzania hormonu wzrostu (z tzw. somatotropinową niedoczynnością p" },
  59: { text: "Severe combined immunodeficiency (SCID) is a group of severe immune disorders. It occurs rarely, the most common form approximately 1:100,000 births. The defect affects both B and T lymphocytes.\nIt is characterized by abnormal development of the child, severe, generalized infections and accompanying autoimmune diseases. Untreated children die in the first two years of life.\nThe treatment consists of infection prevention and administration of immunoglobulins. The only option for permanent treatment is hematopoietic stem cell transplantation.\nSource: Pediatrics, Editors: Kawalec Wanda, Grenda Ryszard, Ziółkowska Helena, 2014, PZWL", key: "B", consensusPct: 71, doctorsN: 12351, topic: "pediatria / Choroby układu wydzielania wewnętrznego", konsyliumStem: "Wskaż prawdziwe stwierdzenia dotyczące ciężkiego złożonego niedoboru odporności (severe combined immunodeficiency SCID): 1) to genetycznie uwarunkowany brak obecności lub funkcji l" },
  62: { text: "Adrenoleukodystrophies are a group of diseases caused by defects in peroxisomes, which are the basic organelles in the cellular metabolism of fatty acids. Their different forms are:\n- neonatal - part of Zellweger spectrum diseases, presenting with hypotonia, feeding disorders, convulsions and a characteristic facial appearance\n- X-linked adrenoleukodystrophy - the most common peroxisome disease, occurring 1:20,000. Caused by mutations in the gene responsible for the import of very long-chain fatty acids (VLCFA) into peroxisomes. The result is damage to the adrenal glands, brain and myelin. Very high concentrations of VLCFAs are found in the blood. The disease has two forms:\na) childhood cerebral form - affects boys aged 4-12. Symptoms include difficulties with schoolwork, behavioral disorders, developmental regression, ataxia and adrenal insufficiency. If diagnosed early, the disease can be treated with stem cell transplantation.\nb) adrenomyeloneuropathy - occurs in boys, and much less frequently in girls, slowly progressing spastic paralysis and disorders of the sensory spinal cord\nc) Addison's disease - may be the only symptom of the disorder.\nSource: \"Pediatria\" 5th edition, Tom Lissauer, 2019, Ch. 29", key: "A", consensusPct: 65, doctorsN: 12434, topic: "", konsyliumStem: "7-letni chłopiec pozostaje pod opieką psychiatry z powodu nadpobudliwości psychoruchowej i zaburzeń uczenia się. W ostatnim czasie zaburzenia zachowania pogłębiały się, pojawił się" },
  63: { text: "Indications for hospitalization in pneumonia:\n• age < 6 months\n• hypoxemia (saturation < 92%)\n• tachypnea – in infants > 70/min; in older children > 50/min\n• severe general condition, dehydration\n• cardiorespiratory failure\n• neurological symptoms\n• chronic diseases, e.g. diabetes, cancer, immune disorders, kidney or liver diseases\n• granulocytopenia\n• extensive changes on chest x-ray\n• complicated pneumonia, e.g. pleural effusion, lung abscess\n• social indications\nStreptococcus agalactiae is a common etiological factor of pneumonia in children from 1 to 21 days of age, and in children over 5 years of age, the most common etiological factor of pneumonia is Streptococcus pneumoniae.\nSource: \"Pediatria\" W. Kawalec, 2018, 2nd ed.; Volume I; Ch. 9.3.3", key: "A", consensusPct: 84, doctorsN: 11124, topic: "", konsyliumStem: "Wskaż prawdziwe stwierdzenie dotyczące zapaleń płuc u dzieci:" },
  65: { text: "Changes in the cerebrospinal fluid typical of viral STI include:\n1. cytosis 100-1000 /ul with mononuclear cells dominating\n2. protein: slightly increased or normal (N: 117 mmol/l).\n5. Lactic acid: normal or increased (N:<2.1 mmol/l)\n6. Appearance: water-light, clear.", key: "C", consensusPct: 78, doctorsN: 11614, topic: "", konsyliumStem: "Badanie płynu mózgowo-rdzeniowego wykonane u 15-letniego dziecka wykazało: pleocytozę 420 /µl, 86% limfocytów, erytrocyty 3/µl, stężenie glukozy 61 mg/dl, stężenie białka 46 mg/dl," },
  66: { text: "Hepatitis A is an acute liver disease classified as a \"disease of dirty hands\", depending on the sanitary condition of the area, living conditions and hygiene rules of the population. It spreads through the gastrointestinal tract (fecal-oral). The incubation period is from 14 to 42 days, and the infectivity is 14-21 days before the onset of jaundice and 5-7 days after its appearance. In 70% of children, the course is asymptomatic or mild, which increases the risk of spreading the disease. The dominant symptoms include dyspeptic symptoms, abdominal pain and bloating, vomiting, and periodic diarrhea or constipation. Other symptoms include fever, upper respiratory tract inflammation, weakness and joint pain. Some patients notice dark urine and discolored stools. Treatment of hepatitis A is symptomatic and consists of a restful lifestyle, regular nutrition and an easily digestible diet. Patients with suspected liver failure, diagnostic difficulties and complications require hospital treatment.\nSource: \"Pediatria\" W. Kawalec, 2018, 2nd ed.; Volume II; Chapter 19.7.8", key: "D", consensusPct: 75, doctorsN: 11714, topic: "", konsyliumStem: "Okres inkubacji wirusowego zapalenia wątroby typu A u dzieci wynosi:" },
  69: { text: "Leprechaunism (dwarfism, Donohue syndrome): a rare, genetically determined disease inherited in an autosomal recessive manner, children usually die within the first few years of life. The clinical picture is dominated by insulin resistance, grayish color and excessive hair growth of the skin, and elf-like facial features (large, widely spaced eyeballs, saddle-shaped nose, large low-set auricles, prominent lips). There is also a lack of subcutaneous fat tissue. In all other cases mentioned in the question, obesity is observed. The question goes beyond the required literature.\nSource:\nhttps://www.mp.pl/insulinoterapia/polecane_artykuly/111651,wadliwy-zamek-niczy-dunek-receptora-insulinowego", key: "B", consensusPct: 75, doctorsN: 11641, topic: "", konsyliumStem: "Przyczyną otyłości u dzieci nie jest:" },
  73: { text: "The interval between the MMR vaccine and the planned pregnancy according to the Protective Vaccination Program for 2016 (also for 2018) should be 4 weeks.", key: "B", consensusPct: 79, doctorsN: 11384, topic: "", konsyliumStem: "Jaki jest według Programu Szczepień Ochronnych minimalny odstęp pomiędzy podaniem skojarzonej szczepionki przeciw odrze, śwince i różyczce a planowaną ciążą wymagany z uwagi na teo" },
  75: { text: "Folic acid is necessary for the proper development of the fetus, especially its nervous system. During pregnancy, a diet rich in folic acid is not enough, its supplementation is also necessary. According to current knowledge, it is recommended:\n1. in all women of reproductive age, the use of folic acid at a dose of 0.4 mg/d in the form of supplements, as a complement to a natural diet rich in folate,\n2. in the first trimester (up to the 12th week of pregnancy) use of folic acid at a dose of 0.4-0.8 mg/d,\n3. after the 12th week and during breastfeeding in the population of women without additional risk factors, the use of folic acid at a dose of 0.6-0.8 mg/d,\n4. in patients with a positive history of NTD in a previous pregnancy, use 4 mg/d of folic acid at a strictly defined time, i.e. at least 4 weeks before the planned conception and for the first 12 weeks of pregnancy, and then reduce the dose as in the general population,\n5. in women at increased risk of folate deficiency and neural tube defects, i.e.: n suffering from type I or II diabetes before pregnancy, n using antiepileptic drugs during or before pregnancy, methotrexate, cholestyramine, metformin, sulfadiazine, n using stimulants, n with renal or liver failure, n with BMI>30, n after bariatric surgery or with gastrointestinal diseases resulting in absorption disorders (Crohn's disease, ulcerative colitis, celiac disease), the use of folates (folic acid and/or active folates) at a dose of 0.8 mg/d at least 3 months before the planned conception and during pregnancy and breastfeeding\nSource: Recommendations of the Polish Society of Gynecologists and Obstetricians regarding supplementation in pregnant women, 2020", key: "D", consensusPct: 84, doctorsN: 10972, topic: "", konsyliumStem: "Do czynników mogących zaburzać wzrastanie płodu nie należy:" },
  76: { text: "In children with vasovagal syncope, non-pharmacological treatment is the basis. The main goal of treatment is to prevent recurrence of fainting and associated injuries, as well as to improve their quality of life. The essence of the procedure is to explain to the child and parents the cause of fainting and to recommend what to do in the event of prodromal symptoms and fainting. It is primarily recommended to avoid situations that may favor fainting, such as prolonged standing, staying in stuffy rooms and sudden verticalization. Regular intake of salted meals and an appropriate volume of fluids is also important. Children should also be taught to perform isometric exercises (crossing legs, balancing toes and heels, clenching fists, tensing arm muscles) in situations predisposing to fainting. In some children with syncope, orthostatic training is necessary, which involves gradually extending the time of standing upright. Pharmacological treatment of vasovagal syncope is used only in exceptional situations. The main drug is midodrine.\nThe most frequently used treatment is NON-PHARMAMOLOGICAL treatment - i.e. response E - increased intake of fluids in the diet.\nAnswers B and D are SURGERY, so they are incorrect.\nIn PHARMACOLOGICAL treatment, the first-line drugs are beta-blockers, e.g. propranolol, atenolol, whose effectiveness - although estimated at 60-90% - is comparable to placebo. The second line is α-sympathomimetics, for example midodrine, etylephrine, and less frequently mineralocorticoids, disopyramide or scopolamine. In children with a cardiodepressive mechanism of syncope, who have a history of kwasolia lasting longer than 4–5 s, permanent cardiac pacing is used.\nSource: Practical Medicine Comment on the article entitled \"Position of the Canadian Cardiovascular Society and the Canadian Pediatric Cardiology Association on the management of syncope in children\", prof. Ph.D. n. med. Aldona Siwińska, dr n. med. Bartłomiej Mroziński\nDepartment of Pediatric Cardiology, Nephrology and Developmental Arterial Hypertension, Medical University of Warsaw. Karol Marcinkowski in Poznań.", key: "C", consensusPct: 61, doctorsN: 12731, topic: "", konsyliumStem: "W leczeniu farmakologicznym omdleń wazowagalnych u dzieci najczęściej stosuje się:" },
  77: { text: "On the Centor/McIsaac scale, the girl scored 4 points:\n- age 3-14 years (1 point),\n- body temperature > 38 degrees (1 point),\n- tonsil exudate and swelling (1 point),\n- enlarged anterior cervical lymph nodes (1 point).\nIf the symptoms are severe, as in the case of the girl described, antibiotics are prescribed because the probability of acute streptococcal pharyngitis and tonsillitis is very high. In case of less severe symptoms or diagnostic doubts, a rapid test for the presence of the PBHA antigen should be performed, but remember that in children confirmation by culture of a throat swab is required.\nSource: \"Interna Szczeklik\" Small textbook, Andrzej Szczeklik, 2019/20, Ch. 3.3", key: "C", consensusPct: 89, doctorsN: 10633, topic: "", konsyliumStem: "Do lekarza POZ zgłosiła się mama z 4-letnią dziewczynką, gorączkującą od rana do 39,5 ºC. Poza gorączką dziecko zgłasza silny ból gardła. W badaniu przedmiotowym lekarz stwierdza n" },
  78: { text: "According to the reference textbook for LEK by A. Dobrzeńska, poor prognostic factors in ALL include: the child's age (below 1 year of age and over 10 years of age), the presence of hyperleukocytosis above 50,000, delayed remission (> 5% of blasts on the 7th day of treatment, the presence of blasts on the 28th day of treatment) and the presence of translocations t (4;11), t (8;14), t (9;22).", key: "B", consensusPct: 83, doctorsN: 11214, topic: "pediatria / Nowotwory u dzieci", konsyliumStem: "Ostra białaczka limfoblastyczna (acute lymphoblastic leukemia, ALL) jest w populacji dziecięcej chorobą o relatywnie dobrym rokowaniu na tle innych chorób nowotworowych. Wskaźnikie" },
  79: { text: "The most accurate test of the above is static DMSA scintigraphy. The change in isotope distribution allows the assessment of changes in the kidney - e.g. scars, post-inflammatory changes, cysts, kidney tumors, structural defects.\nOther tests are not accurate enough to show scars in the kidney.\nThis examination is increasingly being abandoned due to the availability of MRI and CT.\nSource: \"Interna Szczeklik\" Andrzej Szczeklik, 2018, Ch. I.VII.C.2", key: "A", consensusPct: 83, doctorsN: 11274, topic: "", konsyliumStem: "Która z metod diagnostycznych pozwala na wykrywanie blizn w nerkach?" },
  80: { text: "Determining the appropriate dosage in developmental age requires knowledge of doses expressed in mg/kg body weight or mg/m2 body surface area. Let us remember that this data is freely available in publicly available pediatric textbooks, publications, guides, leaflets attached to the packaging of medicinal products and guides intended for doctors.\nSource:\nhttp://www.leksykon.com.pl/zasady-liczania-dawowania-lekow-u-dzieci-72-artykul.html", key: "B", consensusPct: 81, doctorsN: 11221, topic: "", konsyliumStem: "Leki u dzieci, w zależności od substancji i formy podania, dawkuje się obliczając masę danej substancji: 1) na kilogram masy ciała dziecka; 2) na metr kwadratowy powierzchni ciała " },
  81: { text: "Chemoprophylaxis of close contacts in the event of invasive meningococcal disease should be implemented as soon as possible, preferably within 24 hours of the onset of the disease, but it is justified up to 2 weeks from the onset of the disease. It is also recommended to all people who had close contact with the patient in the 7 days preceding the illness (household members, people in intimate contact, people sleeping in the same room, people in contact with respiratory secretions, people performing cardiopulmonary resuscitation).\nFor the prevention of meningococcal diseases, it is recommended to use one of three antibiotics:\n- rifampicin – dosage: orally every 12 hours for 2 days, children 1 month of age 10mg/kg, adults 600mg\n- ciprofloxacin – only >18 years of age single oral dose of 500 mg\n- ceftriaxone – single dose intramuscularly <15 years of age 125mg, adults 250mg.\nThe only correct answer is to administer a single dose of ceftriaxone.\nSource: Recommendations for management of bacterial infections of the central nervous system, 2012", key: "C", consensusPct: 76, doctorsN: 11765, topic: "pediatria / Choroby zakaźne", konsyliumStem: "U 4-letniego dziecka rozpoznano w szpitalu inwazyjną chorobę meningokokową. Jakie postępowanie zapobiegawcze powinno zostać wdrożone u 2-letniego brata tego chorego, mieszkającego " },
  82: { text: "The location of the lesions and their appearance indicate a disease caused by the human scabies mite. In addition to the papular lesions mentioned above, we can observe vesicles and linear gray-black corridors of scabies in the skin. In addition to lesions located between the fingers and buttocks, they can also be found in the armpits, around the ankles, navel, armpits, groin and genitals. The changes are accompanied by itching and swelling.\nSource: Pediatrics, Editors: Kawalec Wanda, Grenda Ryszard, Ziółkowska Helena, 2014, PZWL", key: "A", consensusPct: 94, doctorsN: 10596, topic: "pediatria / Choroby zakaźne", konsyliumStem: "3-latek odczuwa nasilony świąd, zwłaszcza w nocy. Na skórze między palcami ma małe, nieregularne grudki. Na stopach i w okolicy międzypośladkowej widoczne przeczosy. Zapewne jest t" },
  83: { text: "Cystic fibrosis is the most common autosomal recessive congenital disease that shortens life in the Caucasian population. Cystic fibrosis is a multisystem disease resulting primarily from impaired ion transport through epithelial cells. In the respiratory system, this leads to a reduction in the liquid mucous layer lining the respiratory tract and the resulting disturbances in the function of the ciliary apparatus and the retention of mucopurulent secretions. The consequence is chronic endobronchial infection with specific microorganisms, such as Pseudomonas Aeruginosa. Thick meconium is produced in the intestines, causing meconium ileus in newborns. The pancreatic ducts are also blocked by the thick secretion, which leads to a deficiency of digestive enzymes and digestion and absorption disorders. Improper function of sweat glands is manifested by excessive concentration of sodium and chlorine ions in sweat.\nClinical symptoms of cystic fibrosis:\n1. Newborns - diagnosis is made based on screening; meconium ileus\n2. Infants - prolonged jaundice of the neonatal period; growth impairment; recurrent respiratory infections; absorption disorders, fatty stools\n3. Younger children - bronchiectasis, rectal mucosa prolapse, nasal polyps, sinusitis\n4. Older children and adolescents - allergic bronchopulmonary aspergillosis, diabetes, liver cirrhosis and portal hypertension, pneumothorax and recurrent hemoptysis, male infertility.\nIn the course of cystic fibrosis, the secretion of pancreatic enzymes is impaired, which results in impaired digestion of fats, proteins and carbohydrates, and as a result, impaired physical development. An estimated 85-90% of patients with cystic fibrosis have pancreatic exocrine insufficiency.\nSource: \"Pediatria\" Issue 5; 2018; Tom Lissauer; Ch. 17; \"Pediatria\" W. Kawalec, 2018, 2nd ed.; Volume I; Ch. 11.7.3\nHowever, sentence No. 5 remains controversial, because according to the data contained in Szczeklik's Internal Medicine (2018), it should be remembered that recurrent inflammation of the pancreas may lead to its fibrosis and, as a result, to its complete failure and the development of diabetes. Therefore, it is recommended to perform OGTT annually from the age of 10. The main defect that leads to the development of diabetes in patients with cystic fibrosis is insulin deficiency, but its complete absence is not observed. Both fasting insulin and C-peptide levels may be normal, but there is a noticeable delay in peak insulin secretion during the OGTT. However, disorders of the endocrine function of the pancreas are not directly related to congenital dysfunction of the chloride channel. Given the question formulated in this way, in which the author in the introduction touched upon the essence of cystic fibrosis (chloride channel dysfunction), it can be assumed that it is about the consequences of cystic fibrosis resulting 'per se' from blocking or impairing the transport of chlorine from the cell and increasing the absorption of sodium into the cell, which directly affects the reduction of water content in the secretion of exocrine glands and the increase in the production of thick secretion.\nComment update from 25/01/2021", key: "D", consensusPct: 62, doctorsN: 13158, topic: "pediatria / Mukowiscydoza", konsyliumStem: "Mukowiscydoza polega na wrodzonej dysfunkcji kanału chlorkowego. Obserwowane jest zmniejszenie wydzielania chloru, a zwiększenie absorpcji sodu do komórek, co prowadzi do zaburzeń " },
  85: { text: "The most common causes of macrocytic anemia in children include:\n- vitamin B12 deficiency - most often resulting from a deficient diet, e.g. vegetarian, less often in the case of malabsorption disorders or in mothers of children with Addison-Biermer anemia,\n- folic acid deficiency,\n- liver diseases,\n- hypothyroidism,\n- acquired aplastic anemia\n- Fanconi anemia\n- Blackfan-Diamond syndrome.\nPediatrics – Manual for the State Medical Examination and specialization examination, Ed. Anna Dobrzańska and Józef Ryżko, Urban i Partner 2005", key: "A", consensusPct: 77, doctorsN: 11689, topic: "", konsyliumStem: "Do najczęstszych przyczyn niedokrwistości makrocytarnej u dzieci należy zaliczyć:" },
  89: { text: "The main factors increasing the risk of urolithiasis in children:\n- isolated metabolic defects (adsorption hypercalciuria and renal hyperuricosuria, hypocitraturia),\n- situations favoring the production of concentrated urine (insufficient fluid supply, warm climate),\n- urinary stasis,\n- constant high or low urine pH,\n- urinary tract infections (Proteus spp., Moraxella morganii, Klebsiella spp., Staphylococcus spp.)\n- genetically determined genetic diseases,\n- prematurity with low birth weight <1500 g,\n- vitamin metabolism disorders D (its overdose, primary hyperparathyroidism).\nSource: Pediatrics. Vol. 1-2. Wanda Kawalec, Ryszard Grenda, Helena Ziółkowska, Warsaw, Wydawnictwo Lekarskie PZWL, 2013", key: "D", consensusPct: 92, doctorsN: 10560, topic: "", konsyliumStem: "Które z wymienionych czynników zwiększają ryzyko wystąpienia kamicy układu moczowego? 1) zwiększona podaż płynów; 2) występowanie kamicy w rodzinie; 3) ciepły klimat; 4) zakażenie " },
  90: { text: "Extraesophageal symptoms of reflux disease:\n- pulmonary: asthma, chronic bronchitis, bronchiectasis, pulmonary fibrosis, chronic sinusitis\n- otolaryngological: chronic cough, throat clearing, persistent inflammation of the larynx, throat, sinuses, ears, globe\n- other: enamel defects, sleep apnea.\nSource: \"Pediatria\" W. Kawalec, 2018, 2nd ed.; Volume I; Ch. 11.2", key: "B", consensusPct: 76, doctorsN: 11793, topic: "pediatria / Badanie kliniczne dziecka", konsyliumStem: "Który objaw jest najmniej prawdopodobnym objawem pozaprzełykowym choroby refluksowej?" },
  91: { text: "The above case report is a classic symptom of newly diagnosed type 1 diabetes. Polydipsia, polyuria and weight loss are common first symptoms. Symptoms may be accompanied by excessive sleepiness and fatigue. As the disease progresses, symptoms of metabolic acidosis and ketosis also appear - in this case, impaired consciousness, severe general condition, abdominal pain and deepened, intensified breathing - Kussmaul breathing.\nSource:\nWanda Kawalec, Ryszard Grenda, Helena Ziółkowska (ed.): Pediatrics, volume 1-2, Warsaw 2013, Wydawnictwo Lekarskie PZWL)", key: "A", consensusPct: 94, doctorsN: 10510, topic: "pediatria / Cukrzyca", konsyliumStem: "5-letnia dziewczynka, dotychczas zdrowa, prawidłowo rozwijająca się, została skierowana do SOR z powodu zaburzeń świadomości, w stanie ogólnym ciężkim, znacznie odwodniona z nasilo" },
  92: { text: "Increased loss of phosphates in urine occurs in the course of: Fanconi syndrome, tumor lysis syndrome, hypophosphatemic rickets and primary hyperparathyroidism.\nSource: Internal Szczeklik 2018.", key: "A", consensusPct: 66, doctorsN: 12994, topic: "", konsyliumStem: "W których stanach/jednostkach chorobowych występuje zwiększona utrata fosforanów z moczem? 1) zespół Fanconiego; 2) zespół lizy guza w przebiegu chemioterapii; 3) krzywica hipofosf" },
  93: { text: "The girl suffers from stage 3 chronic renal failure.\nStages of chronic kidney disease:\n1 - GFR normal or elevated, >90 ml/min/1.73m2m\n2 - GFR 89-60 ml/min/1.73m2,\n3 - GFR 59-30 ml/min/1.73m2,\n4 - GFR 29-15 ml/min/1.73m2,\n5 - GFR <15 ml/min/1.73m2,\n5d - dialysis patient.\nSource: Pediatrics. Vol. 1-2. Wanda Kawalec, Ryszard Grenda, Helena Ziółkowska, Warsaw, Wydawnictwo Lekarskie PZWL, 2013", key: "C", consensusPct: 80, doctorsN: 11370, topic: "", konsyliumStem: "U 16-letniej pacjentki z nefropatią toczniową z eGFR = 45 ml/min/1,73 m2 należy rozpoznać następujące stadium przewlekłej niewydolności nerek:" },
  95: { text: "Nephrotic syndrome is a condition caused by increased proteinuria, which results in hypoalbuminemia and edema. The cause of the syndrome is unknown, but in a few cases it may be a secondary phenomenon in the course of systemic diseases, such as Schonlein-Henoch purpura or other vasculitis, systemic lupus erythematosus, infections (e.g. malaria) or allergens (e.g. after bee stings). The clinical symptoms of nephrotic syndrome include:\n- swelling around the eyes (especially after waking up) - the earliest symptom\n- swelling of the scrotum or vulva, lower limbs (shins), and around the ankle joints\n- ascites\n- shortness of breath caused by pleural effusion and abdominal enlargement\n- peritonitis, septic arthritis or sepsis due to loss of protective immunoglobulins in the urine.\nNS is diagnosed in the case of:\n• significant proteinuria, i.e. ≥50 mg/kg/24 h (or ≥40 mg/m2/h), or urine protein/creatinine ratio >2 (mg/mg)\n• serum albumin concentration <25 g/l\n• presence of edema.\nSource: \"Pediatria\" Issue 5; 2018; Tom Lissauer; Ch. 19\nhttps://www.mp.pl/pediatria/artykuly-wytyczne/wytyczne/196169, poznanie-i-leczenie-pierskiego-rzutu-zespolu-nerczycowego-oraz-pórcegonawrotu-choroby-aktualne-2017-wytyczne-sinepe", key: "E", consensusPct: 76, doctorsN: 12019, topic: "pediatria / Choroby układu wydzielania wewnętrznego", konsyliumStem: "3-letnia dziewczynka zgłosiła się do poradni z powodu złego samopoczucia, bólu brzucha i obrzęków zlokalizowanych głównie na kończynach dolnych. W wykonanym badaniu moczu stwierdzo" },
  96: { text: "Bronchiolitis is the most common, severe respiratory infection in infancy. In 80% of cases, the responsible pathogen is respiratory syncytial virus (RSV). A dry cough and increasing symptoms of shortness of breath are preceded by several days of catarrhal symptoms. The reason for admission to hospital is very often difficulty in feeding the child, which increases with symptoms of shortness of breath. A serious complication, especially in younger infants, is repeated episodes of apnea. Premature infants with bronchopulmonary dysplasia and infants with congenital heart defects or cystic fibrosis are at risk of severe disease.\nSource: \"Pediatria\" Issue 5; 2018; Tom Lissauer; Ch. 17", key: "D", consensusPct: 83, doctorsN: 11172, topic: "", konsyliumStem: "Wskaż prawdziwe stwierdzenie dotyczące zapalenia oskrzelików:" },
  97: { text: "Wilson's disease belongs to the group of metabolic diseases. As a result of a gene mutation of the copper-binding protein, copper binding by ceruloplasmin is impaired and copper excretion into bile is reduced. As a result, copper is accumulated in the liver and other tissues. Liver damage occurs, manifested by increased transaminase activity, cholestasis, hemolysis, inflammation and liver failure. Accumulated copper also damages other organs, mainly the nervous system. Behavioral disorders and depression are also observed. A characteristic symptom of Wilson's disease is the Kayser-Fleisher ring, i.e. copper deposits in the cornea. However, like neurological symptoms, it is rarely observed in children.\nSerum ceruroplasmin concentration is decreased. Increased urinary copper excretion is also observed.\nSource: Pediatrics, Editors: Kawalec Wanda, Grenda Ryszard, Ziółkowska Helena, 2014, PZWL", key: "C", consensusPct: 58, doctorsN: 13422, topic: "pediatria / Wrodzone wady metabolizmu", konsyliumStem: "Wskaż cechy charakterystyczne choroby Wilsona u dzieci: 1) nadmierne gromadzenie się miedzi w wątrobie ze wzrostem aktywności aminotransferaz w surowicy; 2) częste występowanie zab" },
  98: { text: "In the light of the latest GINA guidelines, inhaled glucocorticosteroids are the most effective and preferred drugs controlling the course of asthma, recommended at every stage of asthma treatment as an emergency drug together with formoterol (Interna Szczeklika).\nHowever, if asthma symptoms occur only seasonally after a period of exposure to the allergen, chronic treatment may be discontinued with the recommendation of follow-up to assess the persistence of symptom remission (Pediatria, edited by W.Kawalec)\nThere was no effect of the use of glucocorticoids on the duration and severity of symptoms and in the case of bronchitis, therefore their use without a diagnosis of asthma or obstructive bronchitis is not justified. It is also not recommended to use glucocorticoids in children suffering from acute bronchiolitis.\nIn the case of acute subglottic laryngitis, the treatment is as follows:\n- single oral or intramuscular administration of dexamethasone at a dose of 0.15-0.6 mg/kg body weight (max. 8 mg),\n- an alternative is a single dose of 2 mg of budesonide by nebulization\n- in more severe cases, adrenaline 0.1% at a dose of 0.5 ml/kg b.w. can also be administered or, in order to obtain a faster effect than after glucocorticoids, before their administration. (max. 5 ml).\nSource: Recommendations for management of community-acquired respiratory infections Edited by: Prof. Ph.D. n. med. W. Hryniewicz, Dr hab. n. med. Piotr Albrecht, Prof. Ph.D. n. med. Andrzej Radzikowski developed by the Ministry of Health as part of the \"National Antibiotic Protection Program\".\nUpdate from 01/02/2021", key: "C", consensusPct: 51, doctorsN: 13799, topic: "", konsyliumStem: "Glikokortykosteroidy wziewne znajdują zastosowanie w leczeniu:" },
  99: { text: "The first symptoms of cystic fibrosis (CF) in infancy may be non-specific: lack of expected weight gain, prolonged neonatal jaundice, recurrent and chronic lower respiratory tract infections, chronic cough. The more typical symptoms that make us suspect CF include meconium ileus in the neonatal period, steatorrhea, and prolapse of the rectal mucosa.\nDue to increased excretion of electrolytes (Na, Cl) in sweat, dehydration may cause pseudo-Bartter's syndrome with metabolic alkalosis, hyponatremia, hypochloremia and hypokalemia.\nThis is followed by shortness of breath, hemoptysis, chronic bronchopulmonary disease, bronchiectasis, nasal polyps, abdominal pain, constipation, hepatosplenomegaly, pancreatitis, pancreatic exocrine insufficiency, diabetes, cholelithiasis, biliary cirrhosis, infertility, and cor pulmonale.", key: "D", consensusPct: 95, doctorsN: 10481, topic: "pediatria / Mukowiscydoza", konsyliumStem: "Do poradni pulmonologicznej zgłosiło się 10-letnie dziecko z przewlekłym kaszlem i nawracającymi infekcjami dróg oddechowych, zwykle przebiegającymi z odkrztuszaniem ropnej wydziel" },
  100: { text: "In phakomatoses, the nervous system and skin develop from the same germ layer - the ectoderm. Disturbances in embryonic development result in syndromes composed of abnormalities of these two systems - cutaneous-nerve syndromes. Phakomatoses are also often called neuroectomesodermal dysplasias. Phakomatoses include:\n- neurofibromatosis type 1 (neurofribomatosis)\n- neurofibromatosis type 2 (NF-2)\n- tuberous sclerosis (Bourneville-Pringle syndrome)\n- Sturge-Weber syndrome - a sporadic disease with a facial hemangioma (wine-red stain), located in the area of \\u200b\\u200bthe innervation of the trigeminal nerve, with a similar lesion located intracranially.\nTay-Sachs disease is a storage disease\nSource: \"Pediatria\" Issue 5; 2018; Tom Lissauer; Ch. 29", key: "E", consensusPct: 73, doctorsN: 11861, topic: "", konsyliumStem: "Do fakomatoz nie zalicza się:" },
  102: { text: "According to the reference textbook by A. Obuchowicz \"Subjective and objective examination in pediatrics\", the Moro reflex is a motor automatism consisting of initial abduction and partial extension of the pelvis. upper limbs (phase I) with their subsequent flexion and adduction to the chest (phase II), present from the child's birth and disappearing around the age of 5-6. month of life.\nA reflex that persists beyond this period is a pathological phenomenon.", key: "C", consensusPct: 88, doctorsN: 10942, topic: "pediatria / Rozwój fizyczny i motoryczny dzieci i młodzieży", konsyliumStem: "Odruch Moro:" },
  103: { text: "Marfan syndrome is characterized by above-average height (average newborn body length 53 ± 4.4 cm for boys, 52.5 ± 3.5 cm for girls, average final height 191.3 ± 9 cm for men, 175.4 ± 8.2 cm for women) and disturbed body proportions (ratio of upper to lower body less than 0.85, ratio of arm length to height > 1.05), slender limbs, superior lens subluxation, hypotonia, kyphoscoliosis, valvular heart defects, dilatation of the aortic root.", key: "B", consensusPct: 92, doctorsN: 10690, topic: "pediatria / Rozwój fizyczny i motoryczny dzieci i młodzieży", konsyliumStem: "Niskorosłość może wystąpić we wszystkich wymienionych poniżej jednostkach chorobowych, z wyjątkiem:" },
  104: { text: "Chlamydia Trachomatis pneumonia:\n- usually develops between 2 and 19 weeks of age,\n- it is quite mild, without fever, with marked tachypnea and so-called cough. staccato (consisting of several separate sounds), crackles are observed on auscultation, without whistling,\n- it is very often accompanied by conjunctivitis, pharyngitis, rhinitis and otitis media (vomiting is not a typical feature of this infection).\nSource: Pediatrics. Jacek J. Pietrzyk, Przemko Kwinta, Kraków, Jagiellonian University Publishing House, 2018", key: "C", consensusPct: 66, doctorsN: 12728, topic: "", konsyliumStem: "Wskaż prawdziwe stwierdzenia dotyczące zapalenia płuc wywołanego przez Chlamydia trachomatis: 1) występuje u noworodków w pierwszych tygodniach życia; 2) jest przykładem infekcji a" },
  106: { text: "Nowadays, tuberculosis is most often infected by adults from the child's immediate home environment (mother, father, caregiver). Children under 3 years of age are most susceptible to M. tuberculosis infection. Risk factors for tuberculosis include:\n- increased exposure to infection from adults,\n- environment of immigrants, homeless, drug addicts, alcoholics,\n- low socioeconomic status,\n- chronic diseases, e.g. the probability of developing tuberculosis increases by 30% in children on dialysis,\n- immune disorders, e.g. HIV infection,\n- malnutrition.\nIf tuberculosis is suspected in a child, the following are necessary:\n- physical examination - primarily to determine contact with a tuberculosis patient,\n- physical examination,\n- tuberculin reaction,\n- immunological tests (IGRA),\n- imaging tests - chest X-ray and other organs, chest CT, bronchoscopy,\n- bakeriological tests - bacterioscopy, genetic testing, culture; gastric lavage (3 times), induced sputum, spontaneously expectorated sputum, bronchial lavage, lymph node content, pleural fluid, cerebrospinal fluid and urine are collected for testing,\n- histopathological examination\nSource: \"Pediatria\" W. Kawalec, 2018, 2nd ed.; Volume I; Ch. 9.3.6", key: "C", consensusPct: 64, doctorsN: 12526, topic: "", konsyliumStem: "Wskaż fałszywe stwierdzenie dotyczące gruźlicy u dzieci:" },
  107: { text: "Infectious mononucleosis is caused by the EBV virus belonging to the Herpesviridae family. The EBV virus can also cause diseases such as Hodgkin's disease and Burkitt's lymphoma. Answer And it's true.\nThe incubation period ranges from 30 to 50 days - answer B is false.\nLaboratory tests are characterized by leukocytosis with lymphocytosis and the presence of atypical lymphocytes in the smear - answer C is false.\nInfectious mononucleosis should primarily be differentiated from cytomegalovirus, angina, diphtheria, and HSV infection - answer D is false.\nDue to the fact that the disease is caused by viruses, antibiotic therapy should not be used - answer E is false.\nsource:\nhttps://www.mp.pl/interna/chapter/B16.II.18.1.9\n.", key: "A", consensusPct: 68, doctorsN: 12388, topic: "", konsyliumStem: "Wskaż prawdziwe stwierdzenie dotyczące mononukleozy zakaźnej:" },
  108: { text: "Graft rejection reactions:\n- acute rejection: periportal hepatitis, non-purulent cholangitis, phlebitis.\nDiagnosis: increase in cholestasis parameters greater than transaminase activity, liver biopsy.\n- chronic rejection: non-purulent process of destruction of small bile ducts (VBDS - vanishing bile duct syndrome).\nDiagnosis: increase in cholestasis parameters, liver biopsy.\n- failure of the transplanted organ to function: this occurs in 2-3% of patients. The treatment of choice is liver retransplantation.\n- bleeding: affects 10-15% of patients. It is an indication for reoperation.\n- early hepatic artery thrombosis: 2-8% of patients. Most often, it requires repeated liver transplantation.\n- portal vein thrombosis: 1-3% of patients. A relatively rare complication.\n- hepatic vein obstruction: may lead to the development of acute Budd-Chiari syndrome. It usually requires a second liver transplant.\n- biliary complications: 10-20% of patients. They most often appear in the first 3 months after surgery.\n- bile leakage:\nfrom the anastomosis site\nfrom the place of drain exit\nfrom the cystic duct stump\n- narrowing of the bile ducts\nat the site of anastomosis\ncaused by ischemia\n- non-surgical complications:\ninfections\nrespiratory disorders\ncardiovascular disorders\nkidney disorders\nneurological disorders\ndisorders in the coagulation system\ndiabetes\nSource: \"Internal diseases\" edited by prof. Ph.D. Andrzej Szczeklik, volume 1, pp. 974–976, ISBN 83-7430-031-0\nRecurrence of the underlying disease in the transplanted liver most often occurs in patients with hepatitis C or B, and less frequently in patients with AIH, PSC, PBC, alcoholic cirrhosis, HCC, non-alcoholic fatty liver disease (NAFLD), and hemochromatosis. Patients with congenital anatomical anomalies (biliary atresia, Caroli syndrome, Alagille syndrome, congenital liver fibrosis) or metabolic anomalies (Wilson's disease, alpha-1 antitrypsin deficiency) are free from recurrence.\nMoreover, quite early postoperative complications include recurrence of HBV and HCV infections in patients undergoing surgery due to the consequences of chronic HBV or HCV infections (recurrence of HCV infection in the transplanted liver affects over 90% of patients, over half of whom require treatment due to symptoms of chronic inflammation and fibrosis. HCV recurrence in 50% of patients leads to cirrhosis within 10 years, which is faster than in immunocompetent patients).\nViral infection in the recipient (endo or exogenous) may increase the risk of cancer (e.g. HHV-8 - Kaposi's sarcoma) or the risk of PTLD (e.g. EBV).\nPTLD (post-transplant lymphoproliferative disease) occurs with an incidence of 1-3% of adult liver transplant recipients within 2 years of transplantation.\nDue to the need for immunosuppressive treatment, there is also an increased risk of opportunistic infections and cancer.\nSources: Fundamentals of Surgery - J.Szmidt (2009) and \"POST-TRANSPLANTATION CARE IN THE RECIPIENT AFTER LIVER TRANSPLANTATION\" Ewa Nowacka-Cieciura, MD, Department of Transplantation Medicine and Nephrology, Medical University of Warsaw\nGraft-versus-host disease may complicate <2% of liver transplantations.\nSmith DM, Agura E, Netto G, et al. Liver transplant-associated graft-versus-host disease. Transplantation. 2003;75:118–26.\nUpdated on March 1, 2021", key: "B", consensusPct: 60, doctorsN: 12320, topic: "", konsyliumStem: "Które z powikłań nie występuje u pacjentów po przeszczepieniu wątroby?" },
  109: { text: "In the case of smallpox, the symptoms described above do not occur; a polymorphic rash without a hemorrhagic component is characteristic, immediately preceded by symptoms of an upper respiratory tract infection. In the case of arthritis, there are no petechiae on the skin or proteinuria. We can exclude thrombocytopenia because it does not cause proteinuria or joint pain.\nVascular diseases are divided into congenital (e.g. Rendu-Weber-Osler disease, Kasabach-Meritt syndrome) and acquired (e.g. purpura associated with excessive vascular fragility, DIC, autoimmune vasculitis - Schonlein-Henoch purpura).\nHowever, a history of a previous upper respiratory tract infection and proteinuria are typical for a specific type of vascular diathesis, i.e. Schonlein-Henoch purpura associated with IgA antibodies.\nTypically:\n- it occurs 1-3 weeks after an upper respiratory tract infection,\n- symptoms: skin lesions - polymorphic rash that does not go away under pressure, gravity-dependent; inflammation of joints - usually large ones, e.g. elbows, knees, ankles; involvement of the digestive tract - pain, bleeding; kidney involvement - hematuria, nephrotic syndrome, nephritic syndrome, hypertension.\nSource: Pediatrics. Vol. 1-2. Wanda Kawalec, Ryszard Grenda, Helena Ziółkowska, Warsaw, Wydawnictwo Lekarskie PZWL, 2013", key: "A", consensusPct: 91, doctorsN: 10750, topic: "pediatria / Podstawy reumatologii", konsyliumStem: "Do lekarza zgłasza się dziecko z drobnymi wybroczynami na udach, bólami stawowymi oraz białkomoczem. Matka podaje, że dziecko około 2 tygodnie temu miało zapalenie bakteryjne gardł" },
  111: { text: "Non-alcoholic fatty liver disease (NAFLD) - laboratory tests usually show a slight or moderate increase in ALT, AST and GGT activity, hyperbilirubinemia, dyslipidemia, hyperglycemia or impaired glucose tolerance (common), hypoalbuminemia and PT prolongation (in advanced liver disease), increased iron and ferritin levels (quite common)\nKawasaki disease involves hepatitis with elevated transaminase activity and jaundice in approximately 15% of patients.\nIncreased aminotransferase activity is observed in myopathies.\nSource: \"Pediatria\" W. Kawalec, 2018, 2nd ed.; Volume II; Ch. 18/02/10\n\"Interna Szczeklik\" A small textbook, Andrzej Szczeklik, 2019/20, Ch. 7/11", key: "D", consensusPct: 83, doctorsN: 11207, topic: "", konsyliumStem: "Podwyższona aktywność aminotransferaz nie występuje w:" },
  112: { text: "In the diagnosis of constipation, manometry, Hinton's test and contrast enema of the large intestine are used. Manometry is a test that allows you to determine the function of the anal sphincters based on pressure measurements in the anus and rectum.\nThe Hinton test is mainly used in the diagnosis of chronic constipation and allows for the assessment of intestinal transit. The patient takes markers for 6 consecutive days, the distribution of which in the intestine is observed on day 7 based on an abdominal X-ray. Contrast enema of the large intestine involves administering a contrast agent into the lumen of the large intestine, the distribution of which is then imaged on X-rays.\nSource: Internal Szczeklik 2018.", key: "B", consensusPct: 73, doctorsN: 12148, topic: "", konsyliumStem: "Do diagnostyki zaparcia wykorzystuje się: 1) manometrię; 2) test Hintona; 3) test wodorowy; 4) wlew kontrastowy jelita grubego; 5) gastrofiberoskopię. Prawidłowa odpowiedź to:" },
  113: { text: "Measles is a highly contagious viral disease transmitted through droplets. Measles is caused by Morbillivirus (RNA) from the Paramyxoviridae family. It is characterized by a very typical 4-phase course:\n1. incubation period: usually lasts 9-11 days, is often asymptomatic, but there may be deterioration of the general condition, loss of appetite and increased body temperature\n2. catarrhal period - lasts 3-4 days, there is high fever, rhinitis, pharynx and larynx, tiring, dry cough, acute conjunctivitis with photophobia and tearing, \"crying face\", sometimes swelling of the eyelids. In 2.-3. on the day of the catarrhal period, on the mucous membrane of the cheeks, at the level of the lower molars and premolars, white eruptions with a red inflammatory rim can be seen - Koplik's spots - filate, pathognomonic for measles\n3. rash period - lasts about 3-4 days, a descending rash appears - initially behind the ears and then covers the entire body. Initially, it appears as a maculopapular rash, then the lesions merge to form spots. In the second week, the epidermis may peel.\n4. recovery period.\nSource: \"Pediatria\" Issue 5; 2018; Tom Lissauer; Ch. 15\n\"Pediatria\" W. Kawalec, 2018, 2nd ed.; Volume II; Ch. 19.7.2", key: "B", consensusPct: 91, doctorsN: 11026, topic: "pediatria / Choroby zakaźne", konsyliumStem: "Dziecko 2-letnie, dotychczas nieszczepione (decyzja rodziców) wróciło po dwutygodniowych wakacjach z Ukrainy. Po tygodniu wystąpiła wysoka gorączka, suchy kaszel, wysięk z nosa, za" },
  114: { text: "In mild forms of nephrotic syndrome, we primarily observe an increase in cholesterol levels, while in more severe forms hypertriglyceridemia occurs. There is also loss of immunoglobulins, transferrin and ceruloplasmin in the urine, which increases susceptibility to infections. In nephrotic syndrome, the concentration of vitamin D-binding protein is also reduced, and its active metabolites are not formed.\nSource: Internal Szczeklik 2018.", key: "B", consensusPct: 64, doctorsN: 13195, topic: "", konsyliumStem: "Dla zespołu nerczycowego charakterystyczne są następujące wtórne zaburzenia: 1) wzrost stężenia trójglicerydów i cholesterolu w surowicy; 2) objawy niedoboru witaminy D; 3) objawy " },
  119: { text: "Edema, proteinuria, hypoalbuminemia are the symptoms that make up the clinical picture of nephrotic syndrome. It may be a symptom of most glomerulonephritis. Additionally, typical laboratory findings include hyperlipidemia. The first-line treatment is glucocorticosteroids. Prednisone is used at an initial dose of 2 mg/kg body weight, with the aim of its gradual reduction.\nSource:\nWanda Kawalec, Ryszard Grenda, Helena Ziółkowska (ed.): Pediatrics, volume 1-2, Warsaw 2013, Wydawnictwo Lekarskie PZWL)", key: "B", consensusPct: 76, doctorsN: 11882, topic: "pediatria / Choroby układu moczowego", konsyliumStem: "3-letni chłopiec został przyjęty do oddziału z powodu skąpomoczu oraz uogólnionych obrzęków. W badaniach laboratoryjnych stwierdzono białkomocz 500 mg/mmol kreatyniny, albuminemię " },
  120: { text: "According to percentile charts, in a 12-month-old infant, the 90th percentile of systolic blood pressure is 105 mmHg, and diastolic blood pressure is 67 mmHg for girls and 69 mmHg for boys.\nThe normal heart rate in a 12-month-old infant should be approximately 123/min (range between 1-99th percentile: 88-156).\nSource:\nPercentile chart of systolic and diastolic blood pressure in infants up to 12 months of age.\nThe Lancet, Vol. 377 (9770), Fleming S., Thompson M., Stevens R. et al., Normal ranges of heart rate and respiratory rate in children from birth to 18 years of age: a systematic review of observational studies: 1011–1018.", key: "A", consensusPct: 80, doctorsN: 11401, topic: "", konsyliumStem: "Wskaż zestaw parametrów: czynność serca (HR) oraz ciśnienie tętnicze krwi (RR) prawidłowych dla rocznego dziecka:" },
  121: { text: "By far the most common etiological factor of bronchitis in young children are viruses (RSV, influenza viruses, adenoviruses, parainfluenza viruses, metapneumoviruses, rhinoviruses). Infections with atypical microorganisms, such as Chlamydophila pneumoniae and Mycoplasma pneumoniae, are much rarer. Whooping cough may also be the cause of chronic cough. If typical viral etiology is suspected, symptomatic treatment is the treatment of choice. According to the current management recommendations from 2016, oxygen therapy (when Sat <90%) and proper hydration of the patient are recommended. Routine use of bronchodilators (although they may be considered in case of audible wheezing), glucocorticosteroids, and anti-leukotriene drugs is not recommended. Mucolytics (erdosteine) can be used briefly during periods of productive cough. Additionally, in bronchiolitis requiring hospitalization, it is recommended to use nebulization with 3% NaCl. Introducing an antibiotic should only be considered if pertussis is suspected (macrolide) and in young children (< 5 years of age) with a productive cough that has persisted for more than 4 weeks and does not show any decreasing trends, and after excluding other causes (amoxicillin with clavulonic acid or macrolide).\nFlu vaccines available in Poland are registered from the age of 6 months (influvac) or after the age of 3 (Vaxigrip Tetra).", key: "B", consensusPct: 79, doctorsN: 11961, topic: "pediatria / Choroby układu oddechowego", konsyliumStem: "Wskaż prawdziwe stwierdzenie dotyczące zapaleń oskrzeli u dzieci:" },
  124: { text: "Both in the systemic form of juvenile idiopathic arthritis and in proliferative blood diseases, we may encounter similar abnormalities in blood laboratory tests - increased leukocytosis, anemia, increased inflammatory markers (CRP, ESR). General symptoms such as fever, bone pain, abdominal pain, and weight loss may also occur in both cases. X-ray of the affected joints and abdominal ultrasound may be helpful in the differential diagnosis. However, in doubtful cases, it is necessary to perform a bone marrow biopsy with morphological, cytogenetic, immunophenotypic and cytochemical evaluation of the cells.\nSource:\nWanda Kawalec, Ryszard Grenda, Helena Ziółkowska (ed.): Pediatrics, volume 1-2, Warsaw 2013, Wydawnictwo Lekarskie PZWL)", key: "C", consensusPct: 76, doctorsN: 11720, topic: "pediatria / Podstawy reumatologii", konsyliumStem: "Które z badań jest decydujące przy różnicowaniu układowej postaci młodzieńczego idiopatycznego zapalenia stawów z chorobami rozrostowymi krwi?" },
  126: { text: "The diagnosis of Wilms tumor is made\nbased on imaging tests - most often in the initial diagnosis - ultrasound, then CT.\nThe remaining tests included in the answers have no clinical significance in diagnosing this disease.\nTherefore, the correct answer to the question is C.\nSource:\nPediatrics - Tom Lissauer, Will Carroll, Wrocław 2019, p. 454", key: "C", consensusPct: 78, doctorsN: 11731, topic: "pediatria / Nowotwory u dzieci", konsyliumStem: "Badaniem niezbędnym do rozpoznania guza Wilmsa jest:" },
  127: { text: "In infants and children under 2 years of age, lower respiratory tract infections most often present as bronchiolitis. In 50-80% of cases, the etiological factor is the RS virus, less frequently the human metaponeumovirus and other viruses. The disease is characterized by inflammation in the bronchioles, leading to mucosal edema, epithelial necrosis, excessive mucus production and bronchial obstruction. Children require symptomatic treatment - access to cool, moist air, proper hydration, and cleaning of excess nasal secretions. Sometimes hospitalization, oxygen therapy, and less often respiratory support or even intubation are necessary. Ribavirin shows low effectiveness in treatment. Antibiotic therapy is used in the case of bacterial superinfection. A specific immunoglobulin against RSV, palivizumab, is used in children at risk, mainly in children born prematurely.\nSource: Pediatrics, Editors: Kawalec Wanda, Grenda Ryszard, Ziółkowska Helena, 2014, PZWL", key: "A", consensusPct: 90, doctorsN: 10886, topic: "pediatria / Choroby układu oddechowego", konsyliumStem: "Na oddział dziecięcy przyjęto 4-miesięczne niemowlę z rozpoznaniem zapalenia oskrzelików. Dziecko dotychczas nie chorowało. W teście szybkim wykryto w wymazie z nosa i gardła antyg" },
  128: { text: "Streptococcus pyogenes (group A beta-hemolytic streptococcus) is the most common etiological factor of acute bacterial pharyngitis and tonsillitis. The treatment of choice for streptococcal angina is penicillin, to which the pathogen is practically 100% sensitive. We use phenoxymethylpenicillin orally: in adults and children weighing > 40 kg at a dose of 2-3 million IU/day administered in 2 divided doses every 12 hours. In children weighing < 40 kg at a dose of 100,000-200,000 IU/kg/day, in 2 divided doses every 12 hours. In case of poor compliance of the patient or difficulty in taking antibiotics orally, a single intramuscular administration of benzathine benzylpenicillin is recommended - 1.2 million IU. > 40 kg body weight or 600,000 IU at a time  40 kg 300 mg every 8 hours, and in children weighing < 40 kg 20-30 mg/kg/day in 3 doses for 10 days.\nEffective antibiotic therapy shortens the period of infectiousness to 24 hours after starting treatment, reducing the duration of symptoms by 1-2 days on average and reducing the risk of complications such as rheumatic fever, acute otitis media and acute inflammation of the mucous membrane and paranasal sinuses.\nRecommendations for management of community-acquired respiratory infections 2016, National Antibiotic Protection Program", key: "C", consensusPct: 94, doctorsN: 10360, topic: "pediatria / Podstawy okulistyki i otolaryngologii", konsyliumStem: "W anginie paciorkowcowej lekiem z wyboru jest:" },
  130: { text: "The correct answer is B - Landau reflex. This is a reaction that has been studied in newborns and young infants. It involves placing the child on the examiner's hand, parallel to the ground, face down. The reaction has several phases. At the age of 1-6 weeks, the baby's head drops slightly, the body and limbs are slightly bent. Gradually, with age, the child reaches subsequent stages. After 6 months of life, a baby positioned in this way should straighten its lower limbs and arch its spine.\nLust's sign is characteristic of tetany. It involves abducting the foot in response to a blow with a neurological hammer below the head of the fibula (to the common peroneal nerve).\nLevin's sign occurs in patients with unstable angina and involves pointing to the location of pain with a clenched fist in the sternum area.\nLasegue's sign is characteristic of sciatica. The patient is lying on his back and is unable to lift his lower limb.\nLeigh syndrome, or subacute necrotizing encephalomyelopathy, is a mitochondrial disease. It appears in children between 3 and 24 months of age and affects the nervous system, muscles, heart and kidneys.", key: "B", consensusPct: 69, doctorsN: 12591, topic: "pediatria / Neonatologia", konsyliumStem: "Reakcja błędnikowa u niemowlęcia badana w celu oceny rozwoju psychoruchowego to:" },
  131: { text: "Orthostatic proteinuria is one of the most common causes of proteinuria in teenage boys. Its characteristic features include its occurrence only after standing upright, it disappears or is minor at night, and the protein concentration in individual portions of urine during the day may be significant. However, it does not cause impaired kidney function.\nThe question does not describe any disturbing symptoms or infections, so this answer should be considered the most probable.\nSource: Pediatrics. Vol. 1-2. Wanda Kawalec, Ryszard Grenda, Helena Ziółkowska, Warsaw, Wydawnictwo Lekarskie PZWL, 2013", key: "D", consensusPct: 89, doctorsN: 10877, topic: "pediatria / Choroby układu moczowego", konsyliumStem: "11-letni chłopiec zgłosił się do lekarza z wynikiem badania moczu pobranego w godzinach popołudniowych, w którym stwierdzono białkomocz 300 mg/dl. Jaka jest najbardziej prawdopodob" },
  132: { text: "The incubation period for chickenpox in an immunocompetent person is 10-21 days. It may be prolonged in people with immune disorders. Infectivity begins 2 days before the rash appears and lasts until the last rash dries up (approx. 7 days on average).", key: "D", consensusPct: 68, doctorsN: 12592, topic: "pediatria / Choroby zakaźne", konsyliumStem: "W jakim czasie po kontakcie z pacjentem z ospą wietrzną (w okresie zaraźliwości) immunokompetentne dziecko może rozwinąć objawy ospy wietrznej?" },
  133: { text: "Hemophilia is a recessive, sex-linked genetic disease - healthy mothers are carriers of an abnormal mutated gene linked to the X chromosome. The disease manifests itself in men who inherit the defective gene because they are hemizygotes. It is possible for hemophilia to occur in a woman who is the daughter of a hemophiliac and her mother is a carrier of the defective gene, but this is an extremely rare situation.\nCrossword:\nCarrier mother: XHXh, father: XhY\nPossibilities: XHXh, XHY, XhXh, XhY.\nChance of giving birth to a boy: 50%.\nRisk of giving birth to a boy with the condition, assuming a male child is born: 50%.", key: "C", consensusPct: 77, doctorsN: 11729, topic: "pediatria / Genetyczne uwarunkowania chorób", konsyliumStem: "W przypadku matki będącej nosicielką zmutowanego genu, ryzyko, że jej syn będzie chory na hemofilię A wynosi:" },
  134: { text: "Celiac disease (gluten-dependent enteropathy, celiac disease) is a permanent intolerance to gluten (a protein found in cereals). Its consumption in genetically predisposed people causes damage to the mucosa of the small intestine and, consequently, intestinal malabsorption syndrome. Celiac disease may co-occur with:\n- type I diabetes,\n- autoimmune thyroiditis,\n- recurrent idiopathic pericarditis,\n- autoimmune hepatitis,\n- inflammatory bowel disease,\n- autoimmune pancreatitis,\n- uveitis,\n- rheumatoid arthritis,\n- sarcoidosis, Sjogren's syndrome,\n- lymphomas and adenocarcinomas of the small intestine,\n- enamel hypoplasia,\n- recurrent oral canker sores,\n- delayed puberty,\n- spontaneous miscarriages,\n- Down syndrome.\nDuhring's disease is one of the forms of celiac disease in which multiform eruptions (papules, vesicles) are observed on the extensor surfaces of the limbs, in the shoulder and sacrolumbar areas, and on the buttocks.\nSource: \"Pediatria\" W. Kawalec, 2018, 2nd ed.; Volume I; Ch. 11.2.7", key: "A", consensusPct: 63, doctorsN: 12789, topic: "", konsyliumStem: "Celiakia może współistnieć z wieloma innymi chorobami autoimmunologicznymi, m.in. z: 1) autoimmunologicznym zapaleniem wątroby; 2) chorobą Hashimoto; 3) chorobą Duhringa; 4) chorob" },
  138: { text: "The only statement regarding the PPV23 vaccine is false - it is a polysaccharide vaccine against pneumococci containing capsular polysaccharide of each of the 23 serotypes of Streptococcus pneumoniae. It is intended for active immunization of people aged 2 years and older who are at increased risk of morbidity and mortality due to diseases caused by Streptococcus pneumoniae.\nThe remaining statements are true.", key: "A", consensusPct: 65, doctorsN: 13056, topic: "pediatria / Szczepienia ochronne", konsyliumStem: "Wskaż fałszywe stwierdzenie dotyczące szczepionek:" },
  139: { text: "Let's analyze the individual answer options in the question:\nA) True. Impetigo contagiosum is the most common bacterial skin infection in children, especially in preschool and early school age.\nB) That's right - it's \"an infectious disease of the superficial layers of the skin, most often caused by S. aureus, but also by Streptococcus pyogenes.\"\nC) Yes, these are the characteristic symptoms of bullous impetigo.\nD) Yes - complications of impetigo contagiosum may include post-streptococcal glomerulonephritis, cellulitis, osteomyelitis, purulent arthritis and sepsis.\nE) False. Lisch nodules are an eye lesion characteristic of neurofibromatosis type 1 - a genetic disease classified as phakomatoses.\nTherefore, the correct answer to the question is E.\nSource:\nW.Kawalec, Pediatrics, 2018, Volume II, pp. 1150-1151\nhttps://www.mp.pl/dermatologia/wytyczne/270954,liszajec-zakazny-szybkie-leczenie-to-mjsze-ryzyko-rozmieszenia-sie-choroby,1", key: "E", consensusPct: 70, doctorsN: 12118, topic: "", konsyliumStem: "Wskaż fałszywe stwierdzenie dotyczące liszajca zakaźnego:" },
  141: { text: "The described case is most suggestive of Turner syndrome, the typical features of which are short stature, lack of puberty, primary amenorrhea, infertility and typical dysmorphic features - triangular face shape, low hairline on the forehead and nape, epicanthus wrinkles, and oblique palpebral fissures. Heart defects occur in 20% of patients with Turner syndrome, and the most common one, found in as many as 48%, is coarctation of the aorta.\nKlinefelter syndrome is characterized by tall stature and long limbs. Patients with Prader-Willi syndrome are short, have hypogonadism and facial dysmorphic features, but heart defects do not occur more often than in the general population. Characteristic features of Angelman syndrome include facial dysmorphia, ataxia, microcephaly and fits of laughter inappropriate to the situation. In Noonan syndrome, in addition to the typical facial dysmorphic features, short stature, hematological abnormalities and heart defects are observed, but the most common of them is pulmonary artery stenosis.\nSource: Pediatrics. Vol. 1-2. Wanda Kawalec, Ryszard Grenda, Helena Ziółkowska, Warsaw, Wydawnictwo Lekarskie PZWL, 2013", key: "D", consensusPct: 81, doctorsN: 11602, topic: "pediatria / Genetyczne uwarunkowania chorób", konsyliumStem: "W przypadku stwierdzenia u dziewczynki niskorosłości, pierwotnego braku miesiączki, zwężenia cieśni aorty oraz dysmorfii twarzy najbardziej prawdopodobnym rozpoznaniem klinicznym j" },
  142: { text: "The description presented in point D corresponds to vasovagal syncope. Cardiogenic syncope may occur in the course of organic heart disease and/or arrhythmia. Syncope occurs when cardiovascular disease prevents cardiac output from increasing sufficiently to meet circulatory needs. In organic heart diseases, syncope results from obstruction of blood outflow from the ventricles or myocardial dysfunction, while in children with rhythm and conduction disorders, it results from a significant reduction or acceleration of the heart rate.\nCardiac diseases that predispose to syncope in children and adolescents include:\n1. Heart defects with obstruction of blood outflow from the heart chambers\n2. Heart diseases related to myocardial dysfunction, including: : myocarditis, dilated cardiomyopathy, Kawasaki disease and others\n3. Cardiac rhythm and conduction disorders.\nSource: \"Cardiogenic syncope in children\"\nDepartment of Pediatric Cardiology and General Pediatrics, Medical University of Warsaw\nHead of the Clinic: dr hab. med. Bożena Werner, prof. emergency WUM", key: "D", consensusPct: 65, doctorsN: 12531, topic: "", konsyliumStem: "Do przyczyn omdleń kardiogennych u dzieci nie zalicza się:" },
  143: { text: "A foreign body in the bronchial tree may cause choking resulting in circulatory arrest. In this case, start CPR.\nIf circulatory arrest does not occur and the foreign body is not expelled from the respiratory tree, recurrent pneumonia may occur in this area. Treatment with standard antibiotics may not be sufficient, and the time needed to achieve clinical improvement in the patient may be longer. Symptoms of a foreign body in the respiratory tract include asymmetrical alveolar sounds, muffled convexity, decreased thoracic tremor (physical examination), atelectasis in the CLP X-ray (shading, shift of the mediastinum towards atelectasis, elevation of the dome of the diaphragm and interlobular fissure on the side of atelectasis).\nSource: Emergency medicine in questions and answers. Vincent J. Markovchick, Peter T. Pons, Katherine M. Bakes. Ed. Jerzy Robert Ładny, Marzena Wojewódzka-Żelezniakowicz. Medipage 2016.\nInternal Medicine 2017/2018, small manual; Practical Medicine, Kraków, 2017; p. 97.\nEuropean Resuscitation Council Guidelines 2015, ch. \"Advanced resuscitation procedures in children\".", key: "D", consensusPct: 85, doctorsN: 10872, topic: "", konsyliumStem: "Ciało obce zalegające w oskrzelu może powodować poniższe, z wyjątkiem:" },
  144: { text: "The most common complication of streptococcal angina is a peritonsillar abscess. Other possible complications include: inflammation of the lymph nodes in the neck, inflammation of the middle ear, mastoiditis, and rheumatic fever.\nSource: National Antibiotic Protection Program - Recommendations for management of community-acquired respiratory infections 2017.", key: "D", consensusPct: 78, doctorsN: 11676, topic: "pediatria / Choroby zakaźne", konsyliumStem: "Najczęstszym powikłaniem anginy paciorkowcowej u dzieci jest:" },
  145: { text: "Strabismus should be carefully examined to discover the cause and treat it, if possible. Strabismus sometimes runs in families. Temporary strabismus occurs until the age of 3 months. Severe epicanthic folds may give the impression of strabismus. Each infant with strabismus persisting after the third month of life should be referred for a specialist ophthalmological consultation. The most common cause is refractive error, but cataracts, retinoblastoma and other intraocular causes should always be ruled out. When diagnosing strabismus in children, the following are used:\n- corneal reflection test (Hirschberg) - the easiest method of detecting strabismus; involves causing light to reflect on both corneas simultaneously. The light reflectors should be in the same position in both eyes. If this is not the case, it indicates the presence of strabismus.\n- Cover test (alternately uncovering/covering the eyes test) - if a child has strabismus and the fixating eye is covered, the squinting eye changes position to take over the fixation.\nThe Adams test refers to a visual assessment to determine the presence of structural or functional scoliosis.\nSource: \"Pediatria\" Issue 5; 2018; Tom Lissauer; Ch. 4", key: "B", consensusPct: 70, doctorsN: 12424, topic: "pediatria / Podstawy okulistyki i otolaryngologii", konsyliumStem: "Testami służącymi do diagnozowania zeza u dzieci są: 1) test naprzemiennego zakrywania i odkrywania oczu; 2) test badania refleksów rogówkowych; 3) test Hirschberga; 4) tzw. cover " },
  146: { text: "It is essential to implement preventive measures after contact with infected Neisseria meningitidis. Infections caused by this bacterium most often result in meningitis. Infection occurs through droplets or direct contact with the body fluids of an infected person. The clinical course is characterized by rapidly progressive symptoms and a poor prognosis - mortality is approximately 10-12%, and permanent neurological complications are observed in 20% of patients. Chemoprophylaxis is recommended to all people who had close contact with the patient in the 7 days preceding the illness, i.e. household members and people in direct contact with respiratory secretions. One of 3 antibiotics is used:\n- ceftriaxone,\n- rifamipicin,\n- ciprofloxacin.\nPrevention should be implemented within 14 days of illness, and ideally within 24 hours.\nChemoprophylaxis is also recommended after contact with a person with confirmed pertussis. The same antibiotics are used in prevention as in treatment, i.e. macrolides or co-trimoxazole.\nAfter contact with people with chickenpox or measles, a single dose of vaccination may be administered as post-exposure prophylaxis. In the case of chickenpox, the vaccine can be administered up to 5 days after exposure, although the greatest effectiveness is achieved when the preparation is administered within 3 days of exposure. After contact with a measles patient, in previously unvaccinated or vaccinated patients with one dose, the vaccine can be administered as post-exposure prophylaxis within 72 hours after contact.\nSource: Pediatrics, Editors: Kawalec Wanda, Grenda Ryszard, Ziółkowska Helena, 2014, PZWL\nhttp://antybioticy.edu.pl/", key: "D", consensusPct: 72, doctorsN: 12170, topic: "pediatria / Choroby zakaźne", konsyliumStem: "W których z niżej wymienionych chorób zaleca się profilaktykę poekspozycyjną, czyli po kontakcie ze źródłem zakażenia? 1) świnka; 2) odra; 3) krztusiec; 4) ospa wietrzna; 5) zakaże" },
  148: { text: "Gardner's syndrome is a familial polyposis syndrome (the number of polyps in the large intestine reaches hundreds or thousands). It results in the formation of multiple polyps such as adenomas in the large intestine, osteomas and soft tissue tumors.\nSource: Internal Szczeklik 2018.", key: "A", consensusPct: 67, doctorsN: 12680, topic: "", konsyliumStem: "Obecność w badaniu endoskopowym przewodu pokarmowego mnogich polipów gruczolakowatych oraz współistniejące włókniaki tkanek miękkich ramion i podudzi nasuwają podejrzenie:" },
  151: { text: "Nephrotic syndrome is a condition caused by increased proteinuria, which results in hypoalbuminemia and edema. The cause of the syndrome is unknown, but in a few cases it may be a secondary phenomenon in the course of systemic diseases, such as Schonlein-Henoch purpura or other vasculitis, systemic lupus erythematosus, infections (e.g. malaria) or allergens (e.g. after bee stings). The clinical symptoms of nephrotic syndrome include:\n- swelling around the eyes (especially after waking up) - the earliest symptom\n- swelling of the scrotum or vulva, lower limbs (shins), and around the ankle joints\n- ascites\n- shortness of breath caused by pleural effusion and abdominal enlargement\n- peritonitis, septic arthritis or sepsis due to loss of protective immunoglobulins in the urine\nSource: Source: \"Pediatria\" Issue 5; 2018; Tom Lissauer; Ch. 19", key: "E", consensusPct: 75, doctorsN: 11976, topic: "pediatria / Choroby układu wydzielania wewnętrznego", konsyliumStem: "Siedmioletni chłopiec z alergią pokarmową, ze wstrząsem anafilaktycznym po wypiciu mleka krowiego w wywiadzie, zgłosił się do lekarza rodzinnego z powodu ogólnego osłabienia oraz o" },
  152: { text: "According to the recommendations of the Polish Diabetes Association from 2018. The therapeutic goal in children and adolescents with diabetes, regardless of its type, is a glycated hemoglobin (HbA1c) value less than or equal to 6.5%.", key: "A", consensusPct: 6, doctorsN: 11092, topic: "pediatria / Cukrzyca", konsyliumStem: "Docelowa wartość HbA1c u dzieci przedszkolnych z cukrzycą typu 1 wynosi:" },
  153: { text: "The best way to avoid cow's milk antigens is to breastfeed. In situations where such feeding is impossible (usually due to insufficient amount of breast milk), there is a tradition of replacing breast milk with goat's milk, much less often with sheep's milk, and very exceptionally with mare's milk. However, all the milks mentioned above come from ungulates and have many common features, and above all, their proteins cross-react with each other. Although giving goat or sheep milk sometimes brings some relief to children with cow's milk allergy, it is small, only temporary and does not always occur.\nSource:\nhttps://www.mp.pl/pacjent/alergie/chorobyalergiczne/alergeny/pokarmowe/58437,alergia-na-mleko-kozie-i-owcza\n, \"Allergy to goat and sheep milk\", Prof. Ph.D. med. Edward Rudzki\nAllergens, Medycyna Practical, Kraków 2009", key: "D", consensusPct: 85, doctorsN: 10929, topic: "", konsyliumStem: "Do profilaktyki alergii pokarmowej nie należy:" },
  154: { text: "Scarlet fever (scarlet fever) is an acute infectious disease with pharyngitis, characteristic small-spotted rash and fever, caused by group A B-hemolytic streptococci. The onset is sudden. There is fever, headache, chills, vomiting and abdominal pain. In the following hours, pharyngitis and a small-spotted rash develop. The fever reaches 39-40 degrees in the first 2 days of the disease, then decreases. Inflammation of the pharynx and palatine tonsils are as in streptococcal pharyngitis. The rash usually appears within 24-48 hours of the disease, exceptionally with the first symptoms. The tongue is initially covered with a white coating (coated tongue), which disappears from the periphery. In the following days, bright red lingual papillae (raspberry tongue) become visible. Hypersensitivity to gustatory, thermal and tactile stimuli is characteristic. The palate and uvula may be swollen and red, with a rash.\nSource: \"Pediatria\" W. Kawalec, 2018, 2nd ed.; Volume II; Chapter 19.8.1", key: "C", consensusPct: 84, doctorsN: 11168, topic: "", konsyliumStem: "Nagły początek choroby u dziecka przebiegający z wysoką gorączką, bólami głowy, wymiotami, drobnoplamistą wysypką i „językiem malinowym” to opis kliniczny:" },
  155: { text: "The carbohydrate exchanger is a unit used in diabetes to determine the dose of insulin depending on the type and amount of food. 1 WW is 10 grams of digestible carbohydrates. 1 WW is 40 kcal/167 kJ.\nFor example:\nBrown rice 60 g\n100 g of brown rice contains 68 g of carbohydrates (information from the nutritional table)\n60 g of brown rice contains 41 g of them,\n41 g is 4.1 WW", key: "B", consensusPct: 86, doctorsN: 11009, topic: "", konsyliumStem: "Definicja 1 wymiennika węglowodanowego (WW) obejmuje ilość produktu zawierającego:" },
  156: { text: "The oral glucose tolerance test (OGTT) involves determining the glucose concentration in venous blood plasma 120 minutes after drinking a solution containing 75 g of glucose. It should be performed on an empty stomach, without previously limiting carbohydrate intake, in the morning, in a well-rested person, after a good night's sleep. It is used to diagnose diabetes and other hyperglycemic disorders.\nThe criteria for diagnosing diabetes are: symptoms of hyperglycemia and random blood glucose ≥ 200 mg/dl (≥ 11.1 mmol/l), fasting blood glucose twice ≥ 126 mg/dl (≥ 7.0 mmol/l), 120-minute OGTT blood glucose ≥ 200 mg/dl (≥ 11.1 mmol/l).\nIf in the 120th minute of the test we receive an incorrect result, but not meeting the criteria for diabetes (i.e. in the range of 140-199 mg/dl), then we diagnose impaired glucose tolerance (IGT).\nClinical recommendations for the management of patients with diabetes 2018, PTD", key: "C", consensusPct: 78, doctorsN: 11593, topic: "pediatria / Cukrzyca", konsyliumStem: "Wartość glikemii w surowicy krwi żylnej rzędu 156 mg/dl w 120. minucie testu OGTT u dziecka interpretuje się jako:" },
  157: { text: "In the empirical treatment of uncomplicated upper urinary tract infections according to the PTNFD guidelines, drugs such as:\n- third generation cephalosporins,\n- second generation cephalosporins,\n- penicillins with beta-thalkamase inhibitors,\n- ampicillin with an aminoglycoside,\n- fluoroquinolones.\nIn older children (>6 months of age), third-generation cephalosporins are usually used, and in the youngest children (due to the suspicion of Gram-positive bacteria) ampicillin and aminoglycosides (e.g. gentamicin).\nSource: PTNFD recommendations on the management of a child with a urinary tract infection. Polish Society of Pediatric Nephrology.", key: "E", consensusPct: 63, doctorsN: 12847, topic: "", konsyliumStem: "Jakie leczenie jest rekomendowane w przypadku zakażenia układu moczowego u noworodka?" },
  160: { text: "Vaccinations prevent measles, rubella, chickenpox and rotavirus diarrhea.\nThere is no protective vaccination against the EBV virus, which causes infectious mononucleosis. A non-specific method of preventing it is that people who have the disease should not donate blood and organs for transplantation.\nSource: Interna Szczeklika 2017/2018, pp. 1148, 1153, 1156, 1168;\nhttp://szkolenia.pzh.gov.pl/szczecinki/rotawirusy/", key: "D", consensusPct: 93, doctorsN: 10468, topic: "", konsyliumStem: "W przypadku której choroby zakaźnej nie ma możliwości zastosowania profilaktyki poprzez szczepienia ochronne?" },
  161: { text: "Cerebral palsy is a non-progressive encephalopathy. According to the current definition, it is a set of symptoms defining various movement and posture disorders resulting from permanent, non-progressive brain damage in the early stages of child development - most often during labor or the perinatal period.\nSource: Pediatrics, Editors: Kawalec Wanda, Grenda Ryszard, Ziółkowska Helena, 2014, PZWL", key: "A", consensusPct: 71, doctorsN: 12261, topic: "pediatria / Choroby układu nerwowego", konsyliumStem: "Mózgowe porażenie dziecięce to niepostępujące zaburzenie czynności ruchowych i postawy spowodowane uszkodzeniem:" },
  163: { text: "The first symptoms of cystic fibrosis (CF) in infancy may be non-specific - lack of expected weight gain, prolonged neonatal jaundice, recurrent and chronic lower respiratory tract infections, chronic cough. The more typical symptoms that make us suspect CF include meconium ileus in the neonatal period, steatorrhea, and prolapse of the rectal mucosa.\nDue to increased excretion of electrolytes (Na, Cl) in sweat, dehydration may cause pseudo-Bartter's syndrome with metabolic alkalosis, hyponatremia, hypochloremia and hypokalemia.\nFurther symptoms include: shortness of breath, hemoptysis, chronic bronchopulmonary disease, bronchiectasis, nasal polyps, abdominal pain, constipation, hepatosplenomegaly, pancreatitis, pancreatic exocrine insufficiency, diabetes, cholelithiasis, biliary cirrhosis, infertility, cor pulmonale. Since 2009, all children in Poland have been screened for CF.", key: "C", consensusPct: 90, doctorsN: 10764, topic: "pediatria / Mukowiscydoza", konsyliumStem: "4-miesięczna dziewczynka została przyjęta do szpitala z powodu słabego przyrostu masy ciała, po drugim epizodzie wypadnięcia odbytu. W wywiadzie żółtaczka utrzymująca się do 5. tyg" },
  164: { text: "A urinary tract infection is diagnosed when the presence of microorganisms, most often bacteria, is found in the urinary tract above the bladder sphincter. A child's urinary tract is the second most common site of infection, after the respiratory system. UTI is the cause of approximately 5% of febrile episodes < 1 year of age. In children < 3 months of age, there is a 5-8 times male predominance. After 8 months of age, the number of UTIs in girls increases. Women develop urinary tract infections 10-50 times more often than men.\nSource: \"Pediatria\" W. Kawalec, 2018, 2nd ed.; Volume I; Chapter 14.3", key: "B", consensusPct: 72, doctorsN: 11705, topic: "", konsyliumStem: "Wskaż fałszywe stwierdzenie dotyczące zakażeń układu moczowego (ZUM) u dzieci:" },
  166: { text: "Elevated creatine phosphokinase levels are characteristic of muscular dystrophies. The highest values ​​are observed in Duchenne muscular dystrophy, lower values ​​in Becker's dystrophy, and in other dystrophies the values ​​are slightly increased. These diseases are inherited on the X chromosome, so mainly boys are affected, while girls are carriers of the disease. We observe a gradual weakening of muscle strength and, as a result, a loss of motor function.\nSource: Pediatrics, Editors: Kawalec Wanda, Grenda Ryszard, Ziółkowska Helena, 2014, PZWL", key: "E", consensusPct: 89, doctorsN: 10836, topic: "pediatria / Genetyczne uwarunkowania chorób", konsyliumStem: "Jeżeli u chłopca > 2. r.ż. stwierdzono podwyższone stężenie kinazy fosfokreatynowej oraz transaminaz, a matka zgłasza niezgrabność ruchową dziecka, należy w pierwszej kolejności po" },
  169: { text: "Infection with group A beta-hemolytic streptococcus may lead to autoimmune complications known as rheumatic fever.\n• Rheumatic fever is an acute autoimmune disease that is a late complication of infection with group A β-hemolytic streptococcus. Symptoms of rheumatic fever usually appear 2-3 weeks after pharyngitis and include inflammation of large joints, carditis, Sydenham's chorea, erythema marginalis (in 5%) on the trunk and proximal parts of the limbs, and subcutaneous nodules.\n• PANDAS is an abbreviation of the English name \"pediatric autoimmune neuropsychiatric disorder associated with streptococcal infections\" - as the name suggests, it occurs after streptococcal infections.\nAnother autoimmune complication of infection is:\n• Acute glomerulonephritis is an acute autoimmune disease that is a late complication of group A β-hemolytic streptococcus infection. It is characterized by a triad of symptoms: edema, hypertension, hematuria and erythrocyte casts (the so-called Addis triad).\nHUS occurs as a consequence of E. coli infection (typical form) or as an atypical form, after infection with Streptococcus pneumoniae, or caused by other factors, including: medications, complement component deficiencies or von Willebrand factor deficiency.\n• HUS is a thrombotic microangiopathy presenting with hemolytic anemia, thrombocytopenia and acute kidney injury. In most cases (typical HUS), the cause is infection with a verotoxin-producing bacterium - EHEC (O157:H7) or Shigella dysenteriae. The second subtype of HUS is atypical hemolytic uremic syndrome, in which the complement system is activated via an alternative route (in some patients it runs in families and recurs).\nPFAPA syndrome is an autoinflammatory disease - it is a relapsing fever syndrome.\n• The abbreviation PFAPA is an acronym of the English terms: Periodic Fever, Aphthous stomatitis (aphthous stomatitis), Pharyngitis (pharyngitis), cervical Adenitis (enlarged cervical lymph nodes). This is the most common syndrome of relapsing fevers. It belongs to the group of autoimmune diseases.\nSource: Pediatrics. Lissauer (T. Lissauer, W. Carroll) ed. 5, ed. A. Milanowski, 2019\n“What every psychiatrist should know about PANDAS: a review.”; Moretti G1, Pasquini M, Mandarelli G, Tarsitani L, Biondi M; Department of Psychiatric Sciences and Psychological Medicine, “Sapienza” University of Rome.\nUpdate from 01/02/2021", key: "C", consensusPct: 48, doctorsN: 14290, topic: "", konsyliumStem: "Zakażenie Streptococcus pyogenes może wywołać u dzieci różnorodne powikłania, które wynikają najczęściej z reakcji autoimmunologicznych. Należą do nich: 1) zespół hemolityczno-mocz" },
  170: { text: "Ad 1. The etiology of UTI in children is:\n- Gramm-negative bacteria: E. coli (the most common - up to 85%), Proteus mirabilis, Klebsiella, Enterobacter spp, Morganella morgani, Pseudomonas aeruginosa\n- Gramm positive bacteria: Staphylococcus, Streptococcus group B\n- rarely fungi and viruses\nAd 2. In small children, especially newborns and young infants, the symptoms of UTI may be non-specific (no dysuria symptoms, fever, reluctance to eat, no weight gain, restlessness and crying during micturition, drowsiness, apathy, nausea, vomiting). According to PTND recommendations, in all children up to 24 months of age with fever > 38°C without an identifiable cause, UTI should be suspected and urine tests should be performed.\nAd 3. The diagnosis of UTI is made based on the results of microbiological examination and urine sediment examination. Voiding cystoureterography is mainly used in the diagnosis of vesicoureteral reflux.\nAd 4. ​​Risk factors for UTI include: • UTI in history • Congenital defect of the urinary system • Abnormal ultrasound examination result in history (including prenatal) • Positive family history of UTI (parents, siblings) • Positive family history of congenital defects of urinary system • Bladder catheterization • Micturition disorders • Constipation, fecal incontinence • Sexual activity of girls.\nAd 5. The time and method of treatment depend on the child's condition. In the case of a lower urinary tract infection, we usually implement oral treatment for 3-5 days. In the case of the upper urinary tract, the optimal route of drug administration should be decided (oral, intravenous or sequential therapy), and treatment should be carried out for 7-10 days. All children <3 months of age should be treated intravenously in a hospital setting by choice.\nRecommendations of the Polish Society of Pediatric Nephrology regarding the management of a child with a urinary tract infection\nhttp://ptnfd.org/wp-content/uploads/2012/07/Zalecenia-PTND.pdf", key: "B", consensusPct: 82, doctorsN: 11328, topic: "", konsyliumStem: "Wskaż prawdziwe stwierdzenia dotyczące zakażeń układu moczowego u dzieci: 1) najczęstszym czynnikiem etiologicznym są bakterie Gram ujemne; 2) objawy kliniczne u noworodka są niech" },
  171: { text: "In the case described above, what attracts attention is primarily the alarm symptoms that indicate a cancer process requiring oncological diagnosis.\nThe most likely diagnosis is Hodgkin's lymphoma, but biopsy is contraindicated for diagnosis. If this disease is suspected, it is advisable to collect the entire node as soon as possible and send it for pathological evaluation.\nThe vascular pattern visible on the skin of the chest mentioned in the description most likely indicates that the mass of the tumor is pressing on the superior vena cava, which is an acute condition in oncology and an absolute indication for immediate hospitalization in an oncological treatment center.\nSource: Pediatrics. Vol. 1-2. Wanda Kawalec, Ryszard Grenda, Helena Ziółkowska, Warsaw, Wydawnictwo Lekarskie PZWL, 2013", key: "B", consensusPct: 72, doctorsN: 11985, topic: "", konsyliumStem: "16-letnia pacjentka skarżąca się na uporczywy świąd skóry, od 3 miesięcy stosuje leczenie immunosupresyjne w postaci maści i kremów, przepisanych przez dermatologa, bez żadnego rez" },
  177: { text: "The described case absolutely indicates a current viral infection of the throat.\nThe Centor-McIsaac scale allows us to assess the risk of streptococcal angina and suggests the most appropriate course of action:\nWe award 1 point for:\n- presence of enlarged anterior cervical lymph nodes,\n- no cough,\n- coatings on enlarged palatine tonsils,\n- fever >38 degrees C.\nFor age:\n- 3 - 14 years old – we add 1 point,\n- 15 – 44 years old – we do not add points,\n- > 45 years, we subtract 1 point.\nResults obtained:\n- 0 - 1 points – symptomatic treatment,\n- 2 - 3 points - it is recommended to perform a rapid test for the presence of streptococcus,\n- 4 – 5 points – possible antibiotic treatment without further diagnostics.", key: "C", consensusPct: 93, doctorsN: 10351, topic: "", konsyliumStem: "Do gabinetu lekarskiego zgłosił się 15-letni chłopiec z powodu złego samopoczucia, kataru i kaszlu. Zmierzona temperatura wynosiła 37,5°C. Lekarz w badaniu fizykalnym, poza nieżyte" },
  178: { text: "Indications for hospitalization of a child with the exception of asthma include:\n- Any severe exacerbation;\n- No response to initial treatment (1 hour) of moderate exacerbation (administration of 3 doses of salbutamol at 20-minute intervals;\n- Saturation <92%;\n- Tachycardia with cyanosis;\n- Intolerance to fluids and oral medications;\n- Social considerations;\n- Exacerbation in a child with another serious chronic disease;\n- Relatively: children 0-2 years old;\n- Recurrence of symptoms within 48 hours of treatment initiation;\n- Moderate exacerbations in a child with a history of severe exacerbations.\nA child presenting difficulties with eating, drinking and speaking is considered a child with a severe exacerbation, requiring hospitalization.\nIn the case of point B and C, we are dealing with unfinished initial treatment. It involves administering 3x doses of inhaled salbutamol at 20-minute intervals during the first hour of treatment. If the child's shortness of breath does not improve after such treatment, the child should be admitted to hospital urgently.", key: "D", consensusPct: 83, doctorsN: 10958, topic: "", konsyliumStem: "Wskazaniem do pilnego przyjęcia dziecka do szpitala z powodu astmy oskrzelowej jest/są:" },
  183: { text: "Edema is not a typical symptom of obstructive nephropathy. The renal cause of the described edema in the neonatal period (which excludes post-infectious inflammation and HUS) may be Finnish-type nephrotic syndrome or acute renal failure.\nThe question contains too little clinical data to allow for correct differentiation.\nCongenital nephrotic syndrome of the Finnish type is caused by a mutation of the gene encoding nephrin, which leads to increased permeability of the slit membrane and protein escape.\nTypical symptoms:\n- large bearing,\n- premature birth, low birth weight,\n- swelling,\n- severe proteinuria, often already in the intrauterine period,\n- characteristic features: large belly, small nose, low-set ears, deformed limbs, wide cranial sutures,\n- limpness,\n- neurological disorders.\nSource: Pediatrics. Vol. 1-2. Wanda Kawalec, Ryszard Grenda, Helena Ziółkowska, Warsaw, Wydawnictwo Lekarskie PZWL, 2013", key: "A", consensusPct: 83, doctorsN: 11255, topic: "pediatria / Neonatologia", konsyliumStem: "U 10-dniowego noworodka stwierdzono nasilone obustronne obrzęki kończyn oraz obrzęki wokół oczu o znacznym nasileniu. Najbardziej prawdopodobną przyczyną jest:" },
  187: { text: "An autosomal recessive disease is manifested only in a homozygous recessive system, which means that both alleles encoding a given trait must be present in an individual to manifest this trait. This means that parents suffering from an autosomal recessive disease are homozygous recessive, so the probability of this disease occurring in their offspring is 100% (the allele responsible for the disease will be passed on from each parent).", key: "E", consensusPct: 76, doctorsN: 11700, topic: "pediatria / Genetyczne uwarunkowania chorób", konsyliumStem: "W przypadku choroby dziedziczonej autosomalnie recesywnie ryzyko wystąpienia choroby u potomstwa dwojga chorych rodziców wynosi:" },
  191: { text: "Nowadays, tuberculosis is most often infected by adults from the child's immediate home environment (mother, father, caregiver). Children under 3 years of age are most susceptible to M. tuberculosis infection. Risk factors for tuberculosis include:\n- increased exposure to infection from adults,\n- environment of immigrants, homeless, drug addicts, alcoholics,\n- low socioeconomic status,\n- chronic diseases, e.g. the probability of developing tuberculosis increases by 30% in children on dialysis,\n- immune disorders, e.g. HIV infection,\n- malnutrition.\nIf tuberculosis is suspected in a child, the following are necessary:\n- physical examination - primarily to determine contact with a tuberculosis patient,\n- physical examination,\n- tuberculin reaction,\n- immunological tests (IGRA),\n- imaging tests - chest X-ray and other organs, chest CT, bronchoscopy,\n- bakeriological tests - bacterioscopy, genetic testing, culture; gastric lavage (3 times), induced sputum, spontaneously expectorated sputum, bronchial lavage, lymph node content, pleural fluid, cerebrospinal fluid and urine are collected for testing,\n- histopathological examination\nSource: \"Pediatria\" W. Kawalec, 2018, 2nd ed.; Volume I; Ch. 9.3.6", key: "A", consensusPct: 71, doctorsN: 11959, topic: "", konsyliumStem: "Wskaż prawdziwe stwierdzenie dotyczące gruźlicy u dzieci:" },
  193: { text: "Cystic fibrosis is the most common autosomal recessive congenital disease that shortens life in the Caucasian population. Cystic fibrosis is a multisystem disease resulting primarily from impaired ion transport through epithelial cells. In the respiratory system, this leads to a reduction in the liquid mucous layer lining the respiratory tract and the resulting disturbances in the function of the ciliary apparatus and the retention of mucopurulent secretions. The consequence is chronic endobronchial infection with specific microorganisms, such as Pseudomonas Aeruginosa. Thick meconium is produced in the intestines, causing meconium ileus in newborns. The pancreatic ducts are also blocked by the thick secretion, which leads to a deficiency of digestive enzymes and digestion and absorption disorders. Improper function of sweat glands is manifested by excessive concentration of sodium and chlorine ions in sweat.\nClinical symptoms of cystic fibrosis:\n1. Newborns - diagnosis is made based on screening; Smółkow obstruction\n2. Infants - prolonged jaundice in the neonatal period; growth impairment; recurrent respiratory infections; absorption disorders, fatty stools\n3. Younger children - bronchiectasis, rectal mucosa prolapse, nasal polyps, sinusitis\n4. Older children and adolescents - allergic bronchopulmonary aspergillosis, diabetes, liver cirrhosis and portal hypertension, pneumothorax and recurrent hemoptysis, male infertility.\nSource: \"Pediatria\" Issue 5; 2018; Tom Lissauer; Ch. 17", key: "B", consensusPct: 60, doctorsN: 13359, topic: "pediatria / Mukowiscydoza", konsyliumStem: "Do cech charakterystycznych dla mukowiscydozy nie należy/ą:" },
  194: { text: "At birth, the anterior fontanelle measures approximately 2 x 2 cm. It is located on the border of the parietal and frontal bones. Temporarily after giving birth, its dimensions may appear smaller due to the overlapping of the skull bones as they pass through the birth canal. It grows properly according to various sources: between 9 and 18 months of the child's life (Wanda Kawalec, Ryszard Grenda, Helena Ziółkowska (ed.): Pediatria, volume 1-2, Warsaw 2013, Wydawnictwo Lekarskie PZWL) or 12 and 18 months of the child's life. (Pediatrics - Manual for the State Medical Examination and the specialization examination, ed. Anna Dobrzańska and Józef Ryżko, Urban and Partner 2005).\nA bulging of the fontanel or an increase in its tension may occur when the baby cries and in the case of pathologies that increase intracranial pressure, such as bleeding into the central nervous system or meningitis.\nA slight collapse of the fontanelle may occur in healthy children in a sitting position. It may also be a pathological symptom of dehydration in the child.\nPremature closure of the fontanelle, i.e. before the child is 9 months old, may be asymptomatic or result in microcephaly, i.e. microcephaly. In turn, delayed growth may occur in premature babies, in case of vitamin D3 deficiency, e.g. in rickets, hydrocephalus and in anomalies in the structure of the skull.\nBetween 6-8 weeks of the baby's life, the posterior fontanel grows over.\nSource:\nWanda Kawalec, Ryszard Grenda, Helena Ziółkowska (ed.): Pediatrics, volume 1-2, Warsaw 2013, Wydawnictwo Lekarskie PZWL", key: "B", consensusPct: 80, doctorsN: 11645, topic: "pediatria / Neonatologia", konsyliumStem: "Wskaż prawdziwe stwierdzenia dotyczące ciemiączka przedniego: 1) bezpośrednio po porodzie kości czaszki nachodzą na siebie i ciemiączko może wydawać się mniejsze; 2) prawidłowe zam" },
  196: { text: "Meningococcal sepsis is a disease that progresses very rapidly, often even fulminantly. The child's clinical condition is serious and rapidly deteriorating.\nThromboembolic skin lesions appear quickly, sometimes preceded by a maculopapular rash, which then becomes hemorrhagic and does not disappear under pressure (i.e. the glass test!).\nSource: Pediatrics. Vol. 1-2. Wanda Kawalec, Ryszard Grenda, Helena Ziółkowska, Warsaw, Wydawnictwo Lekarskie PZWL, 2013", key: "A", consensusPct: 93, doctorsN: 10632, topic: "pediatria / Badanie kliniczne dziecka", konsyliumStem: "Chłopiec 3-letni zagorączkował do 39°C, jest apatyczny. Podczas badania lekarz stwierdził na skórze uda prawego trzy zmiany skórne. Jakie cechy zmian skórnych mogą przemawiać za ro" },
  198: { text: "Diabetic ketoacidosis (DKA) is an acute metabolic complication occurring in patients with type 1 diabetes, less often type 2. It develops in 15-70% of children with newly diagnosed diabetes. DKA develops as a result of a significant deficiency or lack of insulin. This is accompanied by excessive secretion of hormones that are antagonistic to insulin (glucagon, cortisol, adrenaline, growth hormone). Insulin deficiency leads to hyperglycemia as a result of decreased glucose consumption mainly by muscles and adipose tissue, and increased glucose production via gluconeogenesis and glycogenolysis. When hyperglycemia exceeds approximately 180 mg/dl, glycosuria develops, the patient becomes dehydrated and electrolyte disturbances occur. Hormones that act antagonistically towards insulin intensify hyperglycemia and protein and fat catabolism (lipolysis and ketogenesis). As a result of protein catabolism, amino acids are produced, which provide a substrate for the production of glucose (gluconeogenesis). The effect of lipolysis is an excess of free fatty acids and glycerol. Free fatty acids undergo re-esterification to triglycerides and beta-oxidation, which leads to the production of ketone bodies. Excessive production of ketone bodies leads to the development of metabolic acidosis.\nHypernatremia may occur in DKA. The most common electrolyte disorder is potassium deficiency.", key: "A", consensusPct: 87, doctorsN: 10968, topic: "pediatria / Cukrzyca", konsyliumStem: "W badaniach laboratoryjnych u dziecka z cukrzycą typu 1 w przebiegu kwasicy ketonowej stwierdza się:" },
  201: { text: "Bronchopulmonary dysplasia is a disease resulting from disruption of the proper development of the alveoli and pulmonary vessels. The latest definition of bronchopulmonary dysplasia according to Jobe from 2000 describes it as the need for oxygen therapy with O2 concentration > 21% for at least 28 days and:\n1) In newborns born with 30% O2 and/or positive pressure in the 36th week of postconceptional age or at discharge (severe form)\n2) In newborns born >32 weeks gestation\n- breathing atmospheric air on the 56th day of life or at discharge (mild form)\n- need to use 30% O2 and/or positive pressure on the 56th day of life or at discharge (severe form)\nThe described infant is an ex-premature baby with extremely low birth weight, meeting the basic criteria for BPD. It is also known that the baby required oxygen therapy in the 36th week of postconceptional age, so we are probably dealing with a moderate form of the disease. Both tachypnea and crackles are also part of the picture of the disease (there is no information whether they occurred suddenly or were observed long-term, but the lack of fever and negative inflammation indicators seem to suggest that it is not an acute infection).\nCurrently, changes typical for BPD in the radiological image of the lungs (atelectasis, emphysema, fibrosis) are rarely observed, therefore it is not necessary to diagnose the disease.\nSource:\nhttps://podyplomie.pl/pediatria/15417,dysplazja-oskrzelowo-plucna", key: "E", consensusPct: 78, doctorsN: 11687, topic: "pediatria / Choroby układu oddechowego", konsyliumStem: "Podczas badania czteromiesięcznego niemowlęcia stwierdzono cechy duszności, tachypnoe 75/min oraz osłuchowo nad polami płucnymi rozlane trzeszczenia. Urodzony w 28 Hbd o masie 820g" },
  206: { text: "Treatment of food allergy involves eliminating the food causing the symptoms. In the case of a breastfed infant, the mother should exclude products containing cow's milk proteins from the diet. A formula-fed child should receive special formulas with a high degree of hydrolysis or elementary formulas (mixtures with a low degree of hydrolysis will not be sufficient). Soy formulas should not be used in children <6 months of age. life.\nSource: Pediatrics. Lissauer ed. 5, ed. A. Milanowski; 2019, pp. 247, 331.", key: "A", consensusPct: 79, doctorsN: 11447, topic: "pediatria / Choroby alergiczne", konsyliumStem: "Wskaż, jakie żywienie nie jest zalecane w leczeniu alergii na białka mleka krowiego: 1) mieszankami sojowymi; 2) karmienie mlekiem matki z zastosowaniem przez nią diety eliminacyjn" },
  209: { text: "General symptoms in CD Hodgkin's include:\n- fever > 38 degrees\n- night sweats\n- loss of > 10% of body weight in the last 6 months.\nSource: \"Pediatria\" W. Kawalec, 2018, 2nd ed.; Volume I; Ch. 13.2.1", key: "C", consensusPct: 72, doctorsN: 12026, topic: "", konsyliumStem: "Objawy ogólne w chłoniaku Hodgkina u dzieci obejmują: 1) gorączkę > 38 °C; 2) ból kończyn dolnych; 3) nocne poty; 4) utratę masy ciała >10% w ciągu ostatnich 6 miesięcy; 5) bóle mi" },
  210: { text: "Prader-Willi syndrome is a genetically determined disease inherited through parental stigma. It is caused by the absence of a region of chromosome 15 from the father. The disease is multisystemic. The main clinical symptoms are hypotonia and impaired sucking reflex in infancy, impaired psychomotor development, excessive appetite leading to obesity, hypogonadism, short stature, facial dysmorphic features, and behavioral disorders.\nSource: Pediatrics, Editors: Kawalec Wanda, Grenda Ryszard, Ziółkowska Helena, 2014, PZWL", key: "A", consensusPct: 84, doctorsN: 11142, topic: "pediatria / Genetyczne uwarunkowania chorób", konsyliumStem: "Do gabinetu zgłasza się mama z 5-letnim chłopcem z powodu otyłości. U dziecka początkowo (w okresie niemowlęcym) występowały problemy z karmieniem, chłopiec był konsultowany wówcza" },
  212: { text: "HUS is a thrombotic microangiopathy characterized by a triad of symptoms: severe hemolytic anemia and thrombocytopenia, and acute renal failure. It is one of the most common causes of acute kidney failure in children. In the vast majority of cases, the cause is infection with a verotoxin-producing bacterium - an enterohemorrhagic strain of Escherichia coli (EHEC, serotype O157:H7 or O104:H4) or Shigella dysenteriae (more common in children).", key: "D", consensusPct: 87, doctorsN: 10970, topic: "pediatria / Choroby układu krwiotwórczego", konsyliumStem: "Typowy zespół hemolityczno-mocznicowy, zaliczany do mikroangiopatii zakrzepowej, charakteryzuje się u dzieci następującą triadą objawów:" },
  213: { text: "In the case of De Toni-Debre-Fanconi syndrome caused by a defect of the proximal tubule of the nephron, there are features of rickets and osteomalacia.\nIn the case of the disease mentioned above, as well as in the case of rickets, hypothyroidism or pseudohypoparathyroidism, there is no rash and persistent cradle cap. These diseases cause abnormal tooth eruption, but the gums remain unchanged.\nThese first two symptoms are characteristic only of Langerhans cell histiocytosis (LCH).\nSymptoms typical of LCH:\n- soft bulge of the skull,\n- cradle cap, difficult to remove, persists from infancy,\n- papular rash on the scalp and trunk, ranging in color from red to yellow-brown,\n- chronic discharge from the ear,\n- intensification and soreness of gums, often premature loss of erupted teeth,\n- difficult healing of sockets after tooth extraction,\n- proptosis of the eyeball,\n- polydipsia, polyuria,\n- exertional dyspnea,\n- hemoptysis,\n- fear of bleeding diathesis,\n- lymphadenopathy,\n- hepatosplenomegaly,\n- general symptoms - fever, weight loss, impaired appetite.\nSource: Pediatrics. Vol. 1-2. Wanda Kawalec, Ryszard Grenda, Helena Ziółkowska, Warsaw, Wydawnictwo Lekarskie PZWL, 2013", key: "E", consensusPct: 66, doctorsN: 12210, topic: "", konsyliumStem: "Grudkowo-plamista wysypka, niepoddająca się leczeniu ciemieniucha, rozpulchnienie dziąseł i nieprawidłowe wyrzynanie się zębów, miękkie przy palpacji uwypuklenia czaszki, a w badan" },
  214: { text: "Let's analyze the individual answer options in the question:\n1) Wilms tumor (nephroblastoma) is a kidney cancer.\n2) Neuroblastoma (sympathetic neuroblastoma) – most often develops in the adrenal glands or paravertebral sympathetic ganglia in the abdominal cavity.\n3) Non-Hodgkin's lymphoma - the most common location of this cancer is the lymph nodes located in the abdominal cavity.\n4) Medulloblastoma is a CNS tumor located mainly in the cerebellum.\n5) Dysgerminoma is a germ cell tumor of the ovary.\nThe only cancer of the above mentioned that does not develop in the child's abdominal cavity is\nMedulloblastoma.\nTherefore, the correct answer to the problem is D (1,2,3,5).\nSource:\nW.Kawalec, Pediatrics, 2018, Volume I, pp. 664, 673, 676, 683, 695", key: "D", consensusPct: 72, doctorsN: 11903, topic: "", konsyliumStem: "Wskaż nowotwory mogące rozwijać się w jamie brzusznej u dziecka: 1) guz Wilmsa; 2) neuroblastoma; 3) chłoniak nieziarniczy; 4) medulloblastoma; 5) dysgerminoma. Prawidłowa odpowied" },
  215: { text: "According to the guidelines, tetanus prophylaxis in a given case (in a low-risk person who had the last dose of vaccination 5-10 years ago) includes one booster dose of diphtheria-tetanus or tetanus vaccine. Therefore, answer B is correct.", key: "B", consensusPct: 66, doctorsN: 12514, topic: "", konsyliumStem: "12-latek zgłasza się do lekarza rodzinnego po zaopatrzeniu skaleczenia nogi w ogrodzie z pytaniem o profilaktykę tężca. Chłopiec otrzymał w przeszłości kompletne szczepienie podsta" },
  216: { text: "Symptoms of hemolytic-uremic syndrome include: hemolytic anemia, thrombocytopenia, renal failure, often with hypertension and fever. Neurological symptoms are rarely present.", key: "A", consensusPct: 81, doctorsN: 11436, topic: "", konsyliumStem: "Do cech zespołu hemolityczno-mocznicowego należą: 1) niedokrwistość hemolityczna; 2) nadpłytkowość; 3) małopłytkowość; 4) ostra niewydolność nerek z oligurią; 5) splenomegalia. Pra" },
  217: { text: "The described case presents a patient with erythema infectiosum. Initially, you feel unwell and are accompanied by fever. After approximately 7-10 days, skin lesions appear on the cheeks in the form of erythema with sharp borders (does not cover the bridge of the nose and around the mouth) and in the form of garland-like, reticulated erythematous eruptions with brightening in the center, among others. on the trunk, lower limbs and buttocks – answer A is correct.\nSource:\nhttps://www.mp.pl/interna/chapter/B16.II.18.1.10\n.\nMeasles - heralding symptoms are high fever, dry cough, conjunctivitis with photophobia, and lymphadenopathy. On the mucous membrane of the cheeks near the premolars, gray-white papules appear - Koplik's spots (pathognomonic symptom), and then a maculopapular rash appears, initially on the head (does not affect the hairy skin), and is descending (later affecting the trunk and limbs).\nsource:\nhttps://www.mp.pl/interna/chapter/B16.II.18.1.3\n.\nScarlet fever - symptoms typical of angina (fever, sore throat, vomiting) and the occurrence of a rash - erythema (sparing Filatov's triangle on the face), the presence of Pastia's symptom (linear petechiae in natural skin folds - due to increased fragility of capillaries), a few days after the rash disappears, large-lobed peeling of the skin occurs, the tongue initially with a white coating, then with a \"raspberry\" appearance.\nSource:\nhttps://podyplomie.pl/pediatria/12158,plonica\nRubella - initially there is malaise, mild fever, muscle pain, headaches, dry cough, after a few days there is a painful enlargement of the lymph nodes (occipital, nuchal and retro-auricular), after a day a pink maculopapular rash appears (it also affects Filatov's triangle on the face). The skin lesions may be accompanied by itching and disappear after 2-3 days.\nsource:\nhttps://www.mp.pl/interna/chapter/B16.II.18.1.5\n.\nErythema multiforme - skin lesions with the appearance of a shooting target (the central part is darker, surrounded by a pale border and an erythematous ring).\nSource:\nhttps://www.mp.pl/pediatria/artykuly-wytyczne/artykuly-przegladowe/152985,diagnostyka-wykwitow-obraczkowatych-u-dzieci", key: "D", consensusPct: 68, doctorsN: 12569, topic: "", konsyliumStem: "Do lekarza zgłaszają się rodzice z dzieckiem w wieku przedszkolnym. Od ponad tygodnia obserwują podwyższoną ciepłotę ciała, a od dwóch dni zmiany na skórze - rumień na obu policzka" },
  221: { text: "Erythema migrans (also: creeping) is a pathognomonic symptom of Lyme disease. It appears 3-30 days after the tick bite. It is characterized by a rapidly enlarging peripheral spot with a diameter of >5 cm and brightening inside. It is not painful, it does not itch, the edges are clearly defined, and it remains in the plane of the skin.\nIts finding is an indication for the implementation of antibiotic therapy - amoxicillin 500 mg three times a day (children: 50 mg/kg/d) for 14-21 days. Doxacycline, macrolides, penicillins and cephalosporins are also used.", key: "E", consensusPct: 89, doctorsN: 10672, topic: "", konsyliumStem: "Do lekarza zgłosił się chory z powiększającym się rumieniem na ramieniu - aktualnie średnica około 12 cm. Na podstawie wywiadu i wyglądu zmiany skórnej lekarz rozpoznał rumień wędr" },
  226: { text: "The cause of hypertension in the newborn is not congenital adrenal hyperplasia, because in this disease, hypotension occurs due to impaired synthesis of cortisol and often aldosterone.\nPossible causes:\n- congenital defects of large arteries, e.g. renal artery stenosis, coarctation of the aorta, patent ductus arteriosus;\n- renal artery clot,\n- congenital kidney defects,\n- acquired kidney diseases,\n- tumors,\n- bronchopulmonary dysplasia,\n- surgical procedures in the abdominal cavity,\n- hypercalcemia,\n- overhydration,\n- thyrotoxicosis in the mother,\n- mother's poisoning, e.g. with cocaine,\n- intracranial hypertension,\n- sleep apnea,\n- disturbances in the biosynthesis of adrenal cortex hormones.\nSource: Pediatrics. Vol. 1-2. Wanda Kawalec, Ryszard Grenda, Helena Ziółkowska, Warsaw, Wydawnictwo Lekarskie PZWL, 2013", key: "D", consensusPct: 49, doctorsN: 14742, topic: "pediatria / Neonatologia", konsyliumStem: "Do przyczyn nadciśnienia tętniczego u noworodka nie należy:" },
  227: { text: "Molluscum contagiosum is a skin disease caused by the MCV virus, a member of the Poxvirus family. The skin lesions are characteristic - hard, translucent nodules with a depression in the center, ranging from 1 mm to 1 cm in diameter. They are especially common in people with reduced immunity. They disappear without leaving any scars.\nSource: Pediatrics, Editors: Kawalec Wanda, Grenda Ryszard, Ziółkowska Helena, 2014, PZWL", key: "E", consensusPct: 89, doctorsN: 10818, topic: "pediatria / Choroby zakaźne", konsyliumStem: "Zmiany skórne występujące u dzieci, zwłaszcza w immunosupresji, w postaci małych, perłowych grudek z pępkowatym zagłębieniem w części środkowej to:" },
  228: { text: "Acute adrenal insufficiency - a set of clinical symptoms caused by a sudden, significant cortisol deficiency, which is life-threatening. Adrenal crisis is a direct threat to life. Symptoms of crisis: increased feeling of weakness, impaired consciousness, vomiting, diarrhea, decreased blood pressure and tachycardia, shock. Biochemical tests reveal: hyponatremia, hypoglycemia and hyperkalemia.\nSource: \"Interna Szczeklik\" Small textbook, Andrzej Szczeklik, 2019/20, Ch. 11.1.3", key: "E", consensusPct: 85, doctorsN: 11008, topic: "pediatria / Choroby układu wydzielania wewnętrznego", konsyliumStem: "Do objawów ostrej niedoczynności kory nadnerczy u dzieci nie można zaliczyć:" },
  229: { text: "The symptoms described in the question (cyanosis, shortness of breath, tachypnea and a sunken \"boat-like\" abdomen) indicate\ndiaphragmatic hernia.\nTherefore, the correct answer to the question is D.\nWhat symptoms typically occur in other diseases?\nA) Pulmonary aplasia means the failure of this organ to develop even though it is present. Bilateral aplasia is a lethal defect, while unilateral aplasia causes compensatory hypertrophy of the other lung. Typical symptoms of this condition include respiratory failure or breathing disorders seen in the newborn.\nB) Typical symptoms of a cyanotic heart defect (early cyanotic) are symptoms caused by a right-to-left shunt in the heart (cyanosis, heart failure, heart murmurs).\nC) An umbilical hernia manifests itself as a (usually painless) bulge, soft lump in and around the navel.\nE) The presence of a foreign body in the respiratory tract usually manifests itself as a sudden onset of cough in a child whose general condition is good (so far). Asymmetrical breath sounds and percussive sounds are often present.\nSource:\nhttps://www.uczkin.pl/ciaza/przepuklina-przeponowa\nW.Kawalec, Pediatrics, 2018, p. 342", key: "D", consensusPct: 78, doctorsN: 11548, topic: "pediatria / Gastroenterologia", konsyliumStem: "U noworodka po porodzie obserwuje się objawy niewydolności oddechowej: sinicę, duszność, tachypnoe oraz zapadnięty „łódkowaty” brzuch. Objawy wskazują typowo na:" },
  231: { text: "The Ballard scale is used to assess the maturity of newborns\n.\nIt assesses 7 morphological features (skin, fetal fuzz, grooves on the feet, nipples, ear, male genital organs, female genital organs) and 6 neurological features (posture, hand bending angle, arm position, popliteal angle, sash sign, heel to ear).\nTherefore, the correct answer to the question is D.\nOther scales:\n- Tanner - determines the progress of sexual maturation\n- Glasgow - there are two scales with this name: 1) assesses the state of consciousness 2) assesses the severity of AP\n- NYHA – used to classify the severity of heart failure symptoms\n- Apgar – used to assess the condition of the newborn immediately after birth\nSource:\nThe Journal of Pediatrics 119(3), I.L. Ballard, J.C. Khoury, K. Wedig et al., New Ballard Score, expanded to include extremely premature infants, p. 418\nhttps://www.mp.pl/pacjent/pediatria/prawidlowyrozwoj/rozwojfizyczny/78070,postepowanie-z-noworodkiem-i-ocena-jego-stanu-na-sali-porodowej", key: "D", consensusPct: 74, doctorsN: 11721, topic: "pediatria / Skale w pediatrii", konsyliumStem: "Do oceny dojrzałości noworodka służy skala:" },
  233: { text: "Mitochondrial diseases, caused by mutations in the mitochondrial genome, are inherited in the maternal line. This is due to the fact that mitochondria are passed on almost exclusively from the mother (almost all of them come from the oocyte, and very few are passed on in the sperm - those from the father are then destroyed in the zygote). Symptoms of mitochondrial diseases mainly concern tissues with high energy demand (nervous system, skeletal muscles). Examples of this type of disease are myoclonic epilepsy, Leber's hereditary optic nerve atrophy, Kearns-Sayre syndrome, and Pearson syndrome. Offspring of both sexes are affected.", key: "A", consensusPct: 90, doctorsN: 10742, topic: "pediatria / Genetyczne uwarunkowania chorób", konsyliumStem: "W przypadku choroby mitochondrialnej jest ona przekazywana potomstwu:" },
  234: { text: "Contraindications to vaccination in children are very similar to those in adults.\nThere are no contraindications to vaccination in adults and children.\nA universal contraindication to vaccination for any vaccine is a systemic, severe anaphylactic reaction after administration of a previous dose of the vaccine or an anaphylactic reaction to any component of the vaccine. This applies to properly diagnosed and classified anaphylactic shock, i.e. involvement of at least two systems or swelling of the oral cavity and/or larynx.\nLive vaccines should not be administered in the case of:\n• severe congenital and acquired immunodeficiencies,\n• leukemia, lymphoma,\n• generalized cancer process,\n• chemotherapy, radiotherapy, high dose of steroids,\n• bone marrow transplantation,\n• organ transplantation.\nAnaphylaxis may also affect substances included in the vaccine, i.e. egg white, gelatin, streptomycin, yeast.\nRelative contraindications to vaccination are:\n• acute severe or moderately severe illness, including high fever (mild illness, e.g. a cold, is not a contraindication to vaccination),\n• exacerbation of a chronic disease,\n• a history of anaphylactic shock that occurred in another situation (unrelated to the administration of the vaccine). Such patients are at higher risk of anaphylaxis after vaccination.\nIn the case of a disease with high fever or exacerbation of a chronic disease, you should wait until the symptoms disappear and the patient's condition improves.\nSource:\nhttps://szkolenia.pzh.gov.pl/faq/jakie-sa-powiedzwskazania-do-szczeien-doroslych/", key: "D", consensusPct: 79, doctorsN: 11341, topic: "", konsyliumStem: "Bezwzględnym przeciwwskazaniem do wykonania szczepienia u dziecka jest:" },
  235: { text: "Nephrotic syndrome is a condition caused by increased proteinuria, which results in hypoalbuminemia and edema. The cause of the syndrome is unknown, but in a few cases it may be a secondary phenomenon in the course of systemic diseases, such as Schonlein-Henoch purpura or other vasculitis, systemic lupus erythematosus, infections (e.g. malaria) or allergens (e.g. after bee stings). The clinical symptoms of nephrotic syndrome include:\n- swelling around the eyes (especially after waking up) - the earliest symptom\n- swelling of the scrotum or vulva, lower limbs (shins), and around the ankle joints\n- ascites\n- shortness of breath caused by pleural effusion and abdominal enlargement\n- peritonitis, septic arthritis or sepsis due to loss of protective immunoglobulins in the urine\nThe first-line treatment, effective in 85-90% of children, is oral corticosteroid therapy (prednisolone).\nSource: \"Pediatria\" Issue 5; 2018; Tom Lissauer; Ch. 19", key: "A", consensusPct: 87, doctorsN: 11239, topic: "pediatria / Choroby układu wydzielania wewnętrznego", konsyliumStem: "Lekiem stosowanym w I rzucie leczenia idiopatycznego zespołu nerczycowego u dzieci jest:" },
  236: { text: "Listed among replies\nheartburn is a typical symptom of gastrointestinal reflux in older children\n– is not an alarming symptom.\nTherefore, the correct answer to the question is C.\nThe alarm symptoms of reflux disease are:\n- blood in regurgitated food\n- anemia\n- malnutrition\n- swallowing disorders\n- aspiration (manifested by recurrent pneumonia, frequent bouts of coughing with shortness of breath)\n- onset of symptoms >6 months of age\n- persistence of symptoms >1 year of age\nSource:\nW.Kawalec, Pediatrics, 2018, Volume II, pp. 505-506\nW.Kawalec, Pediatrics, 2018, Volume I, p. 237\nhttps://www.mp.pl/interna/chapter/B16.II.4.2\n.", key: "C", consensusPct: 81, doctorsN: 11183, topic: "", konsyliumStem: "Refluks żołądkowo-przełykowy, czyli patologiczny odpływ treści z żołądka do przełyku jest krótkotrwałym zjawiskiem w warunkach fizjologicznych. Jeśli utrzymuje się długo lub jego e" },
  237: { text: "Schonlein-Henoch disease is the most common form of systemic vasculitis in developmental age. The disease occurs at all ages, with a predisposition to the disease in young children, with a peak at the age of 3-4 years. Boys get sick twice as often as girls. The pathogenesis is unknown. It is known that the development of this type of vasculitis is associated with the formation of immune complexes composed of IgA and the C3 complement component. The deposition of complexes in the vessel wall initiates the inflammatory process. In most cases, the onset of the disease is preceded by an infection of the upper respiratory tract with B-hemolytic streptococcus, mycoplasma or Legionella. Other etiological factors include viral infections (parvovirus B19, CMV, HBV, HCV), medications (penicillin, aspirin), food products (nuts, blackberries), vaccinations and low temperature. Schonlein-Henoch disease usually has a mild, self-limiting course, but with a tendency to relapse. Diagnosis of the disease is based on the typical clinical picture and diagnostic criteria.\n1. Palpable skin purpura or petechiae mainly in the lower limbs not related to thrombocytopenia - a concomitant condition and\n2. At least 1 of the following:\n- diffuse colicky abdominal pain\n- typical histopathological changes in the skin (leukocytoclastic vasculitis with predominance of IgA deposits) or in the kidneys (proliferative glomerulonephritis with predominance of IgA deposits)\n- joint changes\n- nephropathy - proteinuria (> 0.3 g/24h) or the presence of albumin in the morning urine, hematuria or erythrocyturia > 5 wpw.\nSource: \"Pediatria\" W. Kawalec, 2018, 2nd ed.; Volume II; Ch. 18/02/10", key: "A", consensusPct: 63, doctorsN: 13073, topic: "", konsyliumStem: "Wskaż fałszywe zdanie dotyczące choroby Schönleina-Henocha:" },
  238: { text: "A boy with features of nephritic syndrome (arterial hypertension, proteinuria, hematuria, although without signs of acute renal failure). Elevated ASO and decreased complement C3 are typical of acute poststreptococcal glomerulonephritis, which is the most common cause of nephritic syndrome in children. School-age children are typically affected, with a predominance of boys. The disease can be very severe, but the above-mentioned triad of symptoms is usually observed.\nIgA nephropathy is the most common cause of glomerulonephritis in children, usually manifesting itself in the form of recurrent episodes of hematuria, especially during respiratory infections, and in several percent of cases, nephrotic syndrome or rapidly progressive KZN may occur. One quarter of patients may suffer from hypertension. Elevated IgA levels are usually found (poor diagnostic value), and diagnosis requires a kidney biopsy.\nBasement membrane nephropathy is a congenital glomerulopathy characterized by a lower than normal thickness of the basement membrane of the glomerular capillary. Hematuria occurs, typically there is no proteinuria, no hypertension, and renal function is not impaired.\nTypical symptoms of UTI are dysuria, frequent urination, urgency, enuresis, pain in the suprapubic area, unpleasant urine odor, sometimes hematuria (lower urinary tract) and fever, abdominal pain, tenderness in the lumbar region (upper urinary tract).\nNephrotic syndrome consists of massive proteinuria accompanied by decreased albumin levels, hyperlipidemia and edema. It is usually not associated with inflammatory changes in the histological examination of the kidneys.", key: "A", consensusPct: 81, doctorsN: 11420, topic: "pediatria / Choroby układu moczowego", konsyliumStem: "Pacjent 14-letni został przyjęty do Kliniki z powodu nadciśnienia tętniczego, obrzęków, białkomoczu i krwinkomoczu. W badaniach laboratoryjnych stwierdzono: podwyższone miano ASO, " },
  239: { text: "In the case of the systemic form of juvenile idiopathic arthritis, we may experience minor joint involvement for many years. However, general symptoms may predominate, such as fever, skin lesions, lymphadenopathy, hepatosplenomegaly, and serositis. Laboratory tests reveal significantly increased inflammation markers, significant anemia and thrombocythemia.\nIn oligoarticular juvenile idiopathic arthritis, inflammatory markers may be slightly elevated or normal. Increased exponents do not occur in fibromyalgia and aseptic necrosis of the tibial tuberosity.\nSource: Wanda Kawalec, Ryszard Grenda, Helena Ziółkowska (ed.): Pediatria, volume 1-2, Warsaw 2013, Wydawnictwo Lekarskie PZWL", key: "B", consensusPct: 62, doctorsN: 13159, topic: "pediatria / Podstawy reumatologii", konsyliumStem: "Bardzo wysokie wartości wskaźników ostrej fazy są charakterystyczne dla:" },
  241: { text: "Primary hyperparathyroidism is associated with excessive release of parathyroid hormone. The most common cause is parathyroid adenoma. Increased release of parathyroid hormone causes increased osteolysis and release of calcium from bones into the blood (leading to osteoporosis), as well as increased calcium absorption in the gastrointestinal tract and urinary excretion of calcium and phosphates.\nComplications of chronic hypercalcemia include:\npolyuria, kidney stones,\npeptic ulcer disease of the stomach and duodenum,\nacute pancreatitis, biliary stones,\nweakened muscle strength and tendon reflexes,\nheadaches, depression.\nPrimary hyperparathyroidism does not cause cirrhosis.", key: "C", consensusPct: 71, doctorsN: 12468, topic: "", konsyliumStem: "Do objawów nadczynności przytarczyc nie należy:" },
  242: { text: "Neurofibromatosis type 1 (NF-1) occurs in 1 in 3,000 live births. It is inherited in an autosomal dominant manner with high penetrance and variable expression. It is caused by mutations in the neurofibromin-1 (NF1) gene, 50% of which are new mutations. In order to establish the correct diagnosis, it is necessary to establish two or more criteria:\n- six or more cafe-au-lait spots measuring > 5 mm before puberty and > 15 mm after puberty\n- more than one neurofibroma, an elastic nodular formation that develops on any nerve\n- freckles/spots in the armpit area\n- optic nerve glioma, which may cause vision problems\n- one Lisch nodule, iris hamartoma, visible at the slit lamp\n- dysplasia of the sphenoid bone, which may lead to proptosis\n- first-degree relatives with neurofibromatosis type 1.\nSource: \"Pediatria\" Issue 5; 2018; Tom Lissauer; Ch. 29", key: "C", consensusPct: 91, doctorsN: 10609, topic: "", konsyliumStem: "Plamy typu cafe-au-lait są charakterystyczne dla:" },
  243: { text: "The anterior pituitary releases: growth hormone (GH), prolactin (PRL), adrenocorticotropic hormone (ACTH), thyroid-stimulating hormone (TSH), follicle-stimulating hormone (FSH), luteinizing hormone (LH), endorphins.\nMiddle pituitary: melanotropin (MSH), proopiomelanocortin.\nPosterior pituitary: vasopressin (ADH), oxytocin.", key: "C", consensusPct: 84, doctorsN: 11088, topic: "pediatria / Choroby układu wydzielania wewnętrznego", konsyliumStem: "Z tylnego płata przysadki mózgowej uwalniane są:" },
  245: { text: "Schoenlein-Henoch disease is an inflammation of small vessels, characterized by the deposition of immune complexes in their walls, the main component of which is IgA. The disease can occur at any age, but the peak incidence occurs between the ages of 3 and 4 (more common in boys). The first symptoms usually appear a few days after an upper respiratory tract infection.\nThe enlarged spleen mentioned among the distractors is not a symptom of this disease.\nTherefore, the correct answer to the question is E.\nWhat symptoms may appear during the course of the disease?\n- purpura, polymorphic, palpable rash that does not blanch on pressure (petechiae), usually on the lower limbs\n-\njoint inflammation\n(A) (wrist, ankle, knee) with pain, swelling, no warmth\n-\nstomach pain\n(B), bloody stools, hematemesis, intussusception\n-\nhematuria\n(D), nephritic syndrome, nephrotic syndrome, chronic renal failure - their most common symptom is\nproteinuria or the presence of albumin in the morning urine\n(C)\nSource:\nW.Kawalec, Pediatrics, 2018, Volume I, pp. 765-766", key: "E", consensusPct: 63, doctorsN: 13134, topic: "pediatria / Podstawy reumatologii", konsyliumStem: "Do objawów charakterystycznych choroby Schönleina-Henocha nie należy/ą:" },
  251: { text: "The etiological factor in erythema infectiousa, also known as the \"fifth disease\", is parvovirus B19. HHV-6 causes one of the most common diseases of early childhood, i.e. flushing fever - the \"sixth disease\", commonly known as three-day fever. It is a mild, self-limited disease of infants and young children, most often occurring before the age of 2. Typically, it manifests itself as a high fever with a sudden onset, lasting 3-4 days, after which a maculopapular rash appears on the child's body and face. High fever (usually up to 40 degrees C) in this age group is associated with a significant risk of febrile seizures; studies estimated that HHV-6 infection was the cause of 10-45% of febrile seizures in children. In the course of this viral disease, neutropenia may be present in the peripheral blood count.\nSource: Roseola Infantum. Christopher R. Gorman, MD; Chief Editor: William D James, MD; 2018\nhttps://emedicine.medscape.com/article/1133023-overview#a6", key: "A", consensusPct: 62, doctorsN: 13106, topic: "pediatria / Choroby zakaźne", konsyliumStem: "Wskaż fałszywe stwierdzenie dotyczące zakażenia wirusem HHV6:" },
  252: { text: "Kawasaki disease is not associated with thrombocytopenia. Usually, no significant abnormalities are observed in laboratory tests, but anemia, increased platelet count >450,000/mcl and leukocyte count >15,000/mcl may occur.\nThe remaining symptoms are typical symptoms of Kawasaki disease (cutaneous-mucosal-nodal syndrome):\n● fever for more than 5 days,\n● bilateral non-purulent conjunctivitis,\n● changes in the oral cavity: congestion of the mucous membranes, chapped and cracked lips, pharyngitis, raspberry tongue,\n● lesions on the limbs: erythema and swelling of the hands and feet, patchy peeling of the epidermis, erythematous lesions in the perineum area,\n● polymorphic rash, usually maculopapular,\n● neck lymphadenopathy (most often asymmetrical lymph node enlargement), often painful.\nSource: Pediatrics. Vol. 1-2. Wanda Kawalec, Ryszard Grenda, Helena Ziółkowska, Warsaw, Wydawnictwo Lekarskie PZWL, 2013", key: "D", consensusPct: 68, doctorsN: 12611, topic: "pediatria / Podstawy reumatologii", konsyliumStem: "4-letni chłopiec zgłosił się z powodu gorączki trwającej 6 dni. Która z poniższych cech nie budzi podejrzenia zespołu Kawasakiego?" },
  253: { text: "Warning symptoms suggestive of primary immunodeficiency:\n- at least 4 ear infections per year\n- at least 2 sinusitis per year\n- antibiotic therapy lasting 2 months or longer with slight improvement in the clinical condition\n- at least 2 pneumonias per year\n- lack of weight gain and inhibition of normal development\n- repeated deep skin or organ abscesses\n- chronic mycosis of the oral cavity or skin in children after 1 year of age\n- the need for long-term treatment of infections with intravenous antibiotics\n- 2 or more severe soft tissue infections, including sepsis\n- family history indicating the occurrence of primary immunodeficiencies\nSource: \"Pediatria\" W. Kawalec, 2018, 2nd ed.; Volume II; Ch. 20.2.2", key: "E", consensusPct: 76, doctorsN: 11400, topic: "", konsyliumStem: "Zaniepokojona matka zgłasza objawy, które według niej i strony internetowej dla rodziców wymagają diagnostyki immunologicznej. Prosi lekarza o wyjaśnienie, który z poniższych objaw" },
  258: { text: "Doxorubicin (like other anthracyclines) may cause heart damage and heart failure. Doxorubicin causes heart failure with a dose-dependent incidence of 3-48%.\nSource: ESC position on the toxic impact of cancer treatment on the cardiovascular system in 2016.", key: "C", consensusPct: 80, doctorsN: 11490, topic: "", konsyliumStem: "Do cytostatyków o szczególnie wysokim potencjale kardiotoksycznym, mogącym prowadzić do zastoinowej niewydolności krążenia, należy:" },
  261: { text: "Scintigraphy with 123I-MIBG is intended to detect and localize neuroendocrine tumors such as: pheochromocytoma, neuroblastoma (ganglioma), ganglioneuroblastoma, ganglioneuroma, paraganglioma, carcinoid tumor, and medullary thyroid carcinoma.\nTherefore, the correct answer to the question is B.\nHow do we diagnose other diseases?\nA) To detect hepatoblastoma, ultrasound and CT are most often used.\nC) To diagnose medulloblastoma of the central nervous system (medulloblastoma), an MRI should be performed.\nD) Diagnosis of Hodgkin's lymphoma includes a biopsy of nodes, bone marrow and an X-ray examination.\nE) To detect bone sarcoma (osteosarcoma), a radiological examination is performed.\nSource:\nLissauer, Pediatrics, 2019, p. 454\nhttps://www.czd.pl/upload/pages/181/attachments/informacja-o-badaniu-scyntygrafyczny-z-zastosowanie-123-i-mibg.pdf", key: "B", consensusPct: 66, doctorsN: 12871, topic: "pediatria / Nowotwory u dzieci", konsyliumStem: "Scyntygrafia ze znakowaną ¹²³I metajodobenzyloguanidyną (MIBG) jest stosowana u dzieci w diagnostyce:" },
  262: { text: "Vildagliptin is an antidiabetic drug acting on the incretin system, the so-called gliptin. These are strong selective DPP-4 inhibitors, inhibiting the inactivation of endogenous incretins (GLP-1 and GIP), increasing their concentrations in the blood, increasing the sensitivity of B cells to glucose and glucose-dependent insulin secretion, when used p.o.\nSubstances may have a diabetogenic effect through various mechanisms, e.g. by acting antagonistically towards insulin (inhibiting its secretion or increasing insulin resistance), direct destruction of pancreatic islet cells or stimulating the production of anti-islet antibodies. Drugs with established diabetogenic effects include: glucocorticosteroids, nicotinic acid, thyroid hormones, β-blockers, thiazides, pentamidine, phenytoin, interferon α and atypical psychotropic drugs.\nSource: \"Interna Szczeklik\" Small textbook, Andrzej Szczeklik, 2019/20, Ch. 13;\nPractical Medicine - \"Problems in the treatment of diabetes - part 3. Coexistence of type 2 diabetes and drug-induced diabetes - how not to lose consciousness with blood glucose >1400 mg/dl and in a hyperosmolar state\"; Elektra Szymańska-Garbacz, MD, PhD, Ph.D. n. med. Leszek Czupryniak prof. Medical University of Lodz, Department of Internal Diseases and Diabetology, Medical University of Lodz", key: "E", consensusPct: 81, doctorsN: 11154, topic: "", konsyliumStem: "Cukrzyca wtórna polekowa może wystąpić po wszystkich wymienionych poniżej lekach, z wyjątkiem:" },
  264: { text: "The history raises the suspicion of IgE-related allergy (rapid appearance of skin and respiratory symptoms after exposure). In this case, the \"gold diagnostic standard\" is an elimination test (exclusion of suspected allergens from the diet), followed by a challenge test with previously excluded foods, conducted in a double-blind method using a placebo. In the case of IgE-dependent allergic hypersensitivity, the provocation should be performed in a hospital setting. In everyday practice, he often performs an open trial, but this does not change the fact that a double-blind trial (both the doctor and the parent do not know whether the child received food containing the tested allergen), placebo-controlled, is the most perfect diagnostic test in this case. Additionally, diagnostics include skin prick tests with commercial and native allergens, determination of specific IgE allergens and total IgE concentration.\nEpidermal patch tests are mainly used in the diagnosis of eczema, in particular allergic contact dermatitis.\nSource:\nhttps://www.mp.pl/interna/chapter/B16.II.4.26\n.", key: "C", consensusPct: 83, doctorsN: 11173, topic: "pediatria / Choroby alergiczne", konsyliumStem: "U 6-letniego chłopca, dwukrotnie wystąpiła swędząca, rumieniowo-grudkowa wysypka i upośledzona drożność nosa po spożyciu naturalnego jogurtu. Objawy utrzymywały się do kilku godzin" },
  265: { text: "The only symptom mentioned above that does not belong to meningeal symptoms is Lasègue's sign - (3).\nThis symptom is characteristic of sciatica and is used to differentiate it from other diseases.\nTherefore, the correct answer to the problem is C (1,2,4,5).\nPlease remember what the other symptoms mentioned in the question indicate:\n1) Flatau's sign (nuchal mydriatic) - dilated pupils when passively bending the head to the chest\n2) Brudziński's sign pubic (lower) - pressure on the pubic symphysis causes flexion of the legs at the knee joints and abduction of the hip joints\n4) Amos sign (three-legged) - when sitting, the child leans on straight, widely spaced arms behind him, bends his legs at the knees and supports himself with his heels\n5) - Upper Kernig's sign - passive tilting of the trunk forward triggers reflex flexion of the lower limbs in the knee and hip joints\n- Lower Kernig's sign - inability to extend the lower leg of a lower limb previously bent at a right angle at the knee and hip joint\nThe presence of positive meningeal symptoms indicates an ongoing disease process in the CNS (meningitis and/or encephalitis, subarachnoid hemorrhage, trauma, cancer, degenerative processes). In infancy, meningeal symptoms are more difficult to assess and less diagnostically significant than in older children.\nSource:\nW.Kawalec, Pediatrics, 2018, Volume I, pp. 133-134", key: "C", consensusPct: 73, doctorsN: 12017, topic: "pediatria / Badanie kliniczne dziecka", konsyliumStem: "Do objawów oponowych występujących u dzieci należą: 1) objaw Flataua; 2) objaw Brudzińskiego łonowy; 3) objaw Lasègue’a; 4) objaw Amossa; 5) objaw Kerniga. Prawidłowa odpowiedź to:" },
  267: { text: "The risk of complications caused by measles virus infection is particularly increased in infants and young children, as well as in adults with cellular immune deficiencies and in malnourished people. The most serious complications include subacute sclerosing panencephalitis (SSPE) - a progressive neurodegenerative disorder that usually develops several or a dozen years after the onset of measles (median 7 years). It is rare (1–4/100,000, but 1/8000 in cases of measles <2 years of age), but extremely dangerous, often leading to death.\nSource:\nhttps://www.mp.pl/interna/chapter/B16.II.18.1.3\n.", key: "A", consensusPct: 76, doctorsN: 11827, topic: "pediatria / Choroby zakaźne", konsyliumStem: "Podostre stwardniające zapalenie mózgu (leukoencephalitis subacuta scleroticans) jest związane z wczesnym (do 2. r.ż.) przechorowaniem:" },
  269: { text: "The picture of hemolytic uremic syndrome (HUS) consists of a triad: acute renal failure, microangiopathic hemolytic anemia and thrombocytopenia. Most often, hemolytic uremic syndrome is preceded by a gastrointestinal infection caused by E. coli serotype 0157:H7, producing verotoxin, and less often Shigella. If appropriate treatment, including dialysis, is initiated early enough, the prognosis - especially in cases preceded by diarrhea - is favorable. However, further observation of patients is necessary due to the possibility of persistent proteinuria and the risk of developing hypertension or end-stage renal disease, even many years after the syndrome has subsided.\nSource: \"Pediatria\" Issue 5; 2018; Tom Lissauer; Ch. 19", key: "C", consensusPct: 77, doctorsN: 11279, topic: "", konsyliumStem: "Jaka jest najczęstsza przyczyna zespołu hemolityczno-mocznicowego u dzieci?" },
  270: { text: "Von Willebrand's disease is a congenital bleeding disorder. Its essence is the deficiency or improper function of von Willebrand factor. The consequence is an increased tendency to skin and mucosal bleeding, hemorrhages into joints and muscles, the gastrointestinal tract, as well as hemorrhages after tooth extraction and surgery. The most common form is a slight quantitative deficiency of von Willebrand factor (65-75% of cases).\nThe treatment uses desmopressin, which releases vWF and factor VIII from tissue reserves. This treatment is ineffective in type 3, in which there is a complete absence of vWF.\nAnother method is to provide von Willebrand factor in the form of factor VII concentrate containing von Willebrand factor (applies to patients in whom desmopressin is contraindicated or ineffective).\nYou can also use recombinant vWF (not available in Europe), tranexamic acid and platelet concentrate (platelets contain vWF).\nsource: Interna Szczeklik 2020, Piotr Gajewski, Andrzej Szczeklik, Wydawnictwo Medycyna Practical, Kraków 2020.", key: "B", consensusPct: 84, doctorsN: 6728, topic: "pediatria / Choroby układu krwiotwórczego", konsyliumStem: "W leczeniu choroby von Willebranda stosuje się: 1) koncentrat czynnika VIII z czynnikiem von Willebranda; 2) koncentrat czynnika IX; 3) immunoglobuliny dożylne; 4) deksametazon; 5)" },
  271: { text: "The patient's symptoms include:\n– fever lasting for 7 days (over 5 days)\n– cervical lymphadenopathy\n– maculopapular rash around the perineum and on the trunk\n– lip congestion and raspberry tongue\n– conjunctivitis\n...they raise suspicion\nKawasaki disease\n.\nThis diagnosis is also confirmed by the results of laboratory tests:\n– increased inflammatory parameters (CRP)\n– thrombocytosis\n– anemia\n– increased liver enzymes (ALT = 100 U/l, AST = 85 U/l)\nTherefore, the correct answer to the question is B.\nWhat about the other answers?\nA) Schönlein-Henoch disease has a different course than in the case described - the most common symptoms include arthritis, abdominal pain and nephritis (which are not present in the clinical picture of the patient in question).\nC) The clinical picture of the described case differs significantly from the typical course of rheumatic fever (no carditis, inflammation of large joints, symptoms of streptococcal pharyngitis).\nD) Scarlet fever is not a probable diagnosis in the described case, despite the fact that it is particularly characteristic of this disease\nraspberry tongue\n. In the course of scarlet fever, the clinical picture differs significantly from that presented in the question - including: there is a characteristic Filatov triangle and Pastia lines. Conjunctivitis does not occur in this disease.\nSource:\nW.Kawalec, Pediatrics, 2018, Volume II, pp. 1069-1071", key: "B", consensusPct: 72, doctorsN: 12048, topic: "pediatria / Podstawy reumatologii", konsyliumStem: "2-letni chłopiec został przyjęty do szpitala z powodu utrzymującej się od 7 dni gorączki oraz limfadenopatii szyjnej. Po 5 dniach trwania gorączki pojawiła się wysypka plamisto-gru" },
  272: { text: "If bleeding occurs in a person with von Willebrand's disease, desmopressin or concentrate should be administered as soon as possible. VIII containing vWF. Desmopressin is effective mainly in type 1 and some cases of type 2 disease. There are three possible routes of administration: i.v. (0.3 µg/kg infusion over 30 min) or s.c. every 12–24 h or intranasally (300 μg).\nSource:\nhttps://www.mp.pl/interna/chapter/B16.II.15.20.1\n.", key: "A", consensusPct: 78, doctorsN: 11443, topic: "pediatria / Choroby układu krwiotwórczego", konsyliumStem: "W zapobieganiu/leczeniu krwawień w chorobie von Willebranda stosuje się:" },
  273: { text: "The most common cause of nephrotic syndrome in children is idiopathic idiopathic nephrotic syndrome. Histopathological\nthe most common form is minimal changes\n(approx. 80%), where the image of the glomeruli in the light microscope is normal and no deposits are found in the immunofluorescence test.\nTherefore, the correct answer to the question is A.\nIn addition, idipoatic nephrotic syndrome in children may also occur in the form of:\n– Nephrotic syndrome caused by mesangial-proliferative glomerulonephritis\n– Focal segmental sclerosis (hyalinization) of the glomeruli\nSource:\nW.Kawalec, Pediatrics, 2018, Volume I, p. 747\nJ.Pietrzyk, Pediatrics, Volume II, 2018, p. 55", key: "A", consensusPct: 68, doctorsN: 12745, topic: "pediatria / Choroby układu moczowego", konsyliumStem: "Najczęstszą przyczyną idiopatycznego zespołu nerczycowego u dzieci jest:" },
  276: { text: "The patient presented in the question presents symptoms typical of\nrash caused by HHV-6 viruses, also called three-day sickness.\n\"Children aged between 6 months and 4 years are affected. The rash is pale pink, medium-spotted. It appears after the fever lasts 3-4 days. It occurs mainly on the trunk and face, with less intensity on the limbs. It lasts for about 2 days.\"\nTherefore, the correct answer to the question is B.\nSource:\nW.Kawalec, Pediatrics, 2018, Volume II, p. 1081", key: "B", consensusPct: 75, doctorsN: 7271, topic: "pediatria / Choroby zakaźne", konsyliumStem: "7-miesięczny chłopiec od 2 dni gorączkuje do 39° C. Dziecko jest w dobrym stanie ogólnym. W badaniu fizykalnym stwierdza się zaczerwienione gardło, poza tym bez odchyleń od normy. " },
  277: { text: "In the case of bacterial CSF examination, the following are observed in the general CSF examination:\n- yellowish, cloudy fluid,\n- number of cells: from a few cells up to the number covering the entire field of view,\n- protein concentration >2g/l,\n- very low glucose and reduced chloride levels,\n- increased lactic acid concentration.", key: "B", consensusPct: 82, doctorsN: 7920, topic: "", konsyliumStem: "Pleocytoza 600 komórek/µl ze znaczną przewagą neutrofili, znacznie podwyższone stężenie białka (1,5 g/l), wysokie stężenie kwasu mlekowego oraz obniżone stężenie glukozy (obniżony " },
  280: { text: "In accordance with the Recommendations for management of community-acquired respiratory infections 2016, edited by prof. Ph.D. n. med. Walerii Hryniewicz, prophylactic administration of oseltamivir is recommended for people who have not been vaccinated against influenza:\n• those who are particularly susceptible to severe flu and are in household contact with a person suffering from flu\n• particularly susceptible to infection and staying in closed centers where epidemic diseases have occurred (e.g. hospitals, nursing homes)\n• particularly susceptible to severe flu, during the period of increased number of illnesses\n• during the period of increased number of influenza cases.\nOseltamivir is used prophylactically for 10 days.\nOstelamivir is not approved for prophylactic use in children <1 year of age.", key: "D", consensusPct: 68, doctorsN: 8785, topic: "", konsyliumStem: "U mamy 4-latka (dziecka ze źle kontrolowaną astmą oskrzelową) rozpoznano grypę (objawy u mamy występują od wczoraj). Dziecko ma kontakt domowy z mamą. Wskaż właściwe postępowanie d" },
  281: { text: "Symptoms of urinary tract urolithiasis include: pain in the abdomen or the L-S area with the nature of renal colic (radiating to the pubic symphysis, external genital organs and inner surface of the thighs). A general urine test reveals the presence of blood cells and/or leukocytes. An additional symptom supporting the diagnosis of urolithiasis as the cause of the symptoms in the described child is the image of unilateral hydronephrosis on abdominal ultrasound.\nBased on: Pediatrics – Manual for the State Medical Examination and specialization examination. Anna Dobrzańska, Józef Ryżko and Interna Szczeklik\nhttps://www.mp.pl/interna/chapter/B16.II.14.6\n.", key: "A", consensusPct: 80, doctorsN: 8001, topic: "", konsyliumStem: "Rodzice zgłosili się wieczorem na SOR z 12-letnim synem, u którego od rana występowały nudności, wymioty, ból podczas mikcji promieniujący do lewej pachwiny i ból lewej okolicy lęd" },
  283: { text: "The mainstay of treatment for asthma exacerbation in children is the use of bronchodilators. According to ICON recommendations, short-acting b-2 mimetics should be administered first.\nSource: Pediatrics – Manual for the State Medical Examination and specialization examination. Anna Dobrzańska, Józef Ryżko.", key: "B", consensusPct: 68, doctorsN: 8710, topic: "", konsyliumStem: "Wstępne leczenie w warunkach ambulatoryjnych ciężkiego zaostrzenia astmy u dzieci < 5. roku życia obejmuje:" },
  284: { text: "Allergic contact eczema is a classic presentation of a delayed T cell-mediated hypersensitivity reaction to external factors. It is associated with type IV immune reaction (which develops only 24-48 hours after contact with the allergen). It consists of the induction phase (immediately after contact with the allergen) and the disclosure phase (in which the reaction occurs). A typical eruption is an erythematous exudative papule and a vesicle. A characteristic symptom is itching. The inflamed area of ​​skin usually comes into contact with the allergen, which makes diagnosis easier. In the treatment of contact eczema, it is crucial to avoid contact with the harmful substance. In the presence of severe inflammatory changes, it is necessary to apply anti-inflammatory and antimicrobial treatment, including: topical glucocorticoids and topical calcineurin inhibitors.\nSources: Pediatrics – Manual for the State Medical Examination and specialization examination. Anna Dobrzańska, Józef Ryżko and\nhttps://www.mp.pl/pediatria/artykuly-wytyczne/artykuly-przegladowe/184455,kontaktowe-zapaleni-skory-u-dzieci,1", key: "C", consensusPct: 71, doctorsN: 8411, topic: "", konsyliumStem: "Wskaż fałszywe stwierdzenie dotyczące alergicznego kontaktowego zapalenia skóry:" },
  285: { text: "In the population of young children under 5 years of age, the following occur much more often than in older children and teenagers:\n– acute lymphoblastic leukemia\n– neuroblastoma\n– Wilms tumor\n– retinoblastoma\n– non-Hodgkin's lymphoma\nTherefore, the correct answer to the question is C.\nIt is worth remembering that bone and soft tissue tumors are much more common in older children.\nSource:\nPediatrics - Tom Lissauer, Will Carroll, 2019, p. 459", key: "C", consensusPct: 82, doctorsN: 4734, topic: "", konsyliumStem: "W przeciwieństwie do dzieci starszych i nastolatków, u dzieci do 5. roku życia najczęściej występują:" },
  287: { text: "Occurring in the child described in the question:\n– symptom of \"currant/raspberry jelly\" - blood-stained stool,\n– bloated stomach,\n– a palpable mass in the abdominal cavity,\n– no increased inflammatory parameters,\n– baby's anxiety and crying,\nindicate with high probability\nintussusception.\nTherefore, the correct answer to the question is E.\nLet's analyze the remaining answer options in the question:\nA) and B) Acute appendicitis and salmonellosis would most likely be associated with increased inflammatory parameters and body temperature.\nC) In the case of Meckel's deviation, bleeding from the digestive system may also occur, but in infants, ischemic causes predominate in severe conditions such as intussusception or intestinal volvulus. Moreover, the symptom of currant jelly is more characteristic of intussusception.\nD) Infantile colic would not cause such severe symptoms as the baby experienced.\nSource:\nA. Dobrzańska, Obrycki, Socha, Pediatrics in the practice of a primary care physician, 2022, p. 323", key: "E", consensusPct: 89, doctorsN: 6665, topic: "pediatria / Podstawy chirurgii, urologii, neurochirurgii i ortopedii dziecięcej", konsyliumStem: "Dziecko w wieku 6-miesięcy przyjęto do Izby Przyjęć z powodu trwającego od 3 godzin nieukojonego płaczu i niepokoju. Rodzice dziecka obserwowali podkurczanie nóżek, oraz bladość po" },
  289: { text: "The Vaccination Program includes the following vaccinations recommended for medical professionals:\n• flu vaccination,\n• vaccination against menigococci,\n• against hepatitis A - especially the staff of pediatric and gastroenterological departments,\n• against whooping cough - especially for staff in contact with newborns and infants.\nVaccination against hepatitis B is a mandatory vaccination.", key: "E", consensusPct: 67, doctorsN: 7968, topic: "pediatria / Szczepienia ochronne", konsyliumStem: "Które szczepienia Programu Szczepień Ochronnych są ujęte w wykazie szczepień zalecanych dla osób wykonujących zawód medyczny w oddziale pediatrycznym? 1) przeciwko WZW typu A (HAV)" },
  290: { text: "According to the SES position from 2019, post-exposure prophylaxis in the case of influenza should be implemented in adults and children aged ≥3 months who have risk factors for severe and/or complicated course of influenza and who have not been previously vaccinated. The drug should be administered as soon as possible, but prophylaxis should not be implemented if more than 48 hours have passed since exposure. The duration of prophylaxis is: from the beginning of exposure to 7 days from the last exposure.\nSource: Ozorowski T., Mączyńska A., Dubiel G., Rymer W.: Prevention, diagnosis and treatment of influenza virus infections in hospitals according to the position of the Association of Hospital Epidemiology 2019. Med. Practical, 2019; 2: 51–66", key: "E", consensusPct: 62, doctorsN: 8022, topic: "pediatria / Choroby zakaźne", konsyliumStem: "U matki 5-miesięcznego dziecka od 3 dni występuje gorączka i kaszel, a w dniu badania rozpoznano grypę typu B (potwierdzona szybkim testem). Matka karmi dziecko piersią, w ciąży by" },
  294: { text: "Let's analyze the individual answer options in the question:\nA) True – CD19 is a characteristic antigen for B lymphoblasts.\nB) True - CD3+ is a T-cell antigen, so B lymphoblasts must be negative for its presence.\nC) Yes. Myeloperoxidase (MPO) is characteristic of acute myeloid leukemias.\nD) True - according to WHO and NCCN, ≥20% blasts is the cut-off value for diagnosing this disease.\nE) False - diagnosis is possible when the number of lymphoblasts is >20%.\nTherefore, the correct answer to the question is E.\nSource:\nW.Kawalec, Pediatrics, 2018, Volume I, pp. 641-643\nInterna Szczeklika, 2021, p. 1810", key: "E", consensusPct: 79, doctorsN: 147, topic: "pediatria / Nowotwory u dzieci", konsyliumStem: "Określenie cech cytogenetycznych i molekularnych nie jest wymagane do rozpoznania, ale należy do podstawowych kryteriów klasyfikacji ostrej białaczki limfoblastycznej (ALL). Wskaż " },
  296: { text: "Let's analyze the individual answer options in the question:\nA) Yes. A biopsy removing an enlarged lymph node may be the basis for the diagnosis of Hodgkin's disease.\nB) Absolutely - determining the presence of Reed-Sternberg cells is the basis for diagnosing this disease.\nC) False. \"Fine needle aspiration biopsy is contraindicated because it does not allow for a precise diagnosis.\"\nD) True - performing a bone marrow biopsy in patients with an advanced stage of the disease allows its diagnosis.\nE) Imaging tests, including PET, are useful in the diagnosis and control of cancer - establishing the diagnosis only on their basis is unheard of. This distractor is ambiguous, but due to a certain error in answer C - we consider it false.\nTherefore, the most correct answer to the problem is C.\nSource:\nW.Kawalec, Pediatrics, 2018, Volume I, pp. 656-657, 663", key: "C", consensusPct: 78, doctorsN: 5394, topic: "pediatria / Nowotwory u dzieci", konsyliumStem: "Podstawą do ustalenia rozpoznania ziarnicy złośliwej są wszystkie wymienione, z wyjątkiem:" },
  297: { text: "\"\nIn 80-90% of viral meningitis of established etiology, enteroviruses are the causative factor.\nArboviruses, adenoviruses, HSV, CMV, VZV and influenza, measles and rubella viruses are also responsible for the disease.\nTherefore, the correct answer to the question is A.\nSource:\nW.Kawalec, Pediatrics, 2018, Volume II, p. 1089", key: "A", consensusPct: 78, doctorsN: 7150, topic: "pediatria / Choroby zakaźne", konsyliumStem: "Najczęstsza przyczyna wirusowego zapalenia opon mózgowo-rdzeniowych u dzieci to:" },
  299: { text: "A) This statement is false. Children who received the first dose of the vaccine and did not receive the booster dose at the age of 6 should be vaccinated as soon as possible (no later than 19 years of age).\nB) True.\nC) According to the CEM key, this statement is true, but there is some doubt here - children who were vaccinated with the first dose of the MMR vaccine between 9-12 months of age. another dose of vaccine should be given after the age of 12 months, and then a booster dose at the age of 6 years. This makes a total of 3 doses of vaccine.\nD) True.\nE) True.\nSource:\nProtective Vaccination Program 2022, p. 32", key: "A", consensusPct: 75, doctorsN: 6319, topic: "", konsyliumStem: "Wskaż fałszywe stwierdzenie dotyczące szczepienia przeciw odrze, śwince i różyczce:" },
  301: { text: "1) True - simple febrile seizures, unlike complex ones, are generalized, not focal.\n2) Yes - standard simple febrile seizures last up to 15 minutes.\n3) Not true - this usually concerns complex febrile seizures.\n4) No. Todd's palsy, i.e. post-ictal hemiplegia, may occur in the case of complex seizures.\n5) Absolutely - simple DGs occur more often (65-75%) than complex DGs (25-35%).\nThe true statements are 1, 2 and 5, therefore the correct answer is A.\nSource:\nDobrzańska, Obrycki, Socha, Pediatrics in the practice of primary care physicians, 2022", key: "A", consensusPct: 82, doctorsN: 6082, topic: "", konsyliumStem: "Wskaż prawdziwe stwierdzenia dotyczące drgawek gorączkowych prostych: 1) są uogólnione, zwykle toniczno-kloniczne; 2) czas trwania wynosi poniżej 15 minut, zwykle 5 minut; 3) nawra" },
  303: { text: "A) No - according to the standards of the Polish Society of Epidemiologists and Infectious Disease Physicians for the treatment of Lyme borreliosis (2018), the administration of antibiotics is not recommended in routine treatment. Prophylactic antibiotic administration may be considered in individual cases of increased risk of infection (e.g. in endemic areas in the case of multiple bites).\nB) No. We treat the patient, not the tick! Examining the tick and even confirming the presence of Borrelia burgdorferi pathogens does not mean that the patient has been infected.\nC) No. After a tick bite, testing for tick-borne diseases is recommended if disturbing symptoms occur (e.g. erythema migrans).\nD) Similarly to B, we treat the patient, not the tick.\nE) Absolutely - this is the right thing to do. The tick should be removed and then the bite site should be disinfected (in this order).\nSource:\nPractical medicine 2022,\nhttps://www.mp.pl/interna/chapter/B16.II.18.5.1\n.", key: "E", consensusPct: 92, doctorsN: 5701, topic: "", konsyliumStem: "Wskaż prawidłowe postępowanie po ugryzieniu przez kleszcza:" },
  304: { text: "The principles of preventive vitamin D supplementation are shown in the attached table -\nanswer E is inconsistent with the guidelines.\nSource:\nRusińska A., Płudowski P., Walczak M., et al.: Principles of vitamin D supplementation and treatment - amendment 2018. Medical Standards, 2018; 15: 531–559", key: "E", consensusPct: 71, doctorsN: 6497, topic: "", konsyliumStem: "Wskaż profilaktyczne dawki witaminy D u dzieci, które są nieprawidłowe dla wskazanego przedziału wiekowego:" },
  307: { text: "Let's analyze the individual answer options in the question:\n1) True, Duhring's disease is a variant of latent celiac disease. **\n**2) True - the lack of a proper diet increases the risk of malnutrition, delayed growth and maturation, anemia, osteoporosis, infertility, emotional disorders, as well as cancer, most often lymphoma.\n3) No - the diagnosis of celiac disease is based on the interpretation of blood tests and taking biopsies of the small intestine (while the patient is on a normal diet). For diagnosis, it is not enough to confirm the presence of HLA DQ2 and HLA DQ8 (they are not present in all patients).\n4) Yes - somatic development may be slowed down or inhibited.\n5) Yes - due to the atrophy of intestinal villi in the course of this disease, disturbances in the production and secretion of enzymes within the intestinal epithelium may occur.\nTherefore, the correct answer to the problem is B (1, 2, 4, 5).\nSource:\nW.Kawalec, Pediatrics, 2018, Volume I, pp. 521-522", key: "B", consensusPct: 71, doctorsN: 4612, topic: "", konsyliumStem: "Wskaż prawdziwe stwierdzenia dotyczące celiakii: 1) jej odmianą jest choroba Dühringa; 2) brak przestrzegania diety bezglutenowej zwiększa u chorych z celiakią ryzyko rozwoju chłon" },
  309: { text: "Meningitis in newborns is most often caused by:\nEscherichia coli, Streptococcus agalactiae, Listeria monocytogenes, Klebsiella sp.\nand other Gram-negative enteric bacilli.\nTherefore, the correct answer to the question is D.\nSource:\nhttps://antybiotyki.edu.pl/wp-content/uploads/Reprezentacje/reprezentacje-ukl-nerwowy_2011.pdf\np. 20", key: "D", consensusPct: 66, doctorsN: 4824, topic: "", konsyliumStem: "Najczęstszymi patogenami wywołującymi zapalenie opon mózgowo-rdzeniowych u noworodków są:" },
  310: { text: "\"The recommended fluid dose is 10-20 ml/kg body weight for 20-30 minutes.\"\nIn the case of a child weighing 15 kg, the value will be in the range of 150-300 ml in 20-30 minutes (slightly less in 10 minutes).\nAnswer D is the closest to the correct values.\nSource:\nW.Kawalec, Pediatrics, 2018, Volume I, p.216", key: "D", consensusPct: 81, doctorsN: 4391, topic: "", konsyliumStem: "W przypadku posocznicy u dziecka ważącego 15 kg, z uwagi na konieczność wypełnienia łożyska naczyniowego, w pierwszych 10 minutach działań należy podać krystaloidy w objętości okoł" },
  312: { text: "All of the following medications can be used to treat small common warts located on the extremities, except:\n1% mupirocin ointment\n. This ointment contains an antibiotic used topically on the skin to treat bacterial - not viral - infections.\nTherefore, the correct answer to the question is C.\nSource:\nPediatrics in the practice of a primary care physician, Anna Dobrzańska, 2022\nhttps://www.mp.pl/pacjent/leki/lek/56508,Mupirox-masc", key: "C", consensusPct: 75, doctorsN: 3233, topic: "", konsyliumStem: "Zakażenie wirusem brodawczaka ludzkiego należy do jednego z najczęstszych zakażeń wirusowych. Do leczenia małych brodawek zwykłych, zlokalizowanych w obrębie kończyn można zastosow" },
  313: { text: "Let's analyze the individual answer options in the question:\nA) False - the disease is most often diagnosed in the first month of the child's life.\nB) No - severe jaundice is not a typical symptom of pylorostenosis.\nC) False - vomiting is never tinged with bile (due to pyloric hypertrophy, bile does not pass from the duodenum to the stomach).\nD) Starvation stools and chronic malnutrition may also occur in the course of pylorostenosis, typically long after diagnosis - but this is not a very typical symptom. In this case, the \"more correct\" answer would be E.\nE) That's right - the treatment of choice is surgery - pyloromyotomy.\nTherefore, the correct answer to the question is E.\nIt's also worth knowing that\nBoys are four times more likely to suffer from pylorostenosis\nSource:\nPediatrics - Tom Lissauer, Will Carroll; Polish edition 2019\nhttps://www.mp.pl/pacjent/pediatria/choroby/ukladpokarmowy/51098,wrod-przerost-odzwiernika-zoladka", key: "E", consensusPct: 75, doctorsN: 3275, topic: "", konsyliumStem: "Wskaż prawdziwe stwierdzenie dotyczące hipertrofii odźwiernika (pylorostenozy):" },
  314: { text: "Glycogenosis associated with an enzymatic defect of lysosomal-alpha-glucosidase, occurring in two forms - childhood and adolescent - is\nPompe disease (type II).\nTherefore, the correct answer to the question is A.\nIt is a rare neuromuscular disease with a genetic basis (inherited in an autosomal recessive manner).\nIt's also worth knowing that\nWe distinguish many types of glycogenosis:\nType 0 glycogenosis\nGlycogenosis type 1 - von Gierke's disease\nGlycogenosis type 2 - Pompe disease\nGlycogenosis type 3 - Cori's disease\nGlycogenosis type 4 - Andersen's disease\nGlycogenosis type 5 - McArdle's disease\nGlycogenosis type 6 - Hers' disease\nGlycogenosis type 7 - Tarui's disease\nGlycogenosis type 8 -\nGlycogenosis type 9 -\nGlycogenosis type 10 -\nGlycogenosis type 11 - Fanconi-Bickel syndrome\nSource:\nPediatrics - Tom Lissauer, Will Carroll; Polish edition 2019\nhttps://podyplomie.pl/medycyna/38197,pozna-postac-choroby-pompego-diagnostyka-i-mozliwosci-leczenia", key: "A", consensusPct: 82, doctorsN: 3147, topic: "", konsyliumStem: "Glikogenozy należą do rzadkich chorób metabolicznych, w których dochodzi do magazynowania glikogenu w różnych narządach. Glikogenoza związana z defektem enzymatycznym lizosomalnej-" },
  317: { text: "**Pellagra has been associated with niacin/nicotinamide deficiency\n.\n**The correct answer to the question is A.\nWhat about the other answer options?\nB) Beriberi disease is associated with thiamine deficiency.\nC) Scurvy (rot) is a disease associated with vitamin C deficiency.\nD) Night blindness is a disease resulting from vitamin A deficiency.\nE) Osteoporosis is associated with calcium or vitamin D deficiency.\nSource:\nPediatrics - Tom Lissauer, Will Carroll; Polish edition 2019\nhttps://www.mp.pl/pacjent/dieta/zasady/63281,niacyna-witamina-pp", key: "A", consensusPct: 77, doctorsN: 3243, topic: "", konsyliumStem: "Jaką chorobę wiąże się z niedoborem niacyny/nikotynamidu?" },
  318: { text: "Let's analyze the individual answer options in the question:\nA) A characteristic symptom is erythema migrans, usually occurring within the first month after the sting.\nB) True.\nC) Doxycycline should not be used in children under 9 years of age due to its potential side effects (teeth discoloration).\nD) Most often, the clinical picture of the patient - the presence of erythema migrans - is sufficient to diagnose Lyme disease. If further diagnostics are implemented, the first test should be serological tests (detecting the presence of antibodies).\nE) It is not a contraindication, on the contrary - an important diagnostic procedure when neuroboleriasis is suspected.\nTherefore, the correct answer to the question is B.\nSource:\nPediatrics - Tom Lissauer, Will Carroll; Polish edition 2019\nhttps://boreliozaonline.pl/rozpoznanie-neuroboreliozy/", key: "B", consensusPct: 68, doctorsN: 3365, topic: "", konsyliumStem: "Wskaż prawdziwe stwierdzenie dotyczące boreliozy:" },
  320: { text: "Only of the disease entities listed in the distractors\nLichen planus is not caused by bacteria from the Streptococcus group.\nIt is a chronic inflammatory disease of the skin and mucous membranes of unknown etiology (often occurring in autoimmune diseases).\nTherefore, the correct answer to the question is C.\nSource:\nPediatrics - Tom Lissauer, Will Carroll; Polish edition 2019\nhttps://www.mp.pl/pacjent/dermatologia/choroby/chorobyskory/74045,liszaj-plaski", key: "C", consensusPct: 75, doctorsN: 3275, topic: "", konsyliumStem: "Która jednostka chorobowa nie jest wywołana przez bakterie z grupy Streptococcus?" },
  321: { text: "Cyanotic heart defects include:\n-\n(1) tetralogy of Fallot\n-\n(2) right-sided transposition of the great vessels\n-\n(3) Eisenmenger syndrome\n- this answer is controversial due to the fact that this syndrome is not a congenital cyanotic defect, but a complication of simple and complex leak defects. However, it is cyanotic, so the answer was probably considered correct.\n- single-chamber heart\n- pulmonary valve atresia\n- tricuspid valve atresia\nHowever, ventricular septal defect (4) and aortic stenosis (5) are not cyanotic defects.\nTherefore, the correct answer to the problem is C (1, 2, 3).\nSource:\nPediatrics - Tom Lissauer, Will Carroll; Polish edition 2019\nPediatrics - W. Kawalec, R. Grenda, H. Ziółkowska, 2nd edition 2018", key: "C", consensusPct: 58, doctorsN: 3806, topic: "", konsyliumStem: "Do wrodzonych wad serca przebiegających z sinicą należą: 1) tetralogia Fallota; 2) prawostronne przełożenie wielkich naczyń; 3) zespół Eisenmengera; 4) ubytek przegrody międzykomor" },
  322: { text: "The most common autosomal recessive genetic disease is **cystic fibrosis.**\n\"The frequency of occurrence is estimated at 1:2500-1:5000 births. The frequency of carriers of mutations in one allele I: 25 (i.e. 4-5% of the population).\nTherefore, the correct answer to the question is A.\nSource:\nPediatrics - W. Kawalec, R. Grenda, H. Ziółkowska, 2nd edition 2018 - Volume 1, p. 594\nPediatrics - Tom Lissauer, Will Carroll; Polish edition 2019", key: "A", consensusPct: 83, doctorsN: 3180, topic: "", konsyliumStem: "Najczęstszą dziedziczącą się autosomalnie recesywnie chorobą genetyczną jest:" },
  323: { text: "Iron deficiency anemia is characterized by:\n1) LOWER MCV (mean corpuscular volume)\n2) LOWER MCH (mean corpuscular hemoglobin - the average mass of hemoglobin in a blood cell)\n3) LOWER ferritin\n4) increased transferrin\n5) INCREASED TIBC (total iron binding capacity)\nTherefore, the correct answer to the question is D (only 4).\nSource:\nPediatrics - Tom Lissauer, Will Carroll; Polish edition 2019\nhttps://www.mp.pl/pacjent/pediatria/choroby/choroby- blood/152182,niedokrestosc-z-niedoboru-zelaza", key: "D", consensusPct: 73, doctorsN: 3332, topic: "", konsyliumStem: "Anemia z niedoboru żelaza charakteryzuje się: 1) podwyższonym MCV; 2) podwyższonym MCH; 3) podwyższoną ferrytyną; 4) podwyższoną transferyną; 5) obniżonym TIBC. Prawidłowa odpowied" },
  324: { text: "Let's analyze the individual answer options in the question:\n1) False - neuroblastoma is a cancer originating from neuroblasts, cells that constitute elements of the sympathetic nervous system.  Neuroblasts give rise to the adrenal medulla, and the starting point of the abdominal tumor is the adrenal medulla.\n2) That's right, therefore scintigraphy using metaiodobenzyl guanidine - MIBG is useful in the diagnosis of this cancer.\n3) Error - neuroblastoma most often occurs in infants and young children.\n4) Truth. Ganglioblastoma most often occurs before the age of 5.\n5) Yes, cancer spread to bone with bone marrow suppression is possible.\nTherefore, the correct answer to the problem is C (2,4,5).\nSource:\nPediatrics - Tom Lissauer, Will Carroll; Polish edition 2019, p. 485", key: "C", consensusPct: 71, doctorsN: 3444, topic: "", konsyliumStem: "Wskaż prawdziwe stwierdzenie/a dotyczące nerwiaka zarodkowego (neuroblastoma): 1) najczęściej lokalizuje się w nerkach; 2) komórki nowotworu wykazują zwiększony wychwyt znacznika M" },
  325: { text: "Based on the symptoms described in the order, we suspect AOM in the patient - acute otitis media. Indications for antibiotic therapy in this condition include, among others: mentioned in the text - discharge of purulent content from the ear.\nIn such a situation\ntherefore, acute purulent otitis media should be diagnosed and empirical antibiotic therapy should be initiated.\nTherefore, the correct answer to the question is D.\nSource:\nPediatrics - Tom Lissauer, Will Carroll; Polish edition 2019\nhttps://www.mp.pl/artykuly/25461, poznanie-i-leczenie-ostrego-zapalenia-ucha-srodkowy-u-dzieci-aktualne-2004-wytyczne-american-academy-of-pediatrics-i-american-academy-of-family-physicians", key: "D", consensusPct: 90, doctorsN: 2960, topic: "", konsyliumStem: "3-letnie dziecko gorączkuje do 39,5°C od dwóch dni, od tego też czasu budzi się w nocy z krzykiem i ma osłabiony apetyt. Od pięciu dni u dziecka występuje wodnisty katar, a dzisiaj" },
  328: { text: "Heart rate 60/min in a 3-month-old infant\nit's bradycardia.\nTherefore, the correct answer to the question is C.\nSource:\nPediatrics - Tom Lissauer, Will Carroll; Polish edition 2019\nhttps://www.mp.pl/pediatria/praktyka-kliniczna/algorytmy-i-objawy-alarmowe/209942,wartosci-prawidlowe-czynnosci-zyciowych", key: "C", consensusPct: 91, doctorsN: 2944, topic: "", konsyliumStem: "Tętno 60/min u 3-miesięcznego niemowlęcia:" },
  329: { text: "According to the Recommendations for management of community-acquired respiratory infections (2016):\n(2) in children aged 4 months. - 5 years old with mild community-acquired pneumonia, antibiotics may not be used because most infections are viral (28-37%)\n(4) radiological examination does not allow distinguishing between viral and bacterial etiology of pneumonia - there are no clear diagnostic criteria for viral and bacterial infection\n(5) in children over 5 years of age with a type I hypersensitivity reaction to penicillins, a macrolide should be used as a first-line treatment for pneumonia.\nTherefore, the correct answer to the problem is A (2, 4, 5).\nWhat about the other answer options?\n(1) in children aged 3 weeks with pneumonia, the first-line treatment is hospitalization.\n(3) Listeria monocytogenes is one of the most common etiological factors of pneumonia in newborns, not in children over 5 years of age.\nSource:\nhttps://antybiotyki.edu.pl/wp-content/uploads/Reprezentacje/Reprezentacje2016.pdf", key: "A", consensusPct: 83, doctorsN: 3098, topic: "", konsyliumStem: "Wg polskich rekomendacji: 1) u dzieci w wieku 3 tygodni z zapaleniem płuc postępowaniem pierwszej linii jest baczne wyczekiwanie, bez antybiotykoterapii; 2) u dzieci w wieku 4. m.ż" },
  330: { text: "A child's score of 1 on the Tanner scale means that\nthe child does not yet show any signs of puberty.\nTherefore, the correct answer to the question is A.\nSource:\nPediatrics in the practice of a primary care physician, Anna Dobrzańska, 2022, pp. 412-413\nhttps://www.mp.pl/podrecznik/pediatria/table/042_7211", key: "A", consensusPct: 86, doctorsN: 3039, topic: "", konsyliumStem: "Uzyskanie przez dziecko stopnia 1 w skali Tannera oznacza, że:" },
  332: { text: "The following deviations are characteristic of type 1 diabetes:\n- increased proportion of glycated hemoglobin (1)\n- presence of anti-GAD antibodies in the blood (2)\n- glucosuria (3)\n- LOW insulin levels\n- Metabolic acidosis\nTherefore, the correct answer to the problem is B (1, 2, 3).\nSource:\nPediatrics in the practice of a primary care physician, Anna Dobrzańska, 2022, p. 381\nhttps://www.mp.pl/pacjent/pediatria/choroby/cukrzyca", key: "B", consensusPct: 82, doctorsN: 3125, topic: "", konsyliumStem: "W cukrzycy typu 1 u dzieci przy rozpoznaniu mogą pojawić się następujące odchylenia w badaniach laboratoryjnych: 1) zwiększony udział hemoglobiny glikowanej; 2) obecność przeciwcia" },
  333: { text: "Congenital adrenal hyperplasia can be detected in newborn screening by testing in a dry drop of blood\nincreased amount of 17-hydroxyprogesterone.\nTherefore, the correct answer to the question is D.\nSource:\nPediatrics - Tom Lissauer, Will Carroll; Polish edition 2019\nhttps://przesiew.imid.med.pl/wpn.html", key: "D", consensusPct: 76, doctorsN: 3192, topic: "", konsyliumStem: "Wrodzony przerost nadnerczy można wykryć w badaniu przesiewowym noworodka dzięki oznaczeniu w suchej kropli krwi:" },
  334: { text: "Let's analyze the individual answer options in the question:\n1) That's right - constipation is the most common cause of abdominal pain in children.\n2) Yes - macrogols are the drug of choice in children over 6 months of age.\nThese drugs are not absorbed from the gastrointestinal tract, and as a result, they remain in the intestinal lumen, exerting an osmotic and water-binding effect. They are used as laxatives.\n3) False - constipation is not caused by high but low fiber content in the child's diet.\n4) Mistake - Hirschsprung's disease can cause constipation - but it is not common.\n5) Truth. Treatment of functional constipation is long-term and often requires at least 2 months of pharmacotherapy.\nTherefore, the correct answer to the problem is A (1,2,5).\nSource:\nPediatrics in the practice of a primary care physician, Anna Dobrzańska, 2022, pp. 308-311\nhttps://www.mp.pl/pacjent/leki/subst.html?id=982", key: "A", consensusPct: 77, doctorsN: 3187, topic: "", konsyliumStem: "Wskaż prawdziwe stwierdzenia dotyczące zaparć stolca u dzieci: 1) są najczęstszą przyczyną bólu brzucha u dzieci; 2) lekiem z wyboru u dzieci powyżej 6. miesiąca życia są makrogole" },
  335: { text: "Calculation of the basic daily water requirement according to Holliday and Segar:\n1) children weighing 1-10kg - 100ml/kg\n2) children weighing 11-20 kg - 1000 ml + 50 ml for each kilogram of body weight over 10 kg\n3) children weighing >20kg - 1500ml + 20ml for each kilogram of body weight over 20kg\nPatient weighs 27kg: 1500ml + 7x20ml = 1640ml of fluids\nTherefore, the correct answer to the question is B.\nSource:\nhttps://www.mp.pl/pacjent/pediatria/lista/70761,zapowiedzowanie-na-plyny-u-dzieci", key: "B", consensusPct: 77, doctorsN: 1575, topic: "", konsyliumStem: "Zgodnie z formułą wg Hollidaya-Segara oblicz podstawowe, dobowe zapotrzebowanie na płyny dla zdrowego dziecka o wadze 27 kg:" },
  336: { text: "Features of complex febrile seizures include:\nfocal start (1)\npostictal paresis (3)\n>1 attack/24h (4)\nhistory of previous brain damage (6)\nTherefore, the correct answer to the question is C.\nThe remaining features (2) and (5) mentioned in the question are typical of simple febrile seizures.\nSource:\nPediatrics - Tom Lissauer, Will Carroll; Polish edition 2019", key: "C", consensusPct: 65, doctorsN: 1718, topic: "", konsyliumStem: "Wskaż cechy charakteryzujące drgawki gorączkowe złożone: 1) ogniskowy początek; 2) napad trwający < 15 minut; 3) ponapadowe niedowłady; 4) > 1 napad/24 godziny; 5) najczęściej wyst" },
  337: { text: "A typical set of antibodies for a patient who has had EBV infection in the past is:\nanti-VCA IgM negative\n(appear at the earliest, disappear within 2–3 months)\nanti-VCA IgG positive\n(appear within a few days of EBV infection, persist throughout life)\nanti-EA negative\n(appear in the acute phase of infection, usually undetectable after 3–6 months)\nanti-EBNA positive\n(produced after a few weeks/months, persist for life\nTherefore, the correct answer to the question is C.\nSource:\nAndrzej Szczeklik, Piotr Gajewski \"Interna Szczeklika\", Medycyna Practical, 2022, p. 2434\nhttps://www.mp.pl/interna/table/B16.18.1-1\n.", key: "C", consensusPct: 75, doctorsN: 1620, topic: "", konsyliumStem: "Do diagnostyki różnicowej zakażenia wirusem Epsteina-Barra (EBV) wykorzystywane są swoiste przeciwciała. Wskaż prawidłowy wynik badania przeciwciał w przypadku wcześniejszego zacho" },
  338: { text: "Let's analyze the individual answer options in the question:\nA) That's right. Nephroblastoma=nephroblastoma=nephroblastoma=Wilms tumor.\nB)\nFalse, the diagnosis of this cancer is based on imaging and histological tests after tumor removal, a biopsy is not performed.\nC) Yes, this treatment protocol is used in Poland (neoadjuvant chemotherapy and subsequent surgical treatment). There is also an American protocol (surgical treatment and subsequent postoperative chemotherapy),\nD) That's right, the prognosis for this cancer is good.\nE) Yes - \"bilateral renal tumors\".\nTherefore, the correct answer to the question is B.\nSource:\nhttps://www.mp.pl/podrecznik/pediatria/chapter/B42.71.13.27.3\n.", key: "B", consensusPct: 71, doctorsN: 1645, topic: "", konsyliumStem: "Wskaż fałszywe stwierdzenie dotyczące nephroblastoma:" },
  340: { text: "Among the vaccines mentioned in the question, the recommended ones include:\n2) TBE - vaccine against tick-borne encephalitis (paid)\n3) COVID-19 - COVID-19 vaccine (free)\n4) MenB - vaccine against meningococcal group B (paid)\n5) MenACWY - vaccine against meningococci groups A, C, W, Y (paid)\n6) IIV - inactivated flu vaccine (paid)\n7) LAIV - live, intranasal influenza vaccine (paid)\nHowever:\n1) BCG - vaccine against tuberculosis\n8) MMR - measles, mumps and rubella vaccine\nit's vaccinations\nmandatory\n.\nTherefore, the correct answer to the problem is C (2,3,4,5,6,7).\nSource:\nhttps://szkolenia.pzh.gov.pl/kalendarz-szczeien-2025/", key: "C", consensusPct: 73, doctorsN: 1663, topic: "", konsyliumStem: "Aktualny kalendarz szczepień na rok 2025 obejmuje oprócz szczepień obowiązkowych, szczepienia zalecane. Które z poniższych szczepień należą do grupy szczepień zalecanych? 1) BCG - " },
  341: { text: "Let's analyze the individual answer options in the question:\nA) True, the clinical picture is usually characteristic and allows the diagnosis of the disease.\nB) Yes. Alternatively, a single dose of 2 mg budesonide may be administered by nebulization.\nC) That's right - see B.\nD) **False. Adrenaline supply is used in the treatment of subglottic laryngitis, but the incorrect dose was given in the distractor - 0.1% adrenaline can be administered at a dose of 0.5 ml/kg body weight. (max. 5 ml)**\nE) True, it is a disease of viral etiology and does not require antibiotic therapy.\nTherefore, the correct answer to the question is D.\nSource:\nhttps://koroun.nil.gov.pl/wp-content/uploads/2017/10/ReprezentacjeA42009.pdf\n, p. 13", key: "D", consensusPct: 62, doctorsN: 1645, topic: "", konsyliumStem: "Wskaż fałszywe stwierdzenie dotyczące podgłośniowego zapalenia krtani:" },
  342: { text: "Let's analyze the individual answer options in the question:\n1)\nTrue, in the case of CAP in children treated on an outpatient basis, empirical antibiotic therapy is the standard.\n2)\nThat's right, if the child's condition is serious, blood culture allows determining the etiology of the infection and implementing targeted therapy.\n3) False - these are not routine procedures.\n4) False - sputum culture should be performed when the child's condition is serious.\n5)\nYes, this results directly from the NPOA recommendation.\n6) No - \"The presence of fluid in the pleural cavity in the course of CAP in children in an amount sufficient to allow puncture requires collection of the fluid for microbiological examination.\"\n7)\nTrue, this is not a routine procedure.\n8) False. This procedure is recommended for children under 2 years of age admitted to hospital due to community-acquired pneumonia, who are immunodeficient or to assess indications for implementing contact isolation.\nTherefore, the correct answer to the question is A.\nSource:\nhttps://koroun.nil.gov.pl/wp-content/uploads/2017/10/ReprezentacjeA42009.pdf\n, p. 21", key: "A", consensusPct: 58, doctorsN: 1759, topic: "", konsyliumStem: "Wskaż prawidłowe rekomendacje dotyczące postępowania w pozaszpitalnym zapaleniu płuc u dzieci: 1) nie zaleca się rutynowego pobierania krwi na posiew u dzieci chorych na pozaszpita" },
  344: { text: "Among the groups of drugs listed in the distractors, it is not a first-line drug in the treatment of hypertension\nalpha-blocker\n.\nThe remaining answers include the main groups of antihypertensive drugs used in first-line treatment also in children.\nTherefore, the correct answer to the question is E.\nSource:\nAndrzej Szczeklik, Piotr Gajewski \"Interna Szczeklika\", Medycyna Practical, 2022, p. 460", key: "E", consensusPct: 73, doctorsN: 1611, topic: "", konsyliumStem: "W przypadku rozpoznania u dziecka w wieku 16 lat, o wadze > 40 kg, nadciśnienia tętniczego I stopnia o etiologii idiopatycznej, jako lek pierwszego rzutu stosuje się wszystkie poni" },
  345: { text: "Let's analyze the individual answer options in the question:\nA) True - Categories A and B indicate the presence of general symptoms (B = general symptoms present, A = no general symptoms).\nB) True.\nC) True (as above).\nD) True (according to the Ann Arbor classification).\n**E) False - Ann Arbor's classification includes stages I–IV (no stage V)\nTherefore, the correct answer to the question is E.\nSource:\nPediatrics - Tom Lissauer, Will Carroll; Polish edition 2019, pp. 451-452\nhttps://chloniak.org/stopnie-zaawansowania-chloniaka/", key: "E", consensusPct: 62, doctorsN: 827, topic: "", konsyliumStem: "Wskaż fałszywe stwierdzenie dotyczące stadium klinicznego zaawansowania chłoniaka Hodgkina:" },
  346: { text: "Let's analyze the individual answer options in the question:\nA) True - some viruses can cause kidney damage (e.g. hepatitis B/C, adenoviruses).\nB) False - the most common prerenal cause of acute renal failure is hypovolemia (dehydration, shock, circulatory failure). Moreover, drugs (including sulfonamides) may cause acute renal failure - in a renal (not pre-renal) mechanism.\nC) True - it is a common cause of prerenal acute renal failure.\nD) True - \"pre-renal - the most common form in children.\"\nE) True - an example is the posterior urethral valve.\nTherefore, the correct answer to the question is B.\nSource:\nPediatrics - Tom Lissauer, Will Carroll; Polish edition 2019, pp. 415-416", key: "B", consensusPct: 69, doctorsN: 798, topic: "", konsyliumStem: "Wskaż fałszywe stwierdzenie dotyczące ostrej niewydolności nerek u dzieci:" },
  347: { text: "Let's analyze the individual answer options in the question:\n1) FALSE. Osteosarcoma is the most common primary malignant bone tumor in children and adolescents.\n2) TRUTH. The lungs are the most common site of osteosarcoma metastases (hematogenous).\n3) FALSE. MIBG scintigraphy is used, among others, in the diagnosis of neuroblastoma and neuroendocrine tumors, not in the case of bone tumors (here, scintigraphy, most often using a labeled technetium isotope).\n4) FALSE. Chemotherapy is used to treat osteosarcoma, including: on high-dose methotrexate (HD-MTX).\n5) TRUE (extraskeletal Ewing sarcoma).\n6) TRUTH. The prognosis in stage IV is poor, 5-year survival rate is approximately 15–20%.\nTherefore, the correct answer to the problem is D (2, 5, 6).\nSource:\nPediatrics - Tom Lissauer, Will Carroll; Polish edition 2019, pp. 444, 559-560", key: "D", consensusPct: 61, doctorsN: 838, topic: "", konsyliumStem: "Wskaż prawdziwe stwierdzenia dotyczące guzów kości u dzieci: 1) kostniakomięsak jest drugim co do częstości występowania guzem kości u dzieci; 2) charakterystycznym miejscem przerz" },
  348: { text: "The clinical picture described in the question (tumor in the renal output, spectacle hematomas, metastases to local lymph nodes) raises suspicion\nneuroblastomas.\nLet's analyze the individual answer options in the question:\n1) TRUE - Neuroblastoma secretes catecholamines - we will observe increased concentrations of VMA (vanillylmandelic acid) and HVA (homovanillic acid) in the urine.\n2) False - biopsy is part of histopathological diagnosis, indicated when neuroblastoma is suspected (confirms the diagnosis).\n3) False - the presence of N-MYC amplification in tumor tissues is associated with a worse prognosis, aggressive course and a high risk of recurrence.\n4) False - stage IVS (4S) refers to the situation: localized primary tumor (in children <1 year of age) with spread to the liver, skin and/or slight spread to the bone marrow. The described case meets the criteria for stage IV.\n5) False - the prognosis in the described clinical situation (advanced neuroblastoma with metastases and N-MYC amplification) is not favorable. \"The risk of recurrence is high and the prognosis for survival in children with metastases still does not exceed 40%.\"\nTherefore, the correct answer to the question is A (only 1).\nSource:\nPediatrics - Tom Lissauer, Will Carroll; Polish edition 2019, pp. 21, 452-454", key: "A", consensusPct: 59, doctorsN: 895, topic: "", konsyliumStem: "Do SOR dla dzieci trafiło 4-letnie dziecko z wykrytą w USG zmianą guzowatą jamy brzusznej. Zmiana zlokalizowana jest w rzucie nerki prawej, wymiary 8x7x7 cm, nie posiada torebki, n" },
  351: { text: "Let's analyze the individual answer options in the question:\nA) False - the maxillary and ethmoid sinuses are aerated (though not fully developed) from birth.\nB) That's right - the sphenoid sinuses usually begin to become aerated around the age of 3, and this process intensifies in preschool age.\nC) The frontal sinuses develop the latest. They begin to be visible in imaging tests, usually around the age of 6–7. years of age.\nD) False (see A).\nE) False - the mastoid process begins to aerate immediately after birth, and this process is clearly visible even in small children.\nTherefore, the correct answer to the question is B.\nSource:\nPediatrics in the practice of a primary care physician edited by Anna Dobrzańska, Łukasz Obrycki, Piotr Socha, 2022\nhttps://www.mp.pl/pacjent/pediatria/lista/61631,leczenie-zatok-u-dziecka-powiedz-rozpoczac", key: "B", consensusPct: 48, doctorsN: 163, topic: "", konsyliumStem: "Do izby przyjęć dla dzieci zgłosił się ojciec z 4-miesięcznym niemowlęciem z wodnistym katarem z nosa. Rodzic, korzystając z informacji dostępnych w internecie podejrzewa ostre zap" },
  352: { text: "Let's analyze the individual answer options in the question:\n1) False - hemophilia A is inherited in a sex-linked recessive manner, not autosomal.\n2) True - it is a deficiency or lack of factor VIII activity.\n3) False - hemophilia A is inherited in a sex-linked recessive manner, not autosomal.\n4) True, most cases of hemophilia concern people with a positive family history of this disease.\n5) That's right. Due to linking with the X chromosome, almost exclusively men are affected, and women are much less likely to suffer from it (e.g. in Turner syndrome or when the father is sick and the mother is a carrier).\n6) True - intramuscular and intra-articular bleeding (knee, elbow and ankle joints) are typical.\n7) False. Severe hemophilia B is diagnosed with factor IX (not VIII) activity below 1%. Activity part VIII < 1% defines severe hemophilia A.\nTherefore, the correct answer to the problem is C 1,3,7.\nSource:\nPediatrics, Tom Lissauer, Will Carroll; ed. ed. Polish: Teresa Jackowska, August Wrotek, ed. VI, Edra Urban & Partner, Wrocław 2023", key: "C", consensusPct: 50, doctorsN: 169, topic: "", konsyliumStem: "Wskaż fałszywe stwierdzenie/a dotyczące koagulopatii: 1) hemofilia typu A dziedziczy się autosomalnie recesywnie; 2) hemofilia typu A dotyczy niedoboru czynnika VIII; 3) hemofilia " },
  354: { text: "According to the vaccination calendar for 2026, for vaccination\nrecommended\nfor children, vaccinations include:\n1) flu\n2) hepatitis A\n3) meningococcal disease\n4) pneumococci\n5) human papilloma virus\n6) COVID-19\n7) chickenpox\nThere is a vaccination against pneumococci\nmandatory\n- not recommended.\nTherefore, the correct answer to the problem is A (1, 2, 3, 5, 6, 7).\nSource:\nVaccination calendar for children and adolescents for 2026\nhttps://szkolenia.pzh.gov.pl/kalendarz-szczeien-2026/", key: "A", consensusPct: 70, doctorsN: 148, topic: "", konsyliumStem: "Zgodnie z kalendarzem szczepień na rok 2026, do szczepień zalecanych dla dzieci należą szczepienia przeciwko: 1) grypie; 2) wirusowemu zapaleniu wątroby typu A; 3) meningokokom; 4)" },
  355: { text: "Let's analyze the individual answer options in the question:\nA) That's right - periodic fever, aphthous stomatitis, pharyngitis and adenitis. In addition to the above, joint pain, rashes, abdominal pain, headaches, vomiting and diarrhea may occur.\nB) False.The cause of PFAPA remains unknown.\nC) Yes - the onset of PFAPA symptoms usually occurs before age 5.\nD) True - PFAPA occurs worldwide and is not limited to specific continents/ethnic groups.\nE) Yes - the prognosis is good, the symptom complex usually disappears spontaneously after several years of life in the second decade of life.\nTherefore, the correct answer to the question is B.\nSource:\nPediatrics, Tom Lissauer, Will Carroll; ed. ed. Polish: Teresa Jackowska, August Wrotek, ed. VI, Edra Urban & Partner, Wrocław 2023\nPediatrics in the practice of a primary care physician edited by Anna Dobrzańska, Łukasz Obrycki, Piotr Socha, 2022", key: "B", consensusPct: 53, doctorsN: 152, topic: "", konsyliumStem: "Wskaż fałszywe stwierdzenie dotyczące wrodzonego zespołu autozapalnego - PFAPA u dzieci:" },
  356: { text: "Osteosarcoma is the most frequently diagnosed primary bone tumor in children and adolescents.\nLet's analyze the individual answer options in the question:\nA) That's right - these drugs are used in neoadjuvant chemotherapy.\nB) False - a good response to neoadjuvant chemotherapy often enables radical surgical treatment (destruction of micrometastases, reduction of tumor mass). This does not spread the cancer.\nC) Currently, most patients can undergo limb-sparing treatment; amputation is not the treatment of choice in every case.\nD) No - treatment is carried out in highly specialized pediatric oncology and hematology centers (not rheumatology centers).\nE) False. The prognosis strictly depends on the stage of the cancer and the histopathological response to preoperative chemotherapy.\nTherefore, the correct answer to the question is A.\nSource:\nPediatrics, Tom Lissauer, Will Carroll; ed. ed. Polish: Teresa Jackowska, August Wrotek, ed. VI, Edra Urban & Partner, Wrocław 2023", key: "A", consensusPct: 73, doctorsN: 146, topic: "", konsyliumStem: "Wskaż prawdziwe stwierdzenie dotyczące leczenia kostniakomięsaka u dzieci:" },
  358: { text: "NEC advancement classification according to the Bell scale:\nI - suspicion of NEC (body temperature fluctuations, flatulence, blood in the stool, non-specific distension of intestinal loops)\nII - confirmed NEC (I + no audible peristalsis, severe abdominal pain, pneumatosis intestinalis / gas in the portal vein.\nIII - advanced NEC (II + shock, DIC, and in case of intestinal perforation - pneumoperitoneum)\nLet's analyze the individual answer options in the question:\nA) That's right - pneumatosis intestinalis, i.e. the presence of gas in the intestinal wall, is a pathognomonic feature of NEC visible on X-ray.\nB) False meconium aspiration syndrome (MAS syndrome) is another disease that involves the aspiration of prematurely passed meconium into the respiratory system of full-term or post-term newborns.\nC) False. More than 90% of cases concern newborns born prematurely.\nD) False - coagulation disorders and DIC occur in the advanced stage of NEC - stage III.\nE) False - although NEC can occur early, the peak incidence usually occurs between the 2nd and 3rd week of life.\nTherefore, the correct answer to the question is A.\nSource:\nhttps://wczasniak.pl/nec/\nPediatrics in the practice of a primary care physician, Anna Dobrzańska, 2022", key: "A", consensusPct: 68, doctorsN: 160, topic: "", konsyliumStem: "Wskaż prawdziwe stwierdzenie dotyczące NEC (martwiczego zapalenia jelit):" },
};
